/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20211108-6","meetingId":"r03-cm11","date":"2021年11月8日","dateIso":"2021-11-08","committee":"区民委員会","time":"午後 １時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"第21回 品川区中学生の主張大会","agenda":"第21回 品川区中学生の主張大会","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１件伺いたいのは、いわゆる青少年対策という流れから来ているものなのか、そこを伺いたいと思います。教育委員会との連携だったり、学校の代表者をどうやって決めるのかとか、主催や教育委員会との連携についてお伺いいたします。","respondent":"川島地域活動課長","answer":"学校との連携ということで申しますと、そういったところともしっかりと連携しながら、会を進めているところです。毎年各学校で１名選出していただくことになっております。","id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"目的の(2)のところで、これまで２０回の間にこちらの主張大会で出た意見等がどういった形で企画・実施に反映されてきたのか、簡単に確認させてください。","respondent":"川島地域活動課長","answer":"こちらの主張は非常に心が洗われるというか、大人として忘れていたようなことを思い出すようなものです。そういった部分でかなりいい効果があったということで、事業に反映されていると考えているところです。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"地域の青少年全体に対して、大人として何ができるのかということを考える、モチベーションを上げる機会にもなっているのかなと考えています。今後具体的なところについても区として把握して、ぜひ生かしていっていただきたいと考えていますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"大崎駅東口指定喫煙所の移転および密閉型喫煙所の設置","agenda":"大崎駅東口指定喫煙所の移転および密閉型喫煙所の設置","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"数点お伺いします。そういったことを踏まえて利用人数はどのように考えていらっしゃるのかを説明を求めました。","respondent":"森田生活安全担当課長","answer":"これにあたり、足元に足跡表示をするのと、１０名制限ですけれども、また、ホームページでもそのような形で表示する。今検討中ではありますが、警備員の配置などにつきまして、多い時間帯には、ルールをお伝えした上で整理・誘導するなどといった部分も検討しています。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"結局周りで喫煙をする方がどうしても出てしまうと思うのです。混むような時間帯は常に指導員というか、警備員がいるような形にするのか、そこに関してもう一度考えを説明を求めました。","respondent":"森田生活安全担当課長","answer":"検討段階です。先ほどの繰り返しになりますが、まだ足りないところがありましたら、取締り等々厳しくやっていきたいと考えています。","id":"exchange-005"},{"speaker":"くにば委員","kind":"質問・要望","question":"利用時間を制限をする必要がなぜあるのかという部分で、午後８時以降は閉まってしまうので、生じてしまうのではないかと思う部分があるのです。午後８時よりも少し遅くしたほうがいいのではないかなと思うという部分、ほかに喫煙所がないから、その３点についてお考えを説明を求めました。","respondent":"森田生活安全担当課長","answer":"東口におきましては、会社勤めの方が多く利用されているということで、午後８時である程度の方の利用は終わるのではないかと考えております。ポイ捨て防止、また歩きたばこ防止に配慮して、今後も進めてまいりたいと思います。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"というのは、しなければならないというわけではなく、あくまで需要を見込んでその時間帯にするということかということで認識をお伺いしました。その２点、何の障害があって利用時間の制限をしなければならないのか、この辺の考え方を説明を求めました。","respondent":"森田生活安全担当課長","answer":"これにつきましては、裏面にコンテナ型の写真がありますが、なるべくガラス面を多くしたいと考えています。今の段階だと少し間口が、ガラスがそれほどないのですけれども、ガラス面を大きくした上で、中が見えるような形にしていきたいと思っています。","id":"exchange-007"},{"speaker":"くにば委員","kind":"確認","question":"最後に１点だけ伺います。どうやって指導していくか、大崎駅周辺における指導・過料は１,８９６件という数字がありますけれども、その辺についてお伺いします。","respondent":"森田生活安全担当課長","answer":"他自治体で駅前に設置しましたコンテナについて聞きましたところ、パーテーションを設置して、コンテナが設置されたことによって。これはプラスの考えでしかございませんので、マナーアップ、こういったところをしていきたいと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう検討をされているのか、何時から何時まで、また人数についてといった検討の中身を伺いたいと思います。夜８時以降どういう環境になるのか、どういう役割なのか、警備員の配置の検討の中身についてご説明ほしいと求めました。","respondent":"森田生活安全担当課長","answer":"これは３時間だけ警備というのは、配置するならば１日とか、そういったことをいろいろと加味して今検討を進めているところです。いろいろなものを加味しながら設置までに考えて、実施していきたいと思っています。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"経費についてもお伺いしたいのですけれども、誘導員、設置費用や維持管理について幾らかかるのかそれぞれと伺いたいと思います。その設置費は補助金なのか、区の一般財源なのか、その辺の財源構成についてもご説明ほしいと求めました。","respondent":"森田生活安全担当課長","answer":"経費は１基が大体１,７００万円です。維持経費については約２５０万円です、フィルター交換は……。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"１基１,７００万円で、年間の経費は２５０万円、全額区の負担ということです。は１カ所を決めて、費用についてもしっかり検討していただきたいと、要望だけしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ある程度設備の方針が決まっていることがあるのかどうかというところが１点、もう１点が、大田区は２カ所ありますね。区としては、大崎駅のところは路面の誘導ブロックなどはお考えになっているかどうかということだけ、２点お伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"来年度も閉鎖している場所についてどうにか適地を探しまして、進めていきたいというのが１点です。今後状況に応じては点字ブロックも考えていきたいと思っているのですが、今現在は考えてございません。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"密閉型喫煙所ということですけれども、吸い殻の処理はどうなるのですか。自分で持っていって捨てるのか尋ねました。","respondent":"森田生活安全担当課長","answer":"今までどおり中にたばこの灰皿を設置しますので、吸い殻はそこに捨てていただく形になります。","id":"exchange-014"},{"speaker":"藤原委員","kind":"意見","question":"その条例を担保にするならば、製造・加工する業者にその辺のことも、金銭的なことも支援してほしいというのは、区としては言えると私は思うのです。","respondent":"森田生活安全担当課長","answer":"私どもが今区内に設置している喫煙所につきましては、ＪＴ、そういったものでご協力を賜っているところです。喫煙につきましても、引き続きそういったところのご協力をいただきながら実施をしてまいりたいと考えています。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"ちなみにこのあたりには防犯カメラはあるのでしょうか。防犯カメラがあるならば、犯罪抑制のために防犯カメラをつけていただきたいと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"警備会社と検討していますが、午後８時以降中に人がいたりしたときなどは、防犯上も安全にしていきたいと考えています。今後も様々なものをお聞きしながら、安全を守りつつ、喫煙所を設置しまして、皆様が快適に暮らせるようなまちづくりにつなげたいと考えております。","id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そこら辺の確認がもう１点です。予算もあることですので、どういう時間帯にどういう人が来ているのかどういう人数なのかという調査をぜひしていただきたいと、要望します。","respondent":"森田生活安全担当課長","answer":"状況を踏まえて、いろいろなことを研究してまいりながら、安全に加味するような形で設置を考えていきたいと考えています。私どももこれが初めての設置ですので、いろいろな意味で考えながら、よろしくお願いします。","id":"exchange-017"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"見ている限りではやはりとても多くの方が吸われているので、そこら辺はまた今後もしっかりと調査をしてほしいと求めました。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"西村委員","kind":"質問","question":"皆さん大分聞いてくださったので、手短にお伺いさせてください。過料は１,０００円だったかなと思うのですけれども、改めて伺わせて下さい。","respondent":"森田生活安全担当課長","answer":"過料についてはプラス５件でございました。都からはオリンピックまでの間に設置ということで出てはおりましたが、現在はもうなくなっておりますので区が全て支出するという形になると思います。","id":"exchange-019"}]},{"id":"topic-03","title":"総合区民会館（きゅりあん）の大規模改修に伴う休館等","agenda":"総合区民会館（きゅりあん）の大規模改修に伴う休館等","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"あのときは報告だったか、そのときに伺ったのですけれども、そのほかについては１年弱工事ということで使用料が入ってこないということになります。そうなると、指定管理料はどういう変化し、それにどう対応するのかを伺いたいと思います。","respondent":"篠田文化観光課長","answer":"令和５年１月中旬まで閉まるということですので、２カ月だけ開くことを予定していますので、２カ月分ぐらいの利用料ということです。今回の場合はコロナの対応と違いまして、あらかじめきちっと予定が分かっていますので、指定管理料を計算し対応するものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"利用料として入ってくるものは減るわけですから、差引きで指定管理料が決まるということです。つまり、入ってこないことは明らかなわけだから、指定管理料としては結果的に増えるということになるのか、ご説明いただけますか。","respondent":"篠田文化観光課長","answer":"例えば舞台の関係でいけば、閉まっているので、当然舞台はできない。この後の予約に対する対応とか、舞台装置の関係で、一定程度の人数が必要になってくるということもあります。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"改めてお伺いさせていただきたいのだけれども、結局大ホールは令和４年２月１日から令和５年９月中旬まで改修します。その下の令和４年２月１日から令和５年１月中旬まで閉めるわけだけれども、ゼロになるのか、分かれば数字を教えていただきたいです。","respondent":"篠田文化観光課長","answer":"きゅりあんの場合、２億円以上と見込まれますので、これが２カ月分だけということになる。２カ月分ですので、恐らく２,０００万円程度しかが入ってこないのではないか、そういった金額だったと記憶しています。","id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"きゅりあんがなくなるわけではなくて休館するわけですから、私が伺っていたのは、確認なのですが。今雇っている方たちの雇用は守られると聞いていたのですけれども、そのとおりでいいのか、質問します。","respondent":"篠田文化観光課長","answer":"ただ、休館中とはいえ、例えば、休館明けの分、先の予約等への対応もありますので、結構人数が必要になるということです。それぞれの再委託の事業者がお考えになっていると聞いておりますので、今の方がそのまま首になってしまうことにはならないと考えているところです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"２億円近いお金が入ってこないとしても、文化振興事業団として今までの実績、雇用の確保だけは維持していっていただきたいと私は思うのです。だけれども、雇用の確保、今までのキャリアを尊重していっていただきたいと思うので、そこは改めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"１点お伺いさせてください。そういった声を受けて、交付会場の拡大はどんどんしていっていただきたいので、認識や課題をどうぞ説明を求めました。","respondent":"木村戸籍住民課長","answer":"現在検討しているところでは、ある程度そこをクリアして進められそうな算段をしています。今後も拡大に向けましてさらに研究・検討を進めてまいりたいと思っているところです。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"その２点を伺いたいです。どんどん導入していっていただきたいという部分と、どんどん広げていただきたいという思いがあるのですが、その２点を伺いたいです。","respondent":"木村戸籍住民課長","answer":"パスワードとかも入れていただきますので、比較的柔軟に対応できるところではありますが、一定程度の大きさが必要だということです。正直それほどのネックではないので、調達して配置すれば済むぐらいのレベルの話ですので、こちらはネックという意識はあまりございません。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"ありがとうございました。スペース的なネックがあると思うのですが、そこに関しては、何か工夫をしていただいて、ぜひとも拡大していただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"全国システム標準化への対応ということで、今、国が旗を振って各自治体に対応を求めているところであります。もっと言うと、区の独自事業がどう変わっていくのか、その点についてご説明ほしいと求めました。","respondent":"木村戸籍住民課長","answer":"システムに合わせて仕事を変えていくという話がよくありますけれども、実際はそういう形で進めていくので、今まで独自でできていたことができなくなるという認識はございません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、この間でいうと、コロナ禍の下、区民の暮らしを応援しようということで、今回品川区で１人３万円の給付金を出しました。例えば、３万円の独自給付金など、改めて確認させてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"ないという認識でよろしいと思います。今回標準化を目指すという部分は、これから先また区で独自事業を何か展開するというときに、そのことで大きな支障があるということではございません。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"国が実際に標準仕様を求めていく際に、今後これが拡大していくと、区独自の事業にブレーキがかかる弊害が生まれてくる危険があると私は思っています。個人情報の保護や丁寧な対応を進めるためにも区直営に戻すべきだと、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"ワクチンパスポートについてお伺いするのですけれども、２３区のほかの自治体では、保健所がやっているところが多いと思うのです。保健所に戻せという意味ではなくて、戸籍住民課で発行することになったのか、お伺いしたいのが１点です。","respondent":"木村戸籍住民課長","answer":"お見えになったらもうその場でご案内するという形を取ったというところで、初期対応の部分でのサービスアップにつながったところがあります。そちらに仕事の中身をシフトしていけたというのが大きな成果だと考えています。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"今２点質問させていただきましたが、本当に時宜にかなった対応で、私はすばらしいと思います。もしできたら、夏服も作ってあげてくださればいいと私は思うのですけれども、その辺はいかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"今回本区で今やっていただいている事業者は、事業者側からやらせてくださいという話がございまして、そちらで持ってもらっているところがあります。今の委員の話も今度伝えながら、これから来年の夏に向けてどうしていくかというところは考えてまいりたいと思っています。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"業務は内容ですから、区民の感情としてそれほど怒られる、もちろん１,０００万円とかかからないでしょう。予算をつけてと予算特別委員会では伺わないですけれども、ここでちょっとお話しさせていただいたので、ぜひご検討くださることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"３番の窓口サービスのさらなるレベルアップ検討のところと、ワンストップサービスの検討というところなのですけれども、区民の方の求めが多様になっていると先ほどのご説明ではあったのですけれども、具体的にはどのようなお声が今入っているのかというところをまずお聞かせいただけたらと思います。","respondent":"木村戸籍住民課長","answer":"担当の職員がご説明する場合もありますけれども、今の状況では、スペース的になかなか難しいところがあります。こうしてくれというお声はないのですけれども、私たちが仕事をしていて、それはかなり実感として持っているところです。","id":"exchange-034"},{"speaker":"横山委員","kind":"提案","question":"一般質問とかで、例えば、お悔みコーナーみたいなもののご提案されているかと思います。この間、まずスタートしやすい部分なのかと私は感じているのですけれども、そのあたりの現在の検討状況を教えていただけたらと思いますとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"全部スペースのせいにするわけではないのですけれども、ほかの方との距離を置いて相対して行うオペレーションまで考えますと、なかなか難しい。","id":"exchange-035"},{"speaker":"横山委員","kind":"意見","question":"例えば、ＤＶを受けた方の加害者側の方が戸籍の窓口の後ろにいらしていて、そこでやり取りを聞かれる心配等があるといけないと思っています。様々な配慮が必要な方に関しては、今も対応いただいているかと思うのですけれども、引き続き検討を進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西村委員","kind":"提案","question":"区民にとっては、今現在求められているものでありますので、そこら辺のご対応をぜひ早急に進めていただきたいという思いでいっぱいであります。会派としても、そこは要望していますけれども、デジタルデバイドでの対応の具体的な取り組みについて、もう少しお知らせほしいと求めました。","respondent":"木村戸籍住民課長","answer":"マイナンバーのデジタルデバイドの対応なのですけれども、今検討しておりますのは、窓口まで来ていただくことはどうしても必要になるのです。","id":"exchange-037"},{"speaker":"西村委員","kind":"意見","question":"１つの窓口に行ったときに、そこをもう一歩広げるということで、具体的に実を結んでいただきますようにお願いしたいと思います。それも広がっていくのかなとも思いますので、そこら辺もぜひ早急に実現できますよう取り組みをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"そのことで１点、本当に必要な方に届いているのかどうかという議論もあったと思うのですけれども、現在品川区としてはどのように対応されているのかというところを確認させていただきたいと思いました。","respondent":"木村戸籍住民課長","answer":"基本的には個別に相談をいただいて、対応するという形で行っております。ざっくりした言い方で申し訳ございませんけれども、そういうご事情をくんだ形の対応を取らせていただいています。","id":"exchange-039"},{"speaker":"西村委員","kind":"質問・要望","question":"これまで区議会の方から申請時の混雑についていろいろな要望をしたり、４月などの季節性によって、来庁する区民の方がとても多い課だと思います。職員の方たちに負担がかかってしまうのではないかということを心配していまして、軽減できるようにしていただきたいという要望です。","respondent":"木村戸籍住民課長","answer":"ある程度効率的に業務が進められて、どんどん変えていこうという形で、職員発想でいろいろやっているところです。それに合わせた人員配置はなかなか厳しいところもありますので、ぜひ知恵を結集して、何とか乗り切ってまいりたいと考えています。","id":"exchange-040"},{"speaker":"西村委員","kind":"質問・要望","question":"改めて伺うと、改めて思いましたので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。現状は使えないということで、また品川区としてホッケー競技場の使用についてどのように要望されているのか、教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今申し上げたホッケー教室も、最後に説明したＵ－１０の品川カップなども、みんながやりたい気持ちになるのを狙ってやっていきたいと考えています。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":35352,"voices":108}},{"id":"r03-20211108-7","meetingId":"r03-cm11","date":"2021年11月8日","dateIso":"2021-11-08","committee":"厚生委員会","time":"午後 １時００分～午後 １時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、区内医療機関等と第５波への対応について情報共有ということで、情報共有というのはどのようなものだったのか。第５波がどのような感染状況だったのか、それで対処法はどうだったのか、行ったのかを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"第６波へ向けての対応が全てその場で決まったわけでは決してございませんで、現状、協議が継続しているところになります。当日先生方にご説明した、その辺もこのたび資料にまとめましたので、そこを含めてご説明させていただきたいというふうに考えております。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"大変な思いをされてきたと思うのですが、現状の勤務状況、残業の状況や職員体制がどうなっているのかということについて伺いたいと思います。それからあと、これから所管事務調査でいろいろと詳しくは教えていただけると思うのですけれども、ちょっと教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"そして、新型インフルエンザ等対策連絡会ですが、かなり以前からで、そこを踏まえて今後ご説明しますが、基本は年１回、これまで開いております。それに対しての品川区の対応ですが、品川区保健所が対応している数については一切変更ございませんので、その旨併せてご説明します。","id":"exchange-002"},{"speaker":"若林委員","kind":"確認","question":"では確認だけ、端的にします。この(3)のまん延防止対応の1)の「９月２０日以降、このような出張検査実施の判断の部分について、２つお願いいたします。","respondent":"鷹箸保健予防課長","answer":"昨年の５月から全部を合わせてですので、その中で必要な場合に、昨年の第２波の頃から必要なときに先生方にお願いをしていたという形になります。「している」というのは、ＰＣＲ検査センターが始まってからこれまでの期間にお願いをしていると、そのような形の表現になります。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"逆にこのような対応で辞めてくれというようなことを言われたとか、そのような相談というものは、保健所等にはあるものなのですか。ないものなのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、鷹箸保健予防課長","answer":"現時点でワクチン担当のほうには、そういったご相談は入っておりません。 感染症予防のほうの担当にも、ワクチンを打っていなくて、その影響でといったようなご相談は特段ありません。そういったご相談はありますけれども、ワクチン関連のそういった相談は、私どもはまだ受けたことはございません。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"確認","question":"それからもう一つは、（資料の）表側の(2)の患者対応というところの部分が、今はもうほとんどないということという確認でよろしいでしょうか。もう１１月ですので、このような方がいない状態だと、保健所のほうではこういった対応をしないで済んでいるという認識でよろしいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"２回目に届け出た先生に、具体的な対応はさせていただいているとともに、その場合の対応はしています。そういった後追いの対応を頼まれることはありますが、業務量についても激減したということが言えると思います。","id":"exchange-005"}]},{"id":"topic-02","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"６割というところでは、そのような人への対応というのですか、対応されていくのかを伺いたいのですが。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"は１２歳の誕生日を迎えた方につきましては、引き続き誕生日を迎える前月末に接種券を発送いたしますので、我々のほうでも認識をしております。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。アストラゼネカの１００人分というものだけになっているのですけれども、これはこういった少しずつな形で今後も入ってくるということなのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２回目接種の方の日付を見越しまして、打てるような数は確保できるように、こちらのほうで計算を進めております。それからアストラゼネカ製、皆さんが打てる分のワクチンは確保できているというふうに、こちらのほうでは準備を進めているところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それで、何かそのような方も、今度の１２月の枠のところではできるということなのでしょうか。それで、今までもそのような枠というものはつくられていたのか、ちょっとその点について伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"開始当初は年齢別に接種が進んでいたこともありまして、８月以降、皆様の予約が開始されて以降は。先ほどもご説明いたしましたけれども、１２月以降、かかりつけ医ではなくてもご相談いただくことはできるかとは思います。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから駐車場つきの大井競馬場だったらできますよという形での、コールセンターでの案内までぜひしていただきたいなと思うのです。受けられるような案内や体制というものがまだまだ必要だと思うのですけれども、その点についての考えを説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"副委員長ご指摘のような対応が取れるようにということで、委託しておりますので、その辺りについて再度確認はさせていただきたいと思います。今後調整を進めてまいりますので、１２月、何とか接種していただければというふうに考えております。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、区内でまだ受けていないけれども受けたいという方のためのワクチンというものは、今何人分くらいは確保されていると考えたらいいか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"何人分というのがちょっと、今すぐ計算はできませんが、数千人分は間違いなくあります。３,０００人、４,０００人、５,０００人分ぐらいはあるというようにご理解いただいて結構だと思います。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば予約は１か月前ぐらいから受けるのかどうか分からないけれども、１か月前とするのか。答弁は要りません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"ちょっと国の動きなどが分からないのでお伺いしたいのですけれども、それは打てる方が多くなったからいいのですが、例の発送です。厳しい状況になるのかもしれないですが、その辺についての現状での見込みというか、検討状況を教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"検討を始めたというところで、それは一切お答えができませんという回答だったので、幾ばくかはつくる予定があるようですけれども。ただ、いろいろな方法を今検討しながら、皆さんに少しでもストレスがかからないような予約ができるような体制づくりを今現在検討して。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"すみません、１点だけ。２回目は東京都が接種券など、接種会場はどういった形になるのか、教えていただきたいです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２回目の接種が５月３１日までに終わっている方を抽出して、その方々に１１月１８日に発送するという形で考えております。順次どのように発送していくかという検討は再度進めていきますが、一応分割して進めていければというふうに考えております。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3610#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":17974,"voices":58}},{"id":"r03-20211108-8","meetingId":"r03-cm11","date":"2021年11月8日","dateIso":"2021-11-08","committee":"建設委員会","time":"午後 １時００分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件整理しています。","topics":[{"id":"topic-01","title":"令和３年陳情第５１号、戸越公園駅周辺のまちづくりについての陳情","agenda":"令和３年陳情第５１号、戸越公園駅周辺のまちづくりについての陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"２つ目が、３番目が、規制緩和の都市計画から持続可能な都市計画に改めることを求めています。補助２９号線も通りますけれども、取消しを求める裁判ですけれども、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"戸越公園をオアシスのようなまちにしたいのかですが、先ほどご説明したように、区としてもビジョンをこういった形で掲げてあります。補助２９号線は東京都も土地のほうのご協力を進めているということも聞いてありますし、どのようなまちにしていくかということを考えていくです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"２９号線のところは、この再開発事業の促進を続けるのかということですので、そこを伺いたいと思います。生活しやすいまちづくりになると考えているのか、都会のオアシスになると考えているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"こちらの事業を先ほどもご説明したとおり、この再開発事業を進めるべきだと判断して、今進めているです。区はオアシスのようなまちづくりになる（と考える）のかですが、この再開発事業がまちに寄与すると考えて、地域と共に進めているです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そしてそのときに、近隣住民の風害ですとか、日照、採光など、どういった被害があるとお考えなのか、伺いたいと思います。結局は追い出されてしまうということでよいと考えているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"風害または日影等々の部分ですが、この前の８月、中高層説明会を組合で行ってあります。なるべく地域に細かい丁寧な説明をして、環境の変化というのを皆様にご説明していきたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"１棟だけの日影が減少しても、２棟建てばその分、そういった点ではどのように考えていらっしゃるのでしょうか。成り立たないというのであれば、事業計画を示して、しっかり説明していただきたいと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"３点目、そういった形に対して補助金が出せるとか、一定のルールがあります。もっと区が補助金を出せばいいのではないかですが、一定のルールがあって、そういった補助金は出しています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"階数を下げてほしいというのは、私は別に補助金を出してほしいということではなくて、ある程度の利益を見込んでやっていらっしゃると思うのです。そういった利益は出るわけですから、そういったところでも事業は成り立つのではないかと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"そこの部分につきましては、歳出・歳入共々同額のお金、要するに、組合に対しての利益は発生しないです。利益につながる部分ですので、社外秘につながりますし、区としても把握はしていないです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"それを減らしてでも、階数を減らしていくべきではないかということなのですが、改めて伺いたいと思います。ゼネコン、デベロッパー、コンサルの利益のために再開発を進めていくのはやめるべきだと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"継続的な企業運営というものも、民間企業は当たり前のように、そこは死守しなければいけないところです。いかに民間活力を活かしながらまちづくりを進めるかというところで、この（戸越）五（丁目）の１９（番地区）は再開発事業を行ってきているです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"課題が様々あるという話でしたけれども、解決する方法があるのではないかと思うのですが、いかがでしょうか。再開発という選択肢が選ばれてしまうということだと思いますが、その点、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"再開発でまちづくりをしていきたいというところで進めてきているので、行政もこの（戸越）五（丁目）の１９（番地区）、一緒に進めているです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"なので、ここはしっかり区としても、一旦立ち止まって考えるべきではないかと思いますが、いかがでしょうか。補助金を出しているということは、そちらを誘導しているということだと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"補助２９号線も踏まえて、または自分たちがどのように戸越公園に住み続けようかと考えた中で、これを止めるような考えはございません。いろいろ区域を分けてまちづくりを進めておりますので、こういったビジョンをつくり、それに対してまちづくりを進めているです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"コロナ対策にこそ使っていくべきだと思いますけれども、この再開発事業を一旦中止するべきだと思いますが、いかがでしょうか。１か所に多くの方が集中するということで、見直しが必要なのではないかと思いますが、区の考えを伺います。","respondent":"中道まちづくり立体化担当課長","answer":"まちづくりというのも１年、２年でできるわけではなくて、広域的な観点を見ながら税金の使い方というのは考えていきたいと考えています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、実際の商店街がある、道幅６ｍの商店街が、陳情にもありましたけれども、温かみのある商店街をつくり出していると思っています。今の街並みのよさを活かしたまちづくりを進めていくべきだということを要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"なので、そこはどういう考え方でまちづくりをやっていくのでしょうか。その反対する中で、区のスタンスとして、区の考え方として、どうまちづくりをしていくのですかということはいかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"この再開発を進めるに当たりまして、戸越公園だと、８町会、２商店街が加盟しているまちづくり協議会というものがあります。そうした形で地域の方と話を進めて、再開発でビルというのは、一定程度理解は示していただいていると認識はしています。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"２、３というゾーンがあって、やってしまうという形ではないですか。２、３と要旨がありますが、これは今の現状において改善できるのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"（戸越）五（丁目）の１９（番地区）、資金計画というのも一定程度、もちろん固まっているという状況です。建築確認も取得していますので、こうした状況なので、階数を低く、建物のボリュームとかを変更するというのは、今の状況だとなかなか難しい状況です。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"まちをどうするのかという話をしているのだから、そうしたら、広く伝えていかないといけないと思うのです。そこは陳情の内容を真摯に受け止めて、今後に活かしていけたらと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"芹澤委員","kind":"質問","question":"そういった状況で、この１枚の陳情書をもって再開発反対とするのは、できかねるかなという思いがあります。ただ、毎回お話ししていますが、再開発に関する情報提供であったりとか、話合いの場のサポートというのは、引き続き行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"一つの有力な選択肢であるとは思っておりますので、民間活力を、その際にはどうしても利用しなければいけない。その民間も従業員を抱えているわけですから、ぜひ善処していただきたいということは、要望として付け加えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"１０年間、１５年間の部分で変化があるということを、しっかりと行政の方も受け止めてほしいと求めました。あるいはここにお住まいの方に不公平が生じない、公平性を持った取扱いをしていただいて、いいまちづくりをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"のだて委員","kind":"意見","question":"戸越公園駅周辺のまちにある商店街などを壊す計画になっております。一極集中を加速させる超高層ビルは必要ないと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば東京都に言っていくとか、国に求めていくとか、今はそういうのがないと思うのです。今度は平面化というのでしょうか、見直しを図る時期もそろそろ来ているのではないかと強く感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"ほかの区営住宅についても設置の検討をしたのでしょうか。設置できないということであれば、その理由はどういったことなのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"今回設置されていない４つの区営住宅ですが、そのうち３つ、エレベーターが設置できない状況です。大規模改修等の区営住宅全体の計画の中で検討してまいりたいと考えております。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"西大井のほうは構造上というのでしょうか、２戸ずつの階段があるという問題で、できないということでした。協議がなかなか難しいということがあったのですが、それはクリアできて、今残っている課題は日影のみということか尋ねました。","respondent":"竹田住宅課長","answer":"こちらは、委員ご指摘のとおり、複合施設ですので、日影規制以外にも、他の施設との調整ということが大きな課題でございまして、そちらについては、まだ解消されておりません。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"日影だけではなくて、そこの課題がまだ残っているということですね。具体的に言うと、保育園や図書館との協議というか、課題というのは、どういったことがあるのか尋ねました。","respondent":"竹田住宅課長","answer":"保育園は、こちらの地区はまだ子どもの数が減少するという見込みはない中で、面積から許容される最大限の人数をお預かりしている可能性があります。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"今のお話だと、図書館のほうは、何か工事したときには、移転というか、代わりの施設を設けなければいけないということですか。絶対に図書館を移動させなければいけないということになるのか伺いたいのと、スペースが少なくなるという可能性があるということなのか尋ねました。","respondent":"竹田住宅課長","answer":"当該住宅の立っている現状から考えますと、北側に設置するしかないという状況だと理解しております。余地がないような状況となっておりますので、その中で工事するのは、大変いろいろ課題があると考えております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"陳情としてはエレベーターを設置してほしいというものですが、区営住宅に入った後に病気になったりして、階段は上れないという方もいると思うのです。ここの区営住宅は１階はないですけれども、１階に移動したりという住み替えというのができるのではないかと思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"そのうち第５項に、同居者の人数に増減があった場合や、病気等によって日常生活に身体の機能上の制限を受けることになった場合という規定があります。第６項には、こういった規定に沿いまして、居住者のお声をお聞きしています。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"声をお聞きしているということは、実際、この陳情されている方の声も聞いているということなのでしょうか。状況がある意味、変わったということだと思うのですが、住み替えには該当するのかどうか伺いたい。","respondent":"竹田住宅課長","answer":"変更を希望する方については、住宅変更申請書をご提出いただくようになっております。既に入居されている方と、これから入居をご希望されている方の公平性の観点から、大変慎重に行わなければならないと考えています。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"生活に支障が出ているということですので、住み替えを進めていってほしいと求めました。二葉一丁目の区営住宅を含めて、エレベーターのない区営住宅の建て替え計画というのはあるのか尋ねました。","respondent":"竹田住宅課長","answer":"適切な時期に効率的な修繕を行って、建物の老朽化および劣化による事故等を未然に防ぐということとともに、耐久化を図るように進めているところです。建て替えにつきましては、区営住宅全体の計画の中で検討していきたいと考えております。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"全体の中で建て替え計画を考えていきたいということですが、その全体の中での計画というのはあるのか尋ねました。","respondent":"竹田住宅課長","answer":"検討した計画というのはありますが、地域の特性等を勘案しながら決まっていくものと考えておりますので、区営住宅全体の計画の中で検討していきたいと考えております。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"立てない理由というのはあるのでしょうか。そこを伺います。","respondent":"竹田住宅課長","answer":"先ほども申し上げましたけれども、老朽化の度合い等によりまして、内部での案というものは持っております。区営住宅は１３住宅のうち、約８割が築４０年以上となっておりますので、全体の中で検討していくことも大事だと考えております。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこの確認と、そうであれば、急いでいただきたいと思うのです。２６号線道路の工事のために使われておりますけれども、日影の問題もクリアできるのではないかと思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"いずれは建て替えるべきものと考えておりますが、その時期がいつなのかというのは、今は申し上げられない状況です。今はそちらは公園という用地になっておりますので、住宅と一体的に活用できるのかどうか、そこも含めて考えていきたいと思います。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"公園も含めて、検討するということですので、ぜひ建て替えを進めていくようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"それを放置していていいのでしょうか。区の考えはどうなっているのか尋ねました。","respondent":"長尾建築課長","answer":"日影の規制自体が昭和５３年から、都の条例に基づいて規制がかかった状態になっております。それよりも前にできている建物ですので、既存不適格という言い方になりまして、違法なものではございません。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"具体的にやっていかないと、区営住宅は、事故が起きたらどうするのですか。修繕はしていると言っていても、事故が起きたら品川区はどうするのか尋ねました。","respondent":"竹田住宅課長","answer":"それから、事故ということですが、定期点検等により、常に状況を把握して、適切な時期に効率的に修繕・改善を実施しています。区の大事な財産ですので、耐久性の向上を目的に、計画的に修繕等も行っている状況です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"構造自体は変えられないですから、そういう意味では、そのぐらいはしていかなければいけないことなのではないか。どういう対処をするようにしていくのかというのは、区のスタンスをきちんと皆さんに知らせていただきたいと意見を申し上げて、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"芹澤委員","kind":"質問","question":"今ご説明をいただいて、現実問題、これからエレベーターの設置というのが実質不可能であるというお話を理解しました。様々ご議論を内部でお話しいただいて、早急に解決するように望んで、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"私どもの会派には、エレベーターが生活上必要であるという訴えのお声は、ほかにもたくさん届いております。建て直すということを、今後しっかり検討していただきたいということは強く要望させていただきまして、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"高齢化が進んでいく上で絶対数が増えるわけですから、このような要望は、まさにもっと増えていくのではなかろうかということが予想されます。行政も利用者に寄り添うような扱いというか、寄り添う、気づくというような行動を取ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"住まいは人権を保障する土台であり、今回の公的住宅という性格からも、区民の大変な生活実態を改善する必要があるため、採択です。エレベーター設置ができないのであれば、別の支援策を取るとともに、建て替えを急ぐことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"すぐに設置していただきたいと要望したいところでありますが、これは申し訳ありませんということになるかと思います。住民たち、そこはいろいろな関係所管と話をされて、対処していただきますようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-02","title":"羽田空港の機能強化","agenda":"羽田空港の機能強化","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"お聞きしたいのは、１日ごとのＬｄｅｎを算出して、夜間とか早朝とかの重みはつけていると思うのです。その後、パワー平均するというのはどういうことなのかと思ったので、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"飛行場ごとという言い方をさらに詳しくご説明しますと、北風のときもそうですし、離陸することも全て含んでというところになります。説明がなかなか難しくて申し訳ないのですが、それを３６５日で平均化する、Ｌｄｅｎが出されると。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点目のところで、南側ルートの新ルートで来たときに、上を飛ぶわけです。確認させていただきたいのと、３６５日を平均化したというのは、年間の間でもＬｄｅｎみたいに重みづけをしているということなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"私の認識だと、年間Ｌｄｅｎを（算出）するときは、時間帯の重みづけというのはやっていないと思います。それは日のほうでされておりますので。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認ですけれども、もともとの深夜や早朝の重みづけはしていなくて、年間のところで同様のパワー平均というのをしているということですか。月単位のＬｄｅｎというのは公表していただきたいと思うのですが、公表はしないのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"パワー平均についての説明が分かりづらくて申し訳ないのですが、１日の、その重みづけを反映しているという理解です。それから、基本的には、着陸の新ルート以外の航空機騒音も拾うことによって、私の認識ですと、年間Ｌｄｅｎというのは上がってくるのではないかと。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"基準値以内だから被害がないということではないということですから、被害を改善していくことが必要だと思うのですが、いかがでしょうか。そのためには、羽田新ルートを中止していく、区として反対表明していくということが、大きな力になると思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"運用開始前から運用開始後も、区としては特に騒音環境軽減に向けた取組というのは、国に対して求めてきております。その対応を今後考えますとかということでは当然ないわけで、これまで求めてきた取組を、今後一切行いませんということでもございません。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"多分これは国に言ったら、「もう基準値以内ですから大丈夫ですよ、我慢してください」で終わってしまうのではないですか。そのように私は非常に危惧するところなのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"年間で行いなさいというところになっておりますので、その根拠をもって区民に提示をするというところが、区の役割ではないかと考えています。ホームページですとか、そうしたところで、区としては区民の方にしっかりご提示していかなければいけないとは考えてあります。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"環境が変わってしまったわけですから。住民の声は結局、この数値だけ見たら、「ほら見ろ」という形になってしまうではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"区の２地点での従前のデータというのは持ちあわせていませんので、これは東京都が新ルート以前から、年間Ｌｄｅｎも公表しております。八潮学園のほうが４４デシベルというところで、令和２年度の結果が上がったというところは、結果としては見られていないです。","id":"exchange-043"},{"speaker":"西本委員","kind":"意見","question":"今まで飛んでいないところを、飛んだところで測定しないと、はっきりした影響は出てこない。そこは配慮していただいて、公表する際に、誤解のないような形での数字の考察をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-03","title":"立会川・勝島地区、都市再生整備計画","agenda":"立会川・勝島地区、都市再生整備計画","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"運河の沿道のところを下りたら、そこになるという形になるのかなとも思うのですが、住宅との関係のところを伺いたいと思います。事業効果を計る指標を確認するためということで行うということなのですけれども、そこの設問で判断をしていこうということなのか、伺います。","respondent":"鈴木都市計画課長","answer":"人道橋を設置して、地域の方の考えといいますか、そうした判断に使わせていただくと。いろいろその指標については検討しているところでございまして、そのうちの一つとして、このアンケート結果も使っていきたいです。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"すみません、一つ聞き忘れまして、３つの整備内容、人道橋と、しながわ花海道の修景、新浜川公園の再整備ということで案が出されておりますが、この３つを選んだ理由、根拠というのを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"まず１つは、平成３１年に策定しました、この３つを整備内容に盛り込む方向で検討を進めているです。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"特に問５なのですけれども、どこにアクセスしやすい、駅が近いとかというのは、住む場所によって大体分かるではないですか。集計が大変になるのですけれども、自由記載、記入するところというのは作らないのか、お願いします。","respondent":"鈴木都市計画課長","answer":"先ほども答弁しましたが、この指標だけで全ての結果を考えていくということではなくて、その中の一つとして加えたいです。国の都市再生整備計画に反映するというところが大きな目的として、一つありますので、今回は自由意見の欄は特段設けていないです。","id":"exchange-047"},{"speaker":"西本委員","kind":"意見","question":"どうだったかという意識も持っていただいて、評価をしていただくということになると、そういう説明は多少入れたほうがいいのかなと思うのです。「どうだったかな」「よかった、より分析をするには効果的なのかなと思いましたので、ぜひご検討くださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"}]},{"id":"topic-04","title":"用途地域等の一括変更","agenda":"用途地域等の一括変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"用途地域のところで伺いたいのですけれども、区内の一部のところでの商業地域と第一種低層住居専用地域が隣り合っているところがあります。商業地域だといろいろ容積率が上がって、低層住居地域のところの良好な環境を守っていくということができるのかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"東京都の用途地域の全体的な指定の考え方、方針というのがありますので、品川区のほうも定められているというところの理解です。それぞれの用途地域での法の適合を守りながら、めり張りのあるといいますか、そうしたところの土地利用が図られているです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"１０ｍまでのところの隣に何百ｍ、１００ｍとかが建ってくるということになってくると、ほかの問題も様々関わってくるということになると思います。良好な環境を守っていくとされているもとで、本当に環境を守っていく面でいいのかなという思いがあるのですが、最後に改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"基本的に２か所、土地自体が坂道で上がっているというところもあって、それほど大きな用途境としての影響はないのかなと。市街地の状況を見ますと、静かなゆとりある住環境が形成されているというところで、路線の商業の影響はそれほどないのかなと認識しています。","id":"exchange-050"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"何点か質問いたしますが、どうしてもこの２０年をかけて整備をしていくというハード面が多いのかなと思いまして、とても大事なことだと思います。そういったハード面ではなくソフト面はどのように考えていらっしゃるのか、まずそれを説明を求めました。","respondent":"栗原河川下水道課長","answer":"ご説明いたしました船着場の整備とあわせたハード面、それとあわせましたソフト面の充実です。本日説明させていただきました中では、フェスタといったものも品川区で実施しているものもありますし、地元で実施しているものもありますが。","id":"exchange-051"},{"speaker":"本多委員","kind":"質問・要望","question":"着目していただきたい。その点についてはいかがか尋ねました。","respondent":"栗原河川下水道課長","answer":"五反田リバーステーションに設置いたしますウェルカムビジョンのお話ですけれども、検討は進めてまいりたいと考えているところです。引き続き、効果的なプロモーションの実施等につきましても、関係部署と連携しながら進めていきたいと思っているところです。","id":"exchange-052"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に１点お聞きするのですけれども、目黒川ですとか、運河ですとか、船に乗って状況を見るという機会が何度か私もありました。どうしても鉄道会社のガードがさびだらけとか、できないところもあると思いますが、その辺を総合的に進めてほしいと求めました。","respondent":"栗原河川下水道課長","answer":"現在パブリックコメント中の、水とみどりの基本計画・行動計画の中でも、景観の向上というところを記載しています。運河側や目黒川からの景観も楽しんでいただけるよう、そういった検討を引き続き進めていきたいと考えているところです。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"水辺が多いと感じる割合５０％、年間に４５０回の利用回数なのですけれども、これはどのように調べていくのでしょうか。回数などは数えればいい話なのですけれども、満足度とかというところについては、どのような指標を持ってお調べになるのか尋ねました。","respondent":"栗原河川下水道課長","answer":"現在、パブリックコメントを実施しております数値目標につきましては、この中で区民満足度調査というのを実施させていただきました。引き続き、区の施策を進めることで、アンケート調査というものは継続的に実施していきたいと考えているものです。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"コストの面でこれを評価するときに、全体の動きの中で、費用対効果も含めて、どういうところをどのように見ていくのかなと。コストに対して効果というのもあって、満足度ということが出てくると思うのですが、それらの評価というのは、何かする予定はあるのか尋ねました。","respondent":"栗原河川下水道課長","answer":"しっかりと事後評価等をした上で、必要な見直し等は実施していくということを、計画書にもまとめさせていただいたところです。実施した事業につきまして、継続するものは継続するといったことを、取組として進めていければと考えております。","id":"exchange-055"},{"speaker":"西本委員","kind":"提案","question":"改善提案をしていくわけだから、住民の皆さんが楽しんでいるというところがあれば、別にそれでいいと思うのです。全体的につくっていただいたほうがいいのかなと思いますので、これは一つの意見として、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これから３倍に増やしていくという中で、区の関わり方というのを改めて教えていただきたいのですが、民間の業者にお任せするというイメージで考えていらっしゃるのか尋ねました。","respondent":"栗原河川下水道課長","answer":"そういったところの社会実験の実施等を踏まえて、それから地元の方々とよくお話をしながら、イベント等の支援をしていきたいと考えているところです。利用要綱を定めました上で、使っていただくべく、ＰＲ等はしっかりしていきたいと考えているところです。","id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問","question":"今これで増やされて、現状の形で一定程度、増えたという認識でよろしいのでしょうか。ＳＵＰとか、人が立ち入っても船に巻き込まれないようなエリアにできないのかなという思いもあるのですけれども、その２点を説明を求めました。","respondent":"栗原河川下水道課長","answer":"ＰＲ等も含めまして行いながら、また検討はしたいと思いますが、今のところは増やすことは考えていないところです。もう１点目、舟運事業者の方々の通航との両立を考えながら、検討はしていければと思っているところです。","id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"たまってしまうというもののようなのですけれども、なぜこうやって取っても、またたまってくるのかなと。たまらないようにする手だてというのは、なかなか考えられないのかなというのをお聞きしたいのですけれども。","respondent":"栗原河川下水道課長","answer":"目黒川に堆積する泥の浚渫ですけれども、こちらは東京都、それから品川区で継続して実施しているものです。少なくなってきているというお話ですが、引き続き下水道局には、そういった整備を求めていきたいと考えているところです。","id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"様々な尽力をされているということで、ありがとうあります。どのぐらいまで水質改善というのは目指せるものなのか、目指していってほしいわけなのですけれども、その辺のことを最後にお伺いしたいと思います。","respondent":"栗原河川下水道課長","answer":"今回の水とみどりの基本計画・行動計画の改定でご提示しています数値目標には、水のきれいさや水辺空間の区民満足度を５０％まで上げると。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"結構お金がかかるのかなと思うのですが、各事業の予算といいますか、事業費が幾らになるのかというところを伺いたいと思います。こういった整備を行っていく中で、そうした再開発のための整備ということはやめていただきたいのですが、いかがか尋ねました。","respondent":"栗原河川下水道課長","answer":"事業実施の金額についてご質問をいただきました。例えば、区有船着場の整備等に関しましては、令和３年度予算額といたしましては、１億８,０００万円程度の予算にて整備をしていく予定です。","id":"exchange-061"}]},{"id":"topic-06","title":"の２、報告事項を再び聴取いたします。 (4)鹿島庚塚児童遊園東側改修工事","agenda":"の２、報告事項を再び聴取いたします。 (4)鹿島庚塚児童遊園東側改修工事","exchanges":[{"speaker":"西本委員","kind":"質問","question":"どういう希望があって、公園の案内図のところの、少し出っ張っているところも公園なのですよね。多少小綺麗にするとか、そういうことはできませんかというのが２点目、いかがか尋ねました。","respondent":"高梨公園課長","answer":"説明でも申し上げましたが、しっかりと自転車の乗り入れを、現在規制させていただいているところです。その建築の計画と公園の改修を連携して進めていかないと、基本的には来年度以降、西側部分については手を入れたいと考えているところです。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"ということで、非常に大きな話題になったりしているので、そういう状況にならないような形で工夫をしてほしいと求めました。周りの事情があるということであるのですけれども、あそこももったいないので、しっかり整備の計画を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、ユニバーサルベッドの設置などを求めているところもあると思うのですが、そこの検討はされたのかどうか。今後３０年ぐらいは３１号線の事業認可はされないという考えなのか、公園は３０年ぐらい、伺いたいと思います。","respondent":"高梨公園課長","answer":"４点目、トイレにつきましてですが、ユニバーサルベッド等の検討はさせていただきました。向こう１０年間で事業化されるという路線には入っていないこと、今回の整備が都市計画道路の整備に伴って、今回改修工事を行うこととしたところです。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4334#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":56279,"voices":166}},{"id":"r03-20211108-9","meetingId":"r03-cm11","date":"2021年11月8日","dateIso":"2021-11-08","committee":"文教委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"令和３年度品川区学力定着度調査および令和３年度全国学力・学習状況調査の結果","agenda":"令和３年度品川区学力定着度調査および令和３年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２年前だったのですけど、資料についての質問なのですが、ちょっとこれだけの説明だと分かりづらいので教えていただきたいというのが１点です。この四分位分析というものをやることのねらいというのですか、理由というのは何なのか、何を改善するために行っていることなのか伺いたいと思います。","respondent":"工藤指導課長","answer":"四分位分析ですが、説明申し上げたように人数分布、ちょうど８０点から９０点の間に実は２５％人数分布というのは入ってまいります。各学校が分析をしながら取組ができるというふうに考えてありますので、授業改善に取り組んでいただきたいという趣旨で示しているものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としては、このグラフをどういう形に持っていくのが理想だと考えていらっしゃるのか伺いたいと思います、というのが２点目です。質問としては、具体的にどういうふうに生かしていこうと考えていらっしゃるのかというのをもう少し聞かせてほしいと求めました。","respondent":"工藤指導課長","answer":"Ｄ、例えばＤ層、そういった子どもたちに対してしっかり丁寧な指導を行っていくことが必要だということは認識できるというふうに思いますので。最後、一個一個が単純に対応したものであるというふうに考えていることではございません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"あなたの学校の結果はＤ層にすごくいっぱい、人数が多いですよということが分かるという、そういう意味なのですか。本事業で定着度合いを把握して子どもに身につけさせたい学力というのは、一体何だというように捉えているのかというのを改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"ですからその場合、区に比べて本校はＢ層も含めて５０％以上がそっちに入っていますよという説明になろうかというふうに思います。判断力、表現力等も併せた総合的なものを含めて全てを学力というふうに考えておりますので、いわゆる知識だけに偏重しているものではないです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"学力の向上ということも含めた成長のために求めているというのは、あとその授業内容を充実させるための時間と条件を整えてほしいということなのです。ですから伺いたいのは、してほしいと思うのですけど、いかがか尋ねました。","respondent":"工藤指導課長","answer":"併せて２点目でいただきました、授業改善に資するというところでいえば、各教員に授業内容等工夫していただいていることは重々理解しています。授業内容を見直す点でも有効な資料になるというふうに考えておりますので、引き続き行っていきたいと考えておるところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"自分たちはどういうことをしてほしいのかということを、しっかりとボトムアップで受け止めていただいた改革というのをしていただきたいと要望します。この学力定着度調査というのは、子どもの学力向上のために絶対必要なのだと、必須なのだというふうに考えていらっしゃるのか伺いたいと思います。","respondent":"工藤指導課長","answer":"第２学年から第９学年までを網羅しつつ、それを次の年度にも生かすという点でいえば必須であるものというふうに考えてありますので、これは継続して行っていくという考えです。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"それで、このテストの中で、例えばそういうような、子ども一人一人の伸びにつながったかというような指標というのはあるのでしょうか。もし、そういうことがあったらいいなと思うのですが、その辺についてはいかがか尋ねました。","respondent":"工藤指導課長","answer":"個別の結果につきましては、各個人にももちろん返るものです。それをまた指導に生かすことができますので、そういった意味では、そういった意味ではきちんと個別に対応できるような結果も返していくです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"そういう子が多い学校は、子どもたちにとっても行きやすい学校かなと思うのですけど、そういうのというのは難しいですか。こういうふうに、最後の点数の結果だけで、良い点の子がこれだけいます、全国平均より高いですというものしか出せないものなのか尋ねました。","respondent":"工藤指導課長","answer":"昨年第２学年だった者は第３学年に上がっていますので、ただ、その結果を示すしかないというところではあります。今後もまた研究が必要だというふうに認識しておりますので、いただいたご意見については、また研究に生かしていきたいと考えております。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"これでは子ども一人一人に目を配ってほしいというのがなかなか言いにくいなということをおっしゃるＰＴＡの方もいらっしゃいますので、だから。もし何かコメントあったら伺いたいと思います。","respondent":"工藤指導課長","answer":"学校支援地域本部によるボランティアの活用など、教員が抱える業務量の削減というのは必要であると認識しておりますので、または授業改善を行う中で働き方改革もしっかり進めていきたいと考えているところです。","id":"exchange-008"},{"speaker":"吉田委員","kind":"意見","question":"どうしても学力定着度だし、正答率という話になると、それ以外にも教育の要素というのはすごくあるのに、そこが見えなくなってしまうのはもうすごく残念だなと思いますので、その点についてぜひ、今後工夫をしていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"何と言うのですか、先生の指導の仕方が問題なのか、そこら辺をどう捉えているのか１点。予習・復習をしているという問いに対して、あまりやらない、全くやらないというのが半分ぐらいか尋ねました。","respondent":"工藤指導課長","answer":"そういった実験・観察というのが行われていないという現状があるというふうに私どもも認識している中では、その調査結果でも明らかになっております。そういったことを各校で取り組むということで、そういった分析をしたものを公表するということは今回全校にはお願いしています。","id":"exchange-010"},{"speaker":"松澤委員","kind":"意見","question":"分かっている子はこうやって、教えることによってまた学びが深まるのかなというのは、ふと肌で感じたのです。それをさらに波及させて、そういった考え方は各校ばらばらになると思うのですけど、何かそういったものの考え方というのはありますかとの意見を述べました。","respondent":"工藤指導課長","answer":"今、お互いの考えを出し合いながら、そして学んでいくというのは全ての学校で行っているところです。授業というのはありますので、そういったことはバランスを取りながら各校進めるようにということで私ども、指導に当たっているところです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"１点だけ確認したいことがあります。今回理科の指導に当たったということなのですけど、どういう方が、どういう指導をしたのかというのをもう少し詳しく聞かせていただきたいです。","respondent":"工藤指導課長","answer":"そういったものをうまく構成をすることで、子どもたちの考え、思考を巡らすことができるというような観点で具体的な指導も行っているです。やはりそこは考える、なぜそういった結果になるのかというのを日々考えることを授業で行いつつ、きちんと考え方。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"今何人いらっしゃるのかということだけ説明を求めました。","respondent":"工藤指導課長","answer":"指導課には現在４名おりますけれども、そのうち幼稚園籍の方が２名ですので、現状今は１名で回らせていただいているところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"先ほど伺えばよかったのですが、これは知識を問う問題とか考えさせる問題とか、何かそういうものというのはあると思うのです。なので、そういう問題のつくりであってほしいと思うのですが、どうなのかというのが１点。","respondent":"工藤指導課長","answer":"これまでも無回答率が２７％になってしまう。そういった意味では何をこう示してというのは見極めながら、分析についてもやはり研究してまいりたいと考えています。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"まさに先ほどあった学びの力というのでしょうか、また一方で、質疑も含めて認識したところなのですけれども。教員側の授業に向かう姿勢というのでしょうか、そこのところというのは、この学力定着度調査を通じて分かることがあれば説明を求めました。","respondent":"工藤指導課長","answer":"授業の質に関するご質問だというふうに思いますが、例えば、学年ごとの単元で定着が難しい単元というのが明らかになるところもあります。それぞれの教員は共通認識を持って授業に臨んでいるところですので、そういった意味では、この学力定着度調査の結果を踏まえながら。","id":"exchange-015"},{"speaker":"つる委員","kind":"確認","question":"なかなかどういうタイミングでそういう報告というか確認がなされるのかあれですけれども、どういう工夫が、なかなか難しいのですけれど。１点、２ページの右のほうにある、個人でやる予習・復習ということなのか尋ねました。","respondent":"工藤指導課長","answer":"質問趣旨上は、どちらも含まれるというふうになってしまうと思います。例えば９年生で自主的に、実際に質問紙で聞くときにはあまりそれを細分化しておりませんので、両方含まれるというように私どもは判断しています。","id":"exchange-016"}]},{"id":"topic-02","title":"令和３年特別区および東京都人事委員会勧告等","agenda":"令和３年特別区および東京都人事委員会勧告等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"なぜそうした特例措置を取られたのかというのをお伺いします。併せて、都のほうの５ページのところに、ラスパイレス方式というのがあるのですけど、これもどういう意味なのかというのを説明を求めました。","respondent":"工藤指導課長","answer":"併せて、１級職なら１級職で大体その経験年数など見合った者同士で比較をするといったときに、正しい公民較差にならないということで除外をする。ですから、そういったもので役職などを合わせながら比較をしたものというものの比較の方式をラスパイレス方式というものです。","id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"こちらは３０％が目標で、特別区全体としては達成しているけれども、各区別に見ると大きな差があるというところがあると思います。文教委員会に関わるところで結構ですので、今、当区の状況というのはどんな形か、もしご存じであればお願いいたしますとの意見を述べました。","respondent":"工藤指導課長","answer":"例えば令和２年度でいうと、これは都費の教員になりますけれども、男性で取得しているのは全体６０名のうち２名。今年度、今途中ですけれども、現状でいうと７４名取得しているのですが、そのうち男性が３名であるというのが現在の状況です。","id":"exchange-018"},{"speaker":"松本委員","kind":"意見","question":"やはり取りにくさというのがあると思いますので、引き続き文教委員会に関わる部分についても促進をお願いできればと思います。以上、意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２ページの（３）の、これ、むしろ社会の変化をつくり出す担い手を育てるという教育というふうにＥＳＤは言っているのではないかと思うのです。この社会にどう対応しようかというのを探るというのは、ここは改める必要があるのではないかと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"（３）の市民科での学習、単元３の内容です。温暖化とか、変わってきた社会の変化にどう対応していくかということを考える内容ですので、内容としては今ご説明したとおりです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、心身ともに健康に働けない状態で、子どもたちに十分な質の学びというのを届けられるのでしょうか。ちょっとここは伺いたいというのが１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"質問ですけど、提案というか必要なのではないかと思うのは、現場からの要望ではない様々なカリキュラムですとか。報告など、やはり削減すべきところは削減するということが必要なのだと思いますが、ＳＤＧｓの達成のためにいかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"基本的なところの確認で、それに関連するものの学びというのは８年生、９年生のみだったでしょうか。そこの基礎の確認、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"実際にＳＤＧｓということで取り上げているのは、この８年生、９年生の単元です。ただ、関わりのあるものは全ての学年に散りばめられております。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"９年生ということで今、まさにその基礎の学びを学校現場で、まさに社会の縮図である学校という中で教えていただいている。この辺もそのまま８年生、それ以外の１年生から７年生のそういう機会というのはどういうふうにしてつくっているのかというのを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"先ほど２点、４年前から４回目になってありますので、継続してその教員が研修を受けた内容を各学校の中で還元していくという形を取ってあります。今後も、研修のほうは継続してまいりたいと考えております。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"ならぬとなったときにどういう事態を招くのかという部分についての伝え方というのは、現場でどういう工夫をされているのかというところ。学校図書館の中でも、自ら学ぶという部分でのＳＤＧｓに関連する資料、そうした部分についての今の状況を教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"達成できないところまで８年生、９年生で考えられるかというところではありますが、私たちが持っている意識で大事なところかと感じております。すみません、２点目は私の認識があれで、もう一度教えていただいてよろしいでしょうか。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"ごめんなさい、図書館の関係なのですが、地区図書館というのでしょうか。８年生、９年生以外での、毎週１回だったでしょうか、２週間に１回だったでしょうか、子どもが本を借りますよね。","respondent":"矢部教育総合支援センター長","answer":"学校の担任のほうで支援員に話をして、すぐそこに同じ本をまとめてもらっているというような現状はあります。学校の年間指導計画に基づいてＳＤＧｓも進めておりますけれども、支援員または図書館司書と協力して、図書の活用を進めているところです。","id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"これは予算特別委員会とか決算特別委員会でさんざん提案をさせていただいているのですが、ぜひ、全校展開とかぜひやっていただきたいなと思います。最後もし、その辺の提案ですけど、現段階でのご答弁あれば説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"ファッション業界の話もありましたけど、様々な方たちと触れ合って、ＳＤＧｓを進めていきたいと考えております。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"コンパクトで結構なので、教員の皆さんにどういうような視点のＳＤＧｓが語られているのか教えていただきたいというのが１つ。学べばみんな感度よく、そう思わないという答えが出てきてしまった結果はどういうふうに分析されているのか、その辺について伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"今年度の元校長先生のご指導の中身を簡単にご説明いたしますと、Ｓｏｃｉｅｔｙ５.０とか、あとＥＳＤについてです。リサイクルから、今日のごみの分別からやればいいというような具体的なところに落としていくことが、これからの指導の課題かなと考えています。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんのお話を伺いながら、そのときはＳＤＧｓという言葉はなかったのですけれども、私が主にやっていたのはフードマイレージ。ぜひそういう、そういう活用もしていただきたいと思うのですが、その点について見解をお伺いします。","respondent":"矢部教育総合支援センター長","answer":"もちろん教員だけではなくて、専門性や長く精通していらっしゃる方をお呼びして、ＳＤＧｓに関わる学習内容の充実は私どもも目指していきたいところだと考えています。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのように進めてほしいと求めました。いろいろ工夫をしておられるということなので、そういうような事例もぜひ参考にして、品川区の中でＳＤＧｓの教育を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"この１名ずつというのはどういった理由なのか、というのをお聞きしたいのと、その１名の教員というのが各学校に持ち帰ってどういうふうにフィードバックしているのかというのをちょっとお聞かせほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"今、話題にもなっていますが研修も様々ございまして、専門もありますので、今のところ１年に１回ですけれども、１人が代表で来るということです。校内研究でＳＤＧｓに取り組んでいれば、電子回覧の機能を使って、その資料や自分の記録を回覧するということもしております。","id":"exchange-031"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"３ページのほうの、この学校で学んだことを家庭に持ち帰ってその家族に伝えて、それでみんなで達成していくというのはとてもいいことだと思います。すみません、あと、学校によって濃淡がついてしまうとかそういったことはないのかというところをちょっと教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"リサイクルをしようとか、学校だけではなくて自分のうちでも取り組もうという活動をしているというところが、読み取れるところです。２点目の、全ての学校でＳＤＧｓを意識して取り組むということで周知してまいりたいと考えておりますので、全校的に展開ができると考えています。","id":"exchange-032"},{"speaker":"湯澤副委員長","kind":"意見","question":"そういうふうになっていけばいいのかなというふうに思いますので、これは意見ですけれども、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"あくつ委員長","kind":"確認","question":"確認ですけれども、この２ページの一番上のところに、令和４年度からの予定だと。東京都のモデル事業というのは、まさにそれをモデルとしてやってみたということなのかどうかというところを説明を求めました。","respondent":"矢部教育総合支援センター長、中島教育長","answer":"今、福祉関係だけについてはこの学校で、市民科のこの時間で取り組みましょうという部分的なところがだんだんと増えていくようなイメージです。研究内容は示していますので、こちらも参考にしながら… 山中小学校のコミュニティ・スクールの中の学校支援地域本部の名前なのですけれども、そこが毎月こういう形で便りを出していただいている。","id":"exchange-034"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"これも何度か質問の中で私も確認させてもらいましたけれども、行動変容がなければ、ぜひ強力に進めていただきたいなと思っています。では、ほかにご意見がないようですので、以上で本日の所管事務調査を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5046#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":43963,"voices":100}},{"id":"r03-20211108-5","meetingId":"r03-cm11","date":"2021年11月8日","dateIso":"2021-11-08","committee":"総務委員会","time":"午後 １時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"コロナ禍における居住意向に関するアンケート調査","agenda":"コロナ禍における居住意向に関するアンケート調査","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"総合実施計画というのは非常に実務的なものだと思うのですけれども、イメージをつかませていただければ、そこら辺のご説明をほしいと求めました。","respondent":"佐藤（聡）計画担当課長","answer":"今回総合実施計画を作るにあたりまして、再度調査・推計するということを予定しておりますけれども、それも併せて総合実施計画のほうで公表するということを予定しております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そうしたら、その人口動向に合わせて総合実施計画も考えていく、体系立てていくというようなイメージなのでしょうか。基本構想、さらに最後の３年間の体系立てをまた変えていくこともあり得るというようなイメージで、このアンケートを実施されるのか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"総合実施計画につきましては、その上で長期基本計画の実現に向けての３か年の行政計画ということで組み立てを考えておりますので、その点で人口動向およびこの調査を踏まえた数値というのをお示ししたいと考えております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、このアンケートと総合実施計画は直結するというほど関係があるわけではないけれども、緩やかには関係するというようなイメージで捉えておけばよろしいのか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"これまで平成１０年以降、そういう点で、委員ご指摘のような形で前提として改めてお示ししたいと考えております。","id":"exchange-003"},{"speaker":"田中委員","kind":"意見","question":"今のやり取りからも、やはり結構重要なアンケートになると思ったのですけれども、重要な調査であるにもかかわらず、この調査対象が２,０００人というのは少し少ないのではないかと思うのですけれども、まずその少ない根拠をお知らせほしいと求めました。","respondent":"佐藤（聡）計画担当課長","answer":"例えば区の世論調査ですと２,５００人を対象にして調査するなど、必要なサンプル数を取れるように想定しまして今回２,０００人という形にしておりますので、この数値でも十分信頼のある数値が得られると考えて設定しております。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"そうは言っても、居住の意向というのは本当に結構区民の間でも話題になっていることなので、この調査の内容に関心のある方はとてもいると思うのです。ですので、無作為抽出の２,０００人は２,０００人でそのままでいいのですけれども、その辺の検討などはいかがか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"統計上信頼できる数値というところから逆算して２,０００人というところを出しておりますので、言われた方の意見が統計上よりも大きく取られてしまうというところもありますので、今回の調査に関してはこの数字でやらせていただきたいと考えております。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"では、この調査を２,０００人を対象に行うという調査の周知は、広報と区ホームページでされる。その２つだけで、もしこの調査に自分も参加したいといった声があった場合には、どのように対応されるのかということを伺ってもいいか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"今回に関しましては無作為抽出で２,０００人という形になっておりますので、突然でびっくりしないようにという形で調査について周知するという面もありますので、そのような形で進めたいと思います。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"やはり関心のある方がとても多い調査項目となっているので、ぜひ広げてほしいということは要望したいと思います。今後の調査対象というのもなるべく広めに取っていただいて、誰でもアンケートに答えられるような体制を整えていただくことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡部委員","kind":"意見","question":"どうせやるなら２,５００人でもよかったのかなという気はするのですけれども、無作為でやらないと、それはこのやり方でいいと思うのです。","respondent":"佐藤（聡）計画担当課長","answer":"今回お聞きしたいのはこの資料の４番目のところですけれども、このコロナ禍を踏まえて定住意向のところに変化が生じたかどうか。高まっているのであれば、今後の人口動向について考えたいという趣旨でございまして、今回の調査をしたいということです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"ただ漠然と無作為にやって、ある層の方たちだけから回答が来たということになると、そこで難しさが出てくるのかなと。今後の区政運営に活かそうということならば、少なくとも年代別に分けたほうがよりいいのではないかと思うのですが、その辺はどのようにお考えか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"委員ご指摘の年代別にということですけれども、今回の調査の設計をする際に、結果として年代別の意向というか傾向が出るようにという形で設計しておりますので、世論調査も同じですけれども、そういった点からの分析にも耐えるような形で設計しております。","id":"exchange-009"},{"speaker":"たけうち副委員長","kind":"質問","question":"この２番の品川区への転入理由を聞くというのは、直近の動向を反映する必要はあまりないのかと思っていたわけです。よく報道などでやっていますけれども、そういった動向などが分かるような設問になっていくのかということを説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"そこのところについてはそのまま、変化がないという形で答えられるようになっておりますので、そこの点もお聞きできると考えております。仮定は考えておりまして、結果として仮定が正しいかどうか、あるいはどういった傾向が出るかということが分かるような形で設計しております。","id":"exchange-010"},{"speaker":"たけうち副委員長","kind":"質問","question":"これは委員会のほうの話かもしれないですけれども、４月の総合実施計画にいきなりぼんと出ているのを我々が目にするというのは、どうですか。今分かる範囲で結構です。","respondent":"佐藤（聡）計画担当課長","answer":"今回お示ししたとおり、総合実施計画でというふうに考えておりますけれども、検討いたしまして、またご報告したいと考えます。","id":"exchange-011"}]},{"id":"topic-02","title":"令和３年 職員の給与等に関する報告及び勧告の概要","agenda":"令和３年 職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これは給料に関することですから、行われて、もう交渉はまとまっているような話なのでしょうか。その辺はどうなのでしょう。","respondent":"崎村人事課長","answer":"先ほど言いました本年のポイントで、特別給が引下げになるということがありますので、現在特別区長会と特区連のほうで協議を行っている状況です。今後これが妥結をされ期末手当の引下げということになりましたら、改めて条例議案として上程し、ご審議をいただく予定です。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"引き上がった場合、６０歳を超えた職員の給料は７割水準に設定することが適当だと書かれているのですが、この根拠は何なのでしょうか。６０歳が来た途端に仕事ができなくなるわけではないと私には思えるのですが、その辺はいかがか尋ねました。","respondent":"崎村人事課長","answer":"同様に７割水準ということで検討があったところですが、全国の民間企業を対象とした調査を実施しておりまして、６０歳前の７割水準となるように給料を設定したといったところが人事院勧告で触れられたところです。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、必ずしも７割にすることに全面的な根拠があるわけではないというのは、国の資料でも示されているわけではないと思うのです。ですから、慎重に協議してほしいと求めましたけれども、いかがか尋ねました。","respondent":"崎村人事課長","answer":"この７割水準については、今後改めて民間企業等の動向を注視して設定するということが考え方として示されております。定年を引き上げることは勤務条件に関わる部分になりますので、丁寧に協議をして妥結を目指していきたいと考えているところです。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問","question":"そういう意味で、品川区はどうなっているのかということをお伺いしたいと思います。それが品川区の場合はどうなのか、その点もお伺いしておきたいと思います。","respondent":"崎村人事課長","answer":"男性の育児休暇の取得率ですけれども、令和２年度について品川区では、取得率がちょうど３０％ということで、３０％の目標値は達成しています。１か月未満が２名、１か月から６か月まで６か月以内の取得をした職員が７名、６か月以上が３名という取得状況でございました。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"鳥取県では長時間労働を１割から２割削減したという例が挙げられたりしているのですけれども、その点、品川区ではいかがお考えでしょうか。その点も少し伺っておきたいと思います。","respondent":"崎村人事課長","answer":"はやはり職場で代替する職員、その人の代わりになる職員の確保といった部分が一番の障害なのかなと考えているところです。ですので、そういった申し出があった場合には、そういったところの意識啓発というのがまず大事なのかと考えているところです。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"この較差というのはどうなっているのでしょうか。それとも国税庁の資料が全くのうそなのか尋ねました。","respondent":"崎村人事課長","answer":"特別区で実施しているのは、公務と同様に部長・課長等の役職段階を有していて、同種のもの同士の企業比較が可能といったところで実施しています。ですので、そういった調査対象の違いによって数字に違いが現れているのかと認識しています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"いや、そうではなくて、やはり平均という意味で言えば、一般の国民、都民、区民が受けるのはこれだけ下がっているではないですか。それから人間関係、様々なことがあると思うのですけれども、これはきちんと声が届くような仕組みができているのか尋ねました。","respondent":"崎村人事課長","answer":"主任昇任前ですとか係長昇任前、管理職もそうですけれども、各職層においてメンタルヘルスの研修を実施しております。そういったところで、必ず管理職なり係長から人事課のほうにご連絡を頂きまして、必要により産業医の面談をするといったことで対応をしています。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"それとも、作るということは可能なのでしょうか。先ほどの質問だけ説明を求めました。","respondent":"崎村人事課長","answer":"特別区の場合は特別区共通で採用選考を実施しておりまして、そちらで面接して、実際に合格して採用するといった流れです。委員のご指摘も十分踏まえながら、どのような採用選考をするべきかというところは今後も研究してまいりたいと思っています。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"今年はこの２、３、４ページというのが増えたので、中身が充実したのですか。勤務環境の整備等に関する意見の４番、５番のところは、お知らせいただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"鹿島庚塚児童遊園東側改修工事請負契約","agenda":"鹿島庚塚児童遊園東側改修工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"トイレのことを聞きたいのですけれども、契約の中でユニバーサルベッドの設置というのは話が出なかったのか、ここに書いてあるものがすべてなのかというところを確認したいのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったものを設置していく方向で、契約の時もチェックしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"東野経理課長","answer":"そこまでの確認は取れていますが、ほかのバリアフリーにつきましては、詳細はこちらまでしか把握してございません。中身につきましては、あくまでも所管のほうでこういう取組みについて契約をするということで、契約手続きのほうは適切に進めてまいりたいと思います。","id":"exchange-022"},{"speaker":"須貝委員","kind":"意見","question":"今後、大きな地震がこの関東、東京に来るような状況が考えられますので、ぜひそういう方面も今後設置に向けて対応していただければありがたいです。意見だけ言わせてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-04","title":"令和３年１０月３１日執行 衆議院議員選挙の結果","agenda":"令和３年１０月３１日執行 衆議院議員選挙の結果","exchanges":[{"speaker":"田中委員","kind":"確認","question":"どういうところに課題があって投票に結びつかなかったのかというところを確認したいのと、あと在外選挙の状況についても少し伺えたらということ。それか投票済証がありますよということを示してほしいといったお声が聞かれたのですけれども、そこら辺の検討というのを伺えればと思います。","respondent":"齋藤選挙管理委員会事務局長","answer":"これは期間が少なかったために、送ることができなかったものだと考えています。投票済証につきましては案内が不十分な点もありますので、今後の改善点ということで、また改めさせていただきたいと思います。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"今後選挙割をされている店と選管でもうまく投票率を上げる工夫というのができたらいいと思うのですけれども、もし何かあればお聞かせいただければと思うのですが、いかがか尋ねました。","respondent":"齋藤選挙管理委員会事務局長","answer":"基本的に２３区統一のものを使って、それで費用軽減というところもありますので、区なりのオリジナリティも出せるか少し検討したいと思います。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、ぜひ区として店や商店街の方たちとうまく連携をして投票率を上げられたらいいと思うので、前向きに検討できたらよいと思います。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"たけうち副委員長","kind":"意見","question":"これを見ていただいて分かるように２０代になると、２０代だけが少し極端に減って、また３０代から比較的上がってくる。１９歳は結構それなりの投票率なのに、２０歳から２４歳になるとがくんと減るという、一応参考までに聞きたいですとの意見を述べました。","respondent":"齋藤選挙管理委員会事務局長","answer":"区といたしまして１８歳、１９歳の方には毎年ポストカードをお送りいたしまして、二十歳を越えてからはそういったものをお送りしておりません。投票率を向上できるような啓発はしていきたいと考えていますが、また今後の検討課題にさせていただきたいと考えています。","id":"exchange-027"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問","question":"５％と２％のところは不動産が５％で、食品が２％でよいのですかというところと、少し分かりやすくしてもらえたらうれしいというのが１点です。こちらの資料の１７ページの次世代育成プログラム「空育」のうちのどれかをやられたのかとか、分かる範囲でお知らせいただければうれしいです。","respondent":"古巻総務課長","answer":"品川区の学習支援事業にご協力いただいたということですので、その事業の一環としてということでご理解いただければと思います。説明が少し不十分かもしれません。","id":"exchange-028"},{"speaker":"田中委員","kind":"意見","question":"２５ページ、なぜこの時は書面開催になってしまったのか、ほかの事業も中止になってしまったのかというのが少し「おや？」と思ったのですけれども、その辺について何かあればお知らせくださいとの意見を述べました。","respondent":"古巻総務課長","answer":"なので、総会については書面開催ということで進めさせていただいたという経緯だと認識しております。１５社というようにある程度限られた中でやれますので、特に企業なのでご指摘のとおり、活動ができるようにいろいろ工夫をしてまいりたいと思います。","id":"exchange-029"},{"speaker":"渡部委員","kind":"意見","question":"一度何かそういう機会があったらよいと思ったりしたので、これは答弁結構です。ご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"大倉委員","kind":"質問","question":"それは当然企業のＰＲも含めて、活動としての発信がよりできるのかなというのを今伺っていて思ったのですが、そういったものはあるのでしょうか。活動は協議会が主なのでどうするかというのは決めるのだと思うのですが、そういったお考えがあると、その辺について説明を求めました。","respondent":"古巻総務課長","answer":"ジャケットというかジャンパー的なものはそれぞれ企業のロゴが入っているものを着て活動されたりということはあると思います。今のところのぼりぐらいしか、そういった全体の活動の目印がないかと思いますので、少し工夫をさせていただければと思います。","id":"exchange-031"},{"speaker":"大倉委員","kind":"意見","question":"その３４ページを見ると、２段目の左の写真で、ご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"おくの委員","kind":"質問・要望","question":"どうもお話を伺っていると、その企業数が増えているというところの右、非常に積極的で意義のあることをやっているという印象を持つのです。あるいは、私などが思うに事務局主体でもいいから、そこら辺はどうなのか尋ねました。","respondent":"古巻総務課長","answer":"今後もう少し前面に出てくると、考え方として、なるべく積極的に活動に参加していただけるような雰囲気づくりをしていければと思っています。少し活動の在り方を考えてみたり、幹事会の中で少しもんで、今後進めていければと考えています。","id":"exchange-033"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういうものにも乗っかって、かつそれを区のほうからも後押しするような感じでやっていっていただければいいのではないかと思います。要望、意見ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"出る話ではないですけれども、また多くの企業に知らしめるという働きをしていただきたいと私は思いますが、いかがでしょうか。もしご意見があったら。","respondent":"古巻総務課長","answer":"その辺りは今後も積極的に活動に対して様々なＰＲをしていくということを、いろいろな工夫があると思うので継続してやっていきたいと思います。ご指摘ありがとうあります。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に一枚のチラシでいいと思うので、ぜひこういう多くの企業の皆さんが貢献して、こういう活動、こういうことに協力してくださっていますというふうに、やはり知らしめるということが、ＣＳＲの推進につながるのではないかと思いますので、そこら辺は考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"たけうち副委員長","kind":"質問","question":"冊子の２４ページのところの住友重機械工業から三菱総研ＤＣＳ株式会社のところについて、これから、今検討しているということでいいのでしょうか。もし、分かれば。","respondent":"古巻総務課長","answer":"まるっきりやっていないわけではないと思いますので、その辺りも今後ある程度活動が少しまとまった段階でいろいろ情報が入ってくると思います。なので確実なお答えにはなっていないと思うのですけれども、そのような状況だと認識しております。","id":"exchange-037"},{"speaker":"たけうち副委員長","kind":"質問","question":"分かりました。ただ３ページにもあるとおり、うちはもうやる気は満々だけれども、少しアドバイスしてほしいみたいなことは時々あるのか尋ねました。","respondent":"古巻総務課長","answer":"こちらから御用聞きで相談をということではないのですけれども、相談いただければ、様々なラインにつなげるような活動はさせていただいているところです。","id":"exchange-038"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"ここにも書いてあるとおり、もちろんそれで重荷になっては困るのですが、何かそういういい意味での関係性をさらに築いていただけるとありがたいなと。先ほど須貝委員からあったとおり、お互いよい意味での関係性をさらに深めてほしいと求めましたけれども、何かございましたら。","respondent":"古巻総務課長","answer":"少しこの２年間、なかなか活動がままならないということがあって、協議会としての活動が少し見えなくなっている部分があるかと思います。今年度もまだ半分ありますけれども、さらに工夫しながらいろいろと活発な活動となるようにしていければと思います。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2212#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":33991,"voices":103}},{"id":"r03-20211109-14","meetingId":"r03-cm11","date":"2021年11月9日","dateIso":"2021-11-09","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"西村委員","kind":"質問","question":"ここをどう見直していくのかというのをお伺いしたいのと、あとチャットボットがどれぐらい利用されているのかというのをお伺いしたいと考えています。この２点、お伺いさせてください。","respondent":"大澤広報広聴課長","answer":"表等のリンクの見づらさについては認識しているところです。チャットボットにつきましては、アクセス数ということであれば、ちょっと今は数字は持ち合わせてございません。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問","question":"一点だけお伺いさせてください。これはＴｗｉｔｔｅｒだけにお願いしたいとか、そういった担当課の方の判断というふうに伺ったことがありまして、そのあたりをお伺いさせてください。","respondent":"大澤広報広聴課長","answer":"その中でどの媒体を使うのか、いつ発信してほしいのか、何時ごろがいいのかというようなことを書いていただいています。ある所管課は、その課の持っている事業や考え方によって偏りというか、その所管に合った使い方をされているというふうに考えています。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"いや、それはＦａｃｅｂｏｏｋのほうにも載せたほうがいいとか、何かそういったことも今後あるといいなと考えています。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"発信をしっかりやってほしいと議会でさんざんお願いをしていたので、ＬＩＮＥ登録されている方はおそらくリアルタイムでぼーんと飛んで来る。それともＳＮＳの担当者が各課にいて、その方が責任を持つということになっているのか、説明を求めました。","respondent":"大澤広報広聴課長","answer":"ＳＮＳの発信につきましては、最終的な責任者は各課の課長が決裁をして、広報広聴課に送ってくるという形になってあります。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。ということは、広報広聴課から発信をするということで、広報広聴課でのチェックみたいなものというのは最後に行うのか尋ねました。","respondent":"大澤広報広聴課長","answer":"はい、各課で課長の決裁を取ったものが広報広聴課に回ってきて、広報広聴課で最終的な確認をした上で発信という形になってあります。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それともう一つ、確認だけになってしまうのですけれども、広報紙なのですね。こういうデザインというのは、１人のデザイナーにお願いをして作っていただいていると、こういうことでよろしいのか尋ねました。","respondent":"大澤広報広聴課長","answer":"決まった会社にお願いはしているのですが、その先のデザイナーが何人いるかというところまでは確認していませんが、こちらの意図を伝えた上で、それに沿ったイラストを入れていただいて、時にはイラストを差し替えていただいたりというようなこともあります。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"分かりやすい言葉で言えばセンス、そういうものというのは、課長が替わることによって変わっていってはいけないと思うのですね。育成というか、いらっしゃると、こういう認識でいいのか尋ねました。","respondent":"大澤広報広聴課長","answer":"やはり多様性とか共存社会とか、そういうことを伝えていかなければいけないということは、広報広聴課全体として認識しています。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"それはそういう形で代々受け継がれていくというふうに捉えました。防災の情報などというのは、今日の所管で聞いてはまずいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"震度５の地震が東京であったときに、そのことについてちょっとお伺いしようと思ったのですが、ご答弁される方がいなかったので。失礼いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほどのお話を伺っていると、その災害時の情報発信はＬＩＮＥとかだとどうなっているのかなというのが、そこが分かれば教えていただきたい。その後、その辺の工夫ですかね、なくしていくためにどのような課題があって工夫をされているかというのを教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥについては、今自動配信するように連携してございませんので、災害時等の発信については今後の課題だというふうに認識しています。今、変更していますので、今後はできる限り間違いをなくした配信をするように努力してまいります。","id":"exchange-010"},{"speaker":"大倉委員","kind":"確認","question":"今ＬＩＮＥということでしたが、事前に予約をしながらやっていくとミスがなくなるということで大丈夫なのか、ちょっと改めて確認を。そのチェックの体制が本当にそれで大丈夫なのかというところでちょっと疑問に思ったので、もう一度ご答弁ほしいと求めました。","respondent":"大澤広報広聴課長","answer":"できるだけ早く出していただければ、時間があるときに入力できますので、今までよりは間違いが減るようになるというふうに思っています。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"入力するということで、データでもらって、それを改めて何か入力し直す作業があってということなのでしょうか。Ｔｗｉｔｔｅｒとかしなメールとかだとたまに文字化けしたメールが届くみたいなお話があって、入力し直す作業が必要ということなのか尋ねました。","respondent":"大澤広報広聴課長","answer":"所管からデータで来たものを、ある程度やはり広報広聴課のほうでチェックして、修正が入りますので、データを写して、それを修正して流すという形になってあります。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"その中でお伺いしたいのは、例えば、広報紙をこれだけ出しています。ほかのことでもそうなのですが、ある一定度の目標を立てて、そこら辺のところをちょっと教えていただければありがたい。","respondent":"大澤広報広聴課長","answer":"どうしてもずっと継続的に管理をしていかなければいけないというところでは、区の要綱に合わせてお断りする場合も結構ありますので、目標を立てて。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば観光的なものをどうしていくのだとか、イベント情報とか、あるではないですか。」とか、何かこういうものというのがあるではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"そこについての認識を一つお伺いしたいのと、ここに出ていないのですが、郵送というのがありますよね。〔「さっき３,０００件と言った」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"それは３,０００件ということです。ないのであれば、認識としてはどの媒体が最も今区民の情報源として使われているのかというようなことの見解を教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"カタログポケットというアプリですとか、それに耐えられるようないろいろな配信方法を広げていかなければいけないなというふうに思っております。やはり広報しながわが１番で、２番目が品川区ホームページ、３番目が回覧板というような順位になってあります。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう知見というか、そういった研究もぜひ今後していただきたいなというのがあって、これについてのご見解を聞きたい。広報の広報みたいになってしまいますけれども、これについてもひとつ力を入れていただきたいと思うのですが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"やはりホームページでもどういうふうにすると見やすいのかということは研究してまいりたいと思います。今も必ず広報紙に個別配送できますというふうに載せているのですが、また少し目立つようにＰＲする号を作ってまいりたいと思います。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"費用がかかっても１軒１軒に何とか届けるという、その辺、実際どうなのでしょうか。どのように考えているのでしょうか、説明を求めました。","respondent":"大澤広報広聴課長","answer":"どこかで品川区としてはこれとこれで周知していきますということをある程度絞っていく必要というのが出てくるのだろうなというふうには考えています。困ったときは情報を得ようとすると、特に調査をしているわけではないですけれども、広報広聴課としての感覚では持っております。","id":"exchange-018"},{"speaker":"須貝委員","kind":"意見","question":"そうすると、これだけ品川区でお伝えしたいということがあるならば、私は費用がかかっても、やはり戸別に何とかお手元に届ける。そういう手法も取らなければいけない時期に来たのではないかなというふうに私は思うのですが、もう一度だけご見解を説明を求めました。","respondent":"大澤広報広聴課長","answer":"例えば広報紙を全戸配布するというような考えはなくて、今の時点で広報紙の全戸配布ということは考えておりませんが、必要なところに届けるようにしてまいりたいというふうに思っております。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に意見だけ。０歳からご高齢者までさまざまな事業をされているわけですから、それを届けるというよりは、何とかいい方法があったら考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"芹澤委員","kind":"質問・要望","question":"登録者数というのですかね、その裏側というか、誰がどのような頻度でやっていらっしゃるのかなというのを教えてほしいと求めました。令和元年から２年にかけて倍ぐらいどんと増えてきていて、ほかも右肩上がりで、情報を求めた区民の方々がフォローされたのだろうと思うのですね。","respondent":"大澤広報広聴課長","answer":"ＳＮＳ等の登録者数の分析としては、属性までは分析できていませんので、例えばＦａｃｅｂｏｏｋだとどのような項目にどのくらいのリーチがあったかということで分析をして、どういうものを出すとたくさんの方が見るのかというような分析方法で確認をしております。","id":"exchange-021"},{"speaker":"芹澤委員","kind":"提案","question":"品川区のアカウントを登録された方々にどれぐらいセグメントがあるのかというのもまだ把握できていないということなのでしょうか。約１万人の登録数に対してどれぐらいブロックされているというのは分かるものなのか尋ねました。","respondent":"大澤広報広聴課長","answer":"ただ、例えば成人式の申込みにＬＩＮＥを活用するとか、そうなるとセグメント配信等もうまく機能していくのかなというふうに思っています。登録数とブロックされている数も把握しておりますので、ここの数はブロック数を除いた数で出しているというふうに認識しております。","id":"exchange-022"},{"speaker":"芹澤委員","kind":"質問","question":"もし分かればなのですが、ブロック数がどれぐらいなのか。この９,６８６がブロックされていない数で、ブロックされているのがどれぐらいなのかだけ、もし分かれば説明を求めました。","respondent":"大澤広報広聴課長","answer":"ブロック数の正確な数が今手元にないのですが、たしか２,０００とか千幾つとか、そういう４桁の初めのほうの数だったというふうに記憶しています。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ホームページについてちょっと伺いたいのですが、それの同意を求める文書が出てきて、それがその後どうなったのか。多くの方がこうしたホームページ、品川区の情報というものにアクセスできるということが大事だと思うのですけれども、その結果を説明を求めました。","respondent":"大澤広報広聴課長","answer":"これは事業者に投げていて、今どうするかを考えていただいているのですが、現状は変わっていません。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたものは参考にされているのでしょうか。平成３０年度以降は、そうした総務省等々のこうした規定やガイドラインを参考にされているのか、説明を求めました。","respondent":"大澤広報広聴課長","answer":"各所管でホームページを担当している職員に研修を受けていただいて、誰にでも使いやすいホームページの作成に努めているところです。調査については、近々にアクセシビリティの検査を受ける予定があります。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり緊急時だったり、災害時だったり、本当に支障なくこうしたホームページ等にアクセスできるというのは大事なことだと思います。引き続き改善されていくのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"渡部委員","kind":"確認","question":"もって、どうしてもアナログで対応しなければいけない人は地域センターで聞いてくださいとか、よく見られているページというのが出ますよね。もしくはある程度意図してこういう情報ですというふうに出しているのかというところだけちょっと確認させてください。","respondent":"大澤広報広聴課長","answer":"数が多いものを上げるようにはしていますけれども、必ずしも多いものから順番に並べているわけではないです。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"ですから、例えば商品券の発売はこちらとか、何かそういうことというのはお考えになったりしますか。どうなのですかね。","respondent":"大澤広報広聴課長","answer":"よく見られているページというのは、多分月単位なので１か月で多いページが上のほうに来てしまうのです。委員おっしゃるとおり、下に沈んでしまったものは、そういったことをもう少しきめ細かくやっていきたいというふうに思います。","id":"exchange-028"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"少しぐらいどういった事業なのかということも書いていただけたらというふうに思うのですが、いかがでしょうか。そうした字幕の付与をぜひ進めていっていただきたいと思うのですが、その進められないところの課題があれば伺いたいと思います。","respondent":"大澤広報広聴課長","answer":"いつ、どこで、広報広聴課のほうからも各所管には重ねて説明をしていきたいと考えています。それを今度は人が全部直すとなると、莫大な費用と手間がかかるので、今のところはそこまではやっていないというのが現状です。","id":"exchange-029"},{"speaker":"のだて副委員長","kind":"質問","question":"字幕のところなのですが、せりふを全部やるとということなのですが、録画してやられると思うのです。その場合だったら字幕をつけるのは、収録してやる場合は後からつけるわけですから、それもなかなか機械の関係でできないということなのか尋ねました。","respondent":"大澤広報広聴課長","answer":"今ケーブルテレビ品川の区の情報番組については、全てテロップをつけているので、内容はそこを読んでいただけると分かるようになっています。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":22711,"voices":67}},{"id":"r03-20211110-19","meetingId":"r03-cm11","date":"2021年11月10日","dateIso":"2021-11-10","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時０５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これはどのくらい必要だと考えていらっしゃるのかということをお伺いしたいのと、それで、それこそ。普通の私たち区民にとっては分かりやすくていいのではないかと思ったのですけれども、その辺はいかがでしょうかということ。","respondent":"山本防災課長","answer":"それから２点目の、場所等、その際については丁寧に説明をしていきたいというふうに考えてあります。大崎地区、区の計画の中の基準を満たした部分での仮置場は設置できないですけれども、そういった方法も検討していきたいというふうに考えてあります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"最初の地区仮置場の質問ですけれども、やはりめどをつけておくというか、そのような作業はもうやられているのですか。本当に発災状況を見てから、ゼロからやるというようなことなのか尋ねました。","respondent":"山本防災課長","answer":"具体的な検討ですが、幾つかパターンがあるかと思うのですけれども、一定の方向性というか、こういった部分でどの公園をどう活用するかというところは、内部でマニュアル等をつくっていきたいというふうには考えているところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから、次の質問ですけれども、これも６０ページ辺りに書かれていることなのですが、有害物質などの処理です。それから予算などをどう考えていらっしゃるのかということを含めて、何というか、いかがか尋ねました。","respondent":"山本防災課長","answer":"それから、予算の部分に関してですが、ちょっと予算については、今のところまだ検討していないところです。今後の課題だというふうに考えてあります。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"現状で、負担関係がどのようになることが現状では原則になっているのか、この点をお伺いしたいと思います。それで、参考までに東日本大震災ではどのような負担関係だったのか、この点お教え願えればありがたいと思うのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"当初は行っていくというところを考えてございまして、また補正予算等を組んでやっていくということを考えているところです。今手元に資料がないので、お答えができない状況です。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"私がお伺いしたかったのは、かなり国や都、特に国に負担してもらえる部分があるのではないかというつもりでお伺いしたのですが。たまらないのではないかということなのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"失礼いたしました。災害等廃棄物処理事業費補助金というものがございまして、こちらのほうで災害廃棄物に関する処理、要する費用等の補助というものがある状況です。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"具体的に何割程度が国で、実際に区が負担しなければいけないのは、かかった分の何割程度ということになるのか尋ねました。","respondent":"山本防災課長","answer":"申し訳ございません。ちょっと具体的な補助割合等は、今資料が手元にないのですけれども、その辺り、また別途回答させていただきたいと思います。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"今からその費用のことも考えて、国に十分な補助をいただけるというか、してもらわなければいけないのではないかと思うのです。その辺のこともよく考えて、国へのアプローチというか、お願いというか、そのようなこともやっておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問","question":"Ａ３の資料の２ページのところで、右側に仮置場のレイアウトがありますけれども、ここに腐敗性廃棄物とあるのですが、これはどのようなものか。左側を見ると、通常の区による収集・運搬のほうになるのかなと思うのですけれども、これはどのようなものか尋ねました。","respondent":"山本防災課長","answer":"腐敗性廃棄物、具体例として申し上げますと、例えば畳であったり、あとは水産廃棄物、そういったものを想定しているものです。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。広場にたまっているとなると、この一次仮置場のほうに随時運搬すると、このような流れでよろしいか尋ねました。","respondent":"山本防災課長","answer":"こちらの一次仮置場、比較的面積の大きい公園を想定していますが、そちらのほうに収集・運搬をするということで考えてあります。収集の頻度につきましては、実際に災害が発生したときの発生量の見込み等で想定して、そのときに考えていくという予定です。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"こういった部分の業務と２つ出てくるので、その辺の人手もかかってくるかもしれないしと、このようなことですね。何かその辺の対策というのですか、分からないけれども、そのようなこともある程度お考えなのかということを説明を求めました。","respondent":"滝澤災害対策担当部長、山本防災課長、品川品川区清掃事務所長","answer":"先ほど防災課長のほうから説明しましたが、今回業者に委託をして、大規模震災のときのがれき量を見積もっていただきました。今後は都と連携をしまして… その辺り悪臭の防止や雨水等の発酵防止というところは、区としてもやっていかなければならないというふうに考えているところです。こちらにつきましても… その後、基本的に、計画の中では７２時間後に一般ごみのほうも収集していくというようなことで明記をしています。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"当然これからお考えになるとか、管理体制というのですか、災害ごみに。そのようにいろいろな、何というのですか、管理体制というか。","respondent":"山本防災課長","answer":"１点目の仮置場の管理体制についてです。この辺１つバッティングはあるのですが、そのときの状況に応じて、使用用途というものはこちらのほうで検討していきたいと思ってあります。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"意見","question":"そこはしっかり縦分けていただくようなことも、嫌な話ですけれども、考えておいていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"ニュースで取り上げられるぐらいですから、検討されていないのか、伺いたいと思います。その辺について、この計画の中では明確に見えないのですけれども、その辺についてどうなのか、まずその点について伺いたいと思います。","respondent":"山本防災課長","answer":"それから検討委員会のメンバーについてですが、検討委員のほうで検討をしてきたところですけれども、その辺り。それから３点目のし尿の処理につきましては、袋を縛って、ご自宅等で一時的に保管をしていただくという対応になるところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"年限でいったら既に事業者や何かでも、いまだにまだそれはきちんと最終的な処理のところまでいっていないということなのでしょうか。その辺について伺いたいと思います。","respondent":"山本防災課長","answer":"こちらについても、環境省のサイト等からデータを持ってきたものになってございまして、こちらのサイト等を活用しています。具体的に区でどうのというよりは、一般的なものでこういったものがありますというところで、ちょっとお示しをしています。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"現実にやはりそのようなことがまだある、それが品川区内かどうかは分かりませんけれども、だから品川区にも可能性があるということですよね。そのような化学物質とか、現実にそれをされているのだったらごめんなさい、もしそのようなことがあるのだったら説明を求めました。","respondent":"滝澤災害対策担当部長","answer":"先ほど防災課長から説明がありました４ページ以下につきましては、基本的に環境省の資料を用いて、都の指導を受けて廃棄の手順を取ることになります。区としては、今３ページにある本計画で対象とする廃棄物、ここを中心に計画をつくったものです。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"し尿のところが簡易トイレや仮設トイレからのし尿となっているので、一般家庭のし尿はどうなっているのかなと思って質問させていただいた次第です。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞かせいただきたいのですが、ちょっと聞き取れなくて、どのようなところに意見照会されるのか教えてほしいと求めました。この検討会をした中で、何というのですか、あったらどのようなものなのかということについてもお聞かせほしいと求めました。","respondent":"山本防災課長","answer":"３点目の検討委員会の回数ですが、こちらについては３回行っているところでございまして、今のところ公開する予定はございません。実際に震災が起きた場合の初動の対応というところで、それから協定先、１つ課題だというふうに考えているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"応急仮置場がこの公園など、そのように具体的に公園がどこだというようなところも、その実行計画の中で決まるということになるのでしょうか。地区仮置場も３日後からということになりますけれども、発災後、その辺はどうなるのかお聞かせほしいと求めました。","respondent":"滝澤災害対策担当部長、山本防災課長","answer":"先ほど防災課長から説明がありましたように、救護所を設置しなければいけないとか、状況を見て最終的には決心をするという形になると思います。最終的にはいろいろな用途を検討した中で、もしくは風水害もまた検討していますので… 委託事業者等も活用して、やはり検討漏れがないか等、今回専門家に意見をお伺いしたいというふうに考えているところです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"町会に１つの公園はつくっていくということを、ぜひとも方針として持っていただきたいなと思うのですけれども、その点についても伺いたいと思います。１日３２万リットルのうち、この協定の中で確保できるということになっているのか、その点についても伺いたいと思います。","respondent":"山本防災課長","answer":"１つの事業者と協定を結んでいるところですが、２５ページのところで、そういった部分も活用する予定です。区のトイレの活用の優先順位としては、いわゆる仮設トイレというのは、そういった部分で対応はできるのではないかと思っているところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのような直結型のマンホールトイレというものをつくられている避難所というのはどれぐらいあるのか、その数を教えてほしいと求めました。その一覧表が、だから使っても下水道のほうに流れていくからという、そのような一覧表のようなものができているのかについても説明を求めました。","respondent":"山本防災課長","answer":"ちょっと今手元に具体的な資料がないのですが、基本的に区民避難所の部分に関しては、１か所は設置のほうを進めているところです。こちらのほうもまだ作成というところはしておりませんので、この辺りにつきましては、今後ちょっと考えていきたいと思っているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"隣の１７ページに、焼却、埋立ての割合などが分かったら教えていただけたらと思います。２７ページなどに、雇用も確保していくという形でやるべきではないかと思うのですけれども、その点についても区の考えを伺いたいと思います。","respondent":"山本防災課長","answer":"今１７０以上の事業者と協定というものを締結しています。連携等を取れるというところでは、ぜひ区内の様々な事業者の方のお力を借りたいというふうに、区としては考えているところです。","id":"exchange-021"},{"speaker":"小芝委員","kind":"確認","question":"災害の発災直後から１週間程度のところで、この資料だと６８ページですが、かつ排水用の生活用水を確保できるとき」というように下に書いてあります。その生活用水の中に災害用井戸等がありまして、この災害用井戸というのは学校の中の井戸を指しておるのかどうか、その確認だけ、まずお願いします。","respondent":"山本防災課長","answer":"こちらの災害用井戸につきましては、委員がおっしゃったとおり、区民避難所にある浅井戸を想定しています。","id":"exchange-022"},{"speaker":"小芝委員","kind":"質問・要望","question":"何ですか、私道ですか、このような場では活用できるのではないかと思います。そのようなものをまた促していくことも、区の役割ではないかなと思いますが、見解のほうをちょっと説明を求めました。","respondent":"山本防災課長","answer":"生活用水の確保というところ、非常に重要だと区としても認識しています。今現在区の地域防災計画上、なかなか位置づけはされていないところですが、そういった部分の活用というところも今後考えていきたいと思ってあります。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどのご質問の中で気づいたのですけれども、簡易型トイレ、備蓄されているということで、すみません、単純な質問です。それとどのように試したことがあるのかということを確認させてほしいと求めました。","respondent":"山本防災課長","answer":"入替えというところは、その使用期限等がありますので、定期的に使用期限前に入替えというものを行っているところです。訓練とか、区民の皆様にそこに水を入れた後に凝固剤を入れて、こういうふうに使うのですよというところの周知等は行っているところです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"その更新のとき、例えば避難訓練のときに皆さんに提供するとか、そのような形になっているのか、その辺についても教えていただけますか。","respondent":"山本防災課長","answer":"備蓄の有効活用というところで、そういったところの活用方法につきましては、今後考えていきたいと思ってあります。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺の確認がされていなくて、少しぐらい使用期限が切れても、その辺について適切な後利用ということを考えてほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"大沢副委員長","kind":"質問","question":"それに対する考え方はこの中にどのように、基本的な考え方にどのように織り込まれて、どのように表現されているのか説明を求めました。","respondent":"山本防災課長","answer":"高層マンション等の居住者への対応ですが、１つの区民という形で、様々な対応等の考え方を整理しています。ごみがかなり集積してしまうというような課題もあるというふうに考えてありますので、また別途、様々周知等を行っていきたいと思ってあります。","id":"exchange-027"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"どうしても縦に伸びたほうの地域、あるいは意思の疎通ができるような仕掛けをしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"平面と立体というところでの連携、スムーズなつながりというところ、確かに区としても考えていかなければならないことだと思ってあります。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"計画の基本方針というところを確認させていただきたいのですが、資料の１の（３）の1)で状況、処理計画をつくっていくと。それから7)の区民やボランティアとの協力というところで、まず、この基本方針についてイメージを説明を求めました。","respondent":"山本防災課長","answer":"それにつきましては、災害発災後、災害対策本部体制を敷きまして、その中で様々な被害状況等の把握を行う予定です。一定期間、１週間後だったりというところでは、様々情報の収集・整理ということを行っていくというところで考えているところです。","id":"exchange-029"},{"speaker":"こんの委員","kind":"確認","question":"学識経験者の方々のご意見も伺って、さらにブラッシュアップされて計画されると思うのですけれども、その点お願いしたいなと思います。これ確認ですが、それぞれの地区の公園数が出ておりますが、これはあくまでも想定される公園数ということでいいのか尋ねました。","respondent":"山本防災課長","answer":"説明版の資料をつくっていきたいと思っていまして、基本的にはそちら、そちらのほうで各町会長にまずご説明に伺いたいと思っているところです。","id":"exchange-030"},{"speaker":"こんの委員","kind":"確認","question":"仮置場の確保の（２）の候補地、あくまでもこれだけ使えたらいいなという数なのかということを、ちょっともう１回確認します。そうしたところなのだろうと思うのですけれども、訓練と出ていたのですが、どのような訓練をこのようなものはするのか尋ねました。","respondent":"山本防災課長","answer":"それから区民への周知ですが、やはり区民の皆様がご自宅で何か見られるものがあるというような状態にしていければとは思っているところです。ではこの仮置場を開設しようとか、収集ルートをどうしよう、そういった部分の図上訓練というところを想定しているところです。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"職員の方の訓練はあれですか、防災課の職員だけではなく、全庁挙げての職員というような理解でよろしいでしょうか。最後。","respondent":"滝澤災害対策担当部長","answer":"訓練の具体的な方法については、今後計画ができた後に検討させてください。地区仮置場、これは今後検討させていただいて、さらに深いものにしていきたいと思います。","id":"exchange-032"}]},{"id":"topic-02","title":"もったいないレシピコンテストの入賞作品決定","agenda":"もったいないレシピコンテストの入賞作品決定","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今回たくさん応募してくださって、本当によかったなと思います。立派なパンフレットができて、この後、これをまた活用していくというようなことがあれば説明を求めました。","respondent":"河内環境課長","answer":"今検討しておりますけれども、そのような形で拡大、また周知を進めてまいりたいというふうに考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"趣旨としてはとてもいい企画になったかなと思いますので、ぜひ、これだけ多くの方が協力というか、応募してくださったので、いろいろなところでの活用とか、今後何かブラッシュアップした上での継続した企画とか、そのようなことも検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"今後の充実を図ってまいりまして、大変ＣＯ２も発生しますので、啓発を進めてまいりたいというふうに考えているところです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"これが具体的にどのようにＣＯ２削減につながっているのかというような、今後活用していっていただきたいのですが、その辺についていかがでしょう。","respondent":"河内環境課長","answer":"今回このレシピコンテストにあたりまして、アンケートも同時にやらせていただいております。食品ロスのイメージで大変参考になったとか、こういった声を基に、さらなる拡大を図ってまいりたいというようなところで検討しています。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"多分２回目、３回目、継続性も含めて伺いたいということが１つです。何かこう、想定していたものがあるでしょうから、そことは違ってすごく参考になった点などがあったらお知らせください。","respondent":"河内環境課長","answer":"中には６０代の方が７％もいらっしゃったり、葉とか、共有できるいいきっかけになっているというようなところが大きな成果だと考えています。","id":"exchange-036"}]},{"id":"topic-03","title":"令和３年度区内一斉防災訓練の実施","agenda":"令和３年度区内一斉防災訓練の実施","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"訓練内容について少し質問させてください。再構築されて、あの防災タブレットに何か新しい機能が備わっているのか、何か変化があったのか説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"防災タブレットを活用した訓練についてのご質問になります。タブレット面を通して対面でやれるような、情報のタブレット化という意味で、それもちょっと導入した訓練をやってみようという試みです。","id":"exchange-037"},{"speaker":"松澤委員","kind":"質問","question":"何というのですか、しっかりと町会長などが学ぶ、そのような機会というものは設ける予定があるのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"今回訓練の中で使用するのは、あくまで警察、消防と災害本部の指令情報部とのやり取りになりますので、今回町会長のところは実施する予定はございません。","id":"exchange-038"},{"speaker":"松澤委員","kind":"質問","question":"そういった新しい訓練というのですか、ちょっと言葉は悪いですが、もう行った途端に分かってしまうぐらいマニュアル化されているのです。私も質問しますけれど、もう少し挑戦していいのかなと個人的には思うのですけれども、ご意見をお願いします。","respondent":"五十嵐災害対策担当課長","answer":"委員のご意見ありがとうあります。いろいろと検証させていただいた上で、いわゆる町会の方々との通信訓練というものも検討していきたいと思いますので、よろしくお願いします。","id":"exchange-039"},{"speaker":"松澤委員","kind":"質問","question":"最後になります。防災授業をやらない学校が何校かありますけれども、このやらない理由というのは校長先生の判断なのか、そこだけ説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"生徒たちを集めて、さらに町会の方々と連携した訓練というのはちょっと気が引けるということで、そういった学校は別日に実施すると。例えば防災安全指導日ですか、そちらのほうで実施するというようなことで回答をいただいております。","id":"exchange-040"},{"speaker":"くにば委員","kind":"確認","question":"通常目視できちんとスプレー缶があるかどうかを確認しているかどうか、なぜ今回陶器ガラス金属ごみの収集中に目視等で確認できなかったのか、その点についてお聞かせいただけますか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"基本的にはビニール袋を分けて出していただくということで説明のほうをしているところですが、こちらは警察とか消防の中でも、多分あるかと思います。","id":"exchange-041"},{"speaker":"くにば委員","kind":"確認","question":"１本もこれが確認できなかった、ちょっと１つ大きな気がかりというか、問題点だと思うのです。目視で確認することはかなり難しいのかなと思うのですが、大量にあったのに確認できなかった、その点についてお伺いします。","respondent":"品川品川区清掃事務所長","answer":"そのまままたビニール袋に入れているとか、そういったケースも考えられなくはないかなとは思われます。とにかく外目で見て、どうしても視界の中で見えない部分については、取り切れていないという部分があるのかなというふうにも考えております。","id":"exchange-042"},{"speaker":"くにば委員","kind":"確認","question":"外から見えないから確認しないという方針であるのか、そうであれば再発は防げないと思うのですけれども、もちろん物すごい手間だとは思います。外から見えないものをどうやって今後確認していくのか、一々手間をかけて確認するという今後の方針にしていくのか、なので今後は仕方ないよねという。","respondent":"品川品川区清掃事務所長","answer":"全てを確認して回収していったほうがいいのですが、さすがにそれをやってしまうと、多分１日の中で回収できないような形になってしまうかと思います。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問","question":"やはり最終的にご答弁のほうを伺った限りでは、今伺った中では、今後いいのかなあと思いました。そうでなければ今回のこの報告、対策という部分、原因究明、再発防止という部分になり切らないのかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"吉田委員","kind":"提案","question":"それが１つと、それから、この消火の手順ですけれども、これが基本的なマニュアルなのでしょうか。試みた結果として鎮火できなかったからではなく、同時であるべきではないかなと思うのですが、その辺についてはいかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"ちょっと説明として、私のほうもそのようなご説明をさせていただいているのですが、ある程度その作業自体は同時というところもあります。とにかく場所の移動をさせて、その後消火活動をしてということで、その後消防のほうに連絡をしたです。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"近隣の方にはご迷惑をかけてしまっているわけですから、そのおわびかたがた、ぜひそれは前向きに検討していただけたらと思います。対応で徹底していただいたほうがいいかなと思うのですが、その辺についてちょっと改めて、ご見解を伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"今後の対策というところにつきましては、やはり清掃事務所全体として、どのようにやっていくかというところを考えていくです。やはりしっかりやっていかなければいけないと考えていますので、その辺も含めてしっかりとやっていきたいと考えています。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/822771?Template=document&Id=6604#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":40457,"voices":121}},{"id":"r03-20211112-10","meetingId":"r03-cm11","date":"2021年11月12日","dateIso":"2021-11-12","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"その他を議題に表します。 初めに、(1)議長からの報告","agenda":"その他を議題に表します。 初めに、(1)議長からの報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点確認と、若干意見も述べたいと思いますけれども、議長に申し入れるという説明でした。そうした議会であるべきだと思いますので、今後も必要に応じて、皆さんの意見を伺いながら対応していったらいいのではないかと。","respondent":"工藤区議会事務局長","answer":"議長に直接言っていただく、もしくは、事務局の庶務係に申し出ていただく。それを議長にお伝えして、確認をしていくということで考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"意見としましては、１の議長にあらかじめ申し出るというのは特に必要ないのではないかと私は思います。確認されていれば、あえて申出をしなくても、飲めるようにしたほうが私はいいのではないかと意見を述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5430#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6155,"voices":24}},{"id":"r03-20211124-10","meetingId":"r03-cm11","date":"2021年11月24日","dateIso":"2021-11-24","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"十分な質疑の時間を確保していただきたいということです。建設委員会にて一定の報告がありましたので、それも踏まえて、質疑の時間を十分に確保していただきたいと要望しておきたいと思います。","respondent":"本多議長","answer":"ほか数名が来られる予定で、国交省からの説明をいただきまして、質疑の時間は十分にとる予定です。最大なのですけども、６０分ぐらいは質疑の時間を取れるのかなというイメージでいますので、よろしくお願いします。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5432#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6802,"voices":30}},{"id":"r03-20211129-6","meetingId":"r03-cm11","date":"2021年11月29日","dateIso":"2021-11-29","committee":"区民委員会","time":"午前１０時００分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"令和３年陳情第５６号 品川区の分煙環境整備に関する陳情","agenda":"令和３年陳情第５６号 品川区の分煙環境整備に関する陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"幾つかお伺いしたいと思うのですけれども、まず、たばこの害、健康被害について伺いたいと思います。つまり、喫煙されている本人とその周辺の方、受動喫煙のことですけれども、具体的にどんなリスクがあるのかご説明ほしいと求めました。","respondent":"高山健康課長","answer":"たばこの害についてのお尋ねです。ＣＯＰＤといわれるもの、それから肺がんなどといったもののリスク因子として、広く科学的な知見があるということで認められているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"陳情が求める公共の場での喫煙所の増設について、区はどのように考えているのか伺いたいと思います。具体的な健康被害が明らかな中、公共の場の喫煙所の増設は進めるべきではないと私は思いますけれども、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"９か所に設置しておりますが、先ほどご説明させていただきましたとおり、マナーを守って喫煙をされる方の立場に配慮して喫煙所を設置しています。喫煙所設置につきましては、私どももまた考えて検討していますので、周辺の喫煙環境が。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"最後に一言。近隣の方の声を受けて、理解を示したいと思いますが、今以上に箇所数を増やすというのは進めるベきではないという意見を述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"陳情要旨の２番に関してなのですが、事業所やオフィスビルに対してどこまでの環境整備を求めるのか、施設管理者に対して現状どのような働きかけを実施しているのか、説明を求めました。","respondent":"高山健康課長","answer":"区では、例えばしながわＣＳＲ推進協議会の場をお借りしまして、受動喫煙に関する取組みや法律、条例、都条例の趣旨などをご説明してきております。管理者の意向などを踏まえまして、アドバイスなどをこの間、相談なども含めて応じてきているところです。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひそこは加味していただいて、検討してほしいと求めましたので、よろしくお願いいたします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"区としての考え方を伺いたいのですが、例えば２０年前とかもう少し前であると、どこの公園でもベンチなどでたばこは吸えたと思うのです。その２点を伺いたいのですけれども、よろしいか尋ねました。","respondent":"森田生活安全担当課長、高山健康課長","answer":"私有地において灰皿を設置する、しないのところです。それは私どものパトロールでも、そういった苦情があれば、健康課と連携しながら対応しています。設置に関しては管理者の思うとおりではありますが、ただ一方で、たばこの煙が周囲の方々に影響しないような場所に設置するといった部分については。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問・要望","question":"区できちんと環境を整備するよう要望していただくという部分だと思うのですが、多分令和３年度から、始めていらっしゃると思うのです。設置は進めていきたいのかどうかという、たばこを吸う人を減らしていきたいのかどうか、伺いたいのですが。","respondent":"森田生活安全担当課長、高山健康課長","answer":"委員のご説明にありましたとおり、民間の喫煙所の設置の関係につきましては、本年から実施しています。受動喫煙も防がれますし、ある程度は必要であろうということで検討を進めながら、整備を進めていくという形で考えております。国民健康・栄養調査という国の実施している全国調査がございまして、令和元年、年を追うごとに喫煙率自体は低減しているというような状況にあります。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"施策がどうしても、最終的に私の質問の部分が陳情要旨２番の部分で、この文章からいいますと陳情要旨の２番の願意にかなうということです。陳情要旨２番にあるとおり、２番を進めていくことに関して最終的にどう思われているのかだけ、最後にご答弁ください。","respondent":"森田生活安全担当課長、高山健康課長","answer":"検討をこのように進めていきまして、３分の２の補助ですので、そういったところも加味しながら進めていきたいと思います。近隣区の状況も見ながら進めていって、民間の喫煙所の設置ができるような… 陳情の趣旨の２にあります、喫煙環境の整備という点です。喫煙所を設置するというのも１つの環境整備ですし、先ほど冒頭でご説明申しました、区としても協力してまいります。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる３０億円とか、質問をしても答える方がいないから、できないですよね。理由の中には税収でこれだけ貢献しているのだというふうに結構出ていますが、できないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"分かりました。では改めて質問しますが、まず陳情提出者の肩書きですが、そもそもどういうところなのか尋ねました。","respondent":"森田生活安全担当課長","answer":"申し訳ありません。こちらに陳情を頂いているということで、手配をしながら、中身を検討していこうということで考えております。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"あれは努力義務ですか、喫煙場所をつくるときにといいますか、努力しなさい、協力しなさいみたいな文言が条例の中にありますよね。それで、製造は分かりますが、販売というと、大元のところ、もしくは個別のお客様に売るところも、条例上は販売所という形になるのか尋ねました。","respondent":"森田生活安全担当課長","answer":"事業者などの責務というところで、条例でされておりますが、これにつきましては、製造・加工・販売などというところですので、該当するです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"ただ、陳情者の方たちからすると、いやいや、たばこ税で品川区には３０億円も納税しているではないですか。３０億円というお金を納税しているのだから、私たちは税金で、そういう形で協力しているわけだからというような趣旨で考えていいのか尋ねました。","respondent":"森田生活安全担当課長","answer":"委員のご意見も踏まえまして、あらゆるところにご協力をお願いして進めていくのは当然かと考えていますし、私どもでも不明な点、分からない点も当然ありますので、そういった意味ではご意見など、また質問などもしながら、適切な対応ができればということで考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"吸う人、受動喫煙など望まない煙等を受動的に吸ってしまう人のことを考えれば、やはりこの陳情というのはもっともだと思います。それとも、こういうことよりも、最初から喫煙を勧めているのだからというような考えになるのか尋ねました。","respondent":"高山健康課長","answer":"喫煙率が２割弱というようなところもありますので、この間の今後の取組みとして、やはり私も少々行っております。平成２９年に実施しました、大体６割いらっしゃったということがありますので、受動喫煙についても取り組んでいく必要があると考えております。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"今、答弁を伺いまして、すごくよく分かりました。やはり陳情の１で言っている公共喫煙場所の増設・維持・改善というのは、私はいいと思うのですけれども、健康課長はどう思いますか。","respondent":"高山健康課長","answer":"先ほど来のご説明の繰り返しになってしまうかとは思いますが、たばこを嗜好される方と、それぞれに対応していく必要があると考えております。そういった効果は認められるものですので、やはり当面の間、施策は継続していくべきものと考えております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"生活安全担当課長に要望というか、答弁を伺うかもしれないのですけれども、空き缶も含めてポイ捨て条例をつくったわけです。区に要望しますという陳情が区に来ているのですけれども、せっかく条例があるのですから、最後にその辺はいかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"たばこの煙害というところでも、勉強は私どももしていかないといけないというところではあります。引き続き、関係機関等にお伺いしながら、分析しながら、どうあるべきかというところにつきましても考えていきたいと考えています。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"陳情を出されている団体も含めて、どのような方にこういう助成制度ができたということを周知されてきたのかということを１点お伺いいたします。品川区の考え方として、この喫煙環境の整備が喫煙者を増やすためのものではないということを確認させていただきたいのですが、いかがか尋ねました。","respondent":"森田生活安全担当課長、高山健康課長","answer":"１つは、そのように進めているところです。先ほどのご説明と重なるところではありますが、また現場に行って、こういった制度がありますということも説明しながら進めてまいりたいと思います。こうした方々がご自身の意思で喫煙をやめられるというような後押しの支援として、たばこをやめる際に、健康増進の観点でいえば目的とするところです。","id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"周知の仕方を工夫していただきたいということと、せっかく予算をつけているわけですから、要望します。喫煙率は減ってきていると確認しましたが、そこは引き続き、また区としても取組まれるようよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問","question":"１点だけ質問します。派生する質問で、禁煙外来治療費助成金交付事業を行っていると思うのですけれども、こちらの進捗状況を教えていただけますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"一言、公共の場での喫煙や、オフィスも含めてパブリックな場での喫煙は、規制こそ強めるべきだと思います。健康への被害がある中で、新たな喫煙場所の増設は進めるべきではないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ伺いたいのですけれども、被害額が１億３,８００万円と記載がありますけれども、私は実態はこれ以上かと考えています。警察官でも結構ですけれども、相談してほしいという声かけも強めていただけたらと思うのですけれども、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"的には言えないところではありますが、これは被害防止のため被害を届け出ていただいたほうが、次の被害を防止する上ではありがたいかです。１つの手段ではありますが、ぜひとも防いでいきたいと考えていますので、今後とも周知にご協力いただければと思います。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"品川区での発生状況が出ていて、令和３年１月から９月末という期間ですが、そういうくくりではなくて、被害届が出れば所轄の警察で調査してくれると思うのですけれども、大体でいいので、検挙の状況はどうなっているのか尋ねました。","respondent":"森田生活安全担当課長","answer":"警察が現場の設定をして検挙したというのが、７６件で昨年の２倍ということで、検挙率も上げてはいるところではあります。そういったところでは、検挙もする、防止もするという両面で被害防止を図っていきたいです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"防止という意味だと、これだけ所管で、オレオレ詐欺ではないですかみたいなメモ帳も、固定電話に貼るシールなども出してくれていますよね。その辺を分析等しているなら教えていただけますか。","respondent":"森田生活安全担当課長","answer":"区でいろいろな予算措置をし対策を進めていることについては、必ず効果が出ていて、それ以上の被害を防いでいると考えております。今後とも私どもで検討、研究しながら進めていきたいと思います。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"どういうふうにすれば効果が出るかというのは分かっているわけですから、一回きちんと整理して、まず最初は電話ですよね。その辺についても一回整理していただいて、また施策として打っていってほしいと求めましたので、その辺についてはいかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"特殊詐欺につきましては、新たな手口はありますが、基本的にはほとんど同じような手口です。どこがポイントになっているか、被害防止につながるのかも考えながら進めていきたいと思いますので、今後ともご協力いただけると助かります。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"警察から連絡があって、迅速にその地域に、場所に向かうという考えでよろしいのですか。そこだけ確認させてください。","respondent":"森田生活安全担当課長","answer":"その周辺で、今こういう電話がかかってきていますから気をつけてくださいというような、被害防止にあたる。警察から連絡が入ったら、私どもからパトロールしている生活安全パトロール隊に連絡して、すぐに現地に行ってもらうという形を取っておるところです。","id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。被害が多い状況の中、還付金に限定にした対策など、今やっておられれば教えてほしいと求めました。","respondent":"森田生活安全担当課長","answer":"先ほど私の説明では、警察でもやっていますが、チラシを貼ってたりしております。そういったことを様々やりながら、被害防止を進めていければと考えています。","id":"exchange-025"},{"speaker":"西村委員","kind":"質問・要望","question":"１０年間で半減したということは先ほどご説明があったのですけれども、この１０年間の比較を見て思っています。実際にどのようにかかってくるものなのかを教えていただきたいのと、詐欺のカテゴリー、また詐欺の中にはどのようなものがあるのかも説明を求めました。","respondent":"森田生活安全担当課長","answer":"ご高齢の方が昼間帯に在宅されているところについては、非常に留意しないといけないということで認識していただければと思います。様々な周知をしながら、対策を講じていきたいと思います。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問","question":"質問の仕方が悪くてすみません。近年の状況を伺いたいのが１点と、その辺り、どのようにキャッチアップして啓蒙活動をしていらっしゃるかを最後に説明を求めました。","respondent":"森田生活安全担当課長","answer":"手口としては、または消費生活センターでもこういったもののメールの対応などもしておりますので、様々なところで対応できるかと。１つ、これは考えていただいて、ご家族で申し合わせていただけると非常に助かるかです。","id":"exchange-027"},{"speaker":"くにば委員","kind":"質問","question":"自動通話録音機について伺いたいのですけれども、４,７００台設置ということで、現状の伸び率の推移というものをまず説明を求めました。","respondent":"森田生活安全担当課長","answer":"緩やかな伸びではあり、また、そういった強弱もありますが、今も借りに来ていただいています。大体の方は設置していただいているのであろうと思うのですが、今後も自動通話録音機というものを促進してまいりたいとは思っております。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問・要望","question":"そういった詐欺被害が０件に抑えられましたみたいなご答弁があって、４,７００台設置して、被害に遭われた方がどの程度減ったのか。４,７００台を貸し出した中で、設置した方がどれぐらい被害にまだ遭っている方がいるか、その数字的な部分をお教えいただきたいです。","respondent":"森田生活安全担当課長","answer":"は相手が誰であるのかは、ナンバーディスプレーなどで確認していただいて、その上で対応していただきたいというのをすすめているところです。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問","question":"もろもろの数値を伺ったのですが、今どれぐらい取られているのかというのも伺いたいのですが、携帯販売の事業者なのです。１つ別のアイデアというか、その２つの手法を考えたのですけれども、その辺について何か所感があればお知らせください。","respondent":"森田生活安全担当課長","answer":"その５つですけれども、人が集まるところの方が普及効果が高まるであろうということで、それにつきましては検討しながら進めたいと思っています。今後もそういったご意見を踏まえた検討を進めながら対応していきたいと思います。","id":"exchange-030"},{"speaker":"新妻副委員長","kind":"確認","question":"２点お伺いします。今の時点では、自動通話録音機にまだ余裕、空きがあるのかということを確認させてください。","respondent":"森田生活安全担当課長","answer":"ＡＩ型の自動通話録音機ですが、当初５０件の予定です。全ての方に設置できるかといいますと、今後も募集をまたしまして、５０台設置できるように進めていこうと考えています。","id":"exchange-031"}]},{"id":"topic-03","title":"東京２０２０大会レガシーとしての旧東品川清掃作業所の暫定活用","agenda":"東京２０２０大会レガシーとしての旧東品川清掃作業所の暫定活用","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"旧東品川清掃作業所の建物を上手に活用してやられているということでよいのかご説明いただきたいのと、事業者決定、ご説明いただけたらと思います。それ以降、状況が分からないので、補足的にご説明いただけたらと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ですので、現在、その場所をごみ中継所からスポーツ施設なり観覧所という用途に変更するために必要な工事というものが出てきます。は築３０年を超えたような施設ですので、それからパラスポーツの方も使えるような仕様に変えていくというような工事を予定しております。","id":"exchange-032"},{"speaker":"中塚委員","kind":"確認","question":"一言、委員長に、今期は無理でも来期にでも、どこかのタイミングで現地を確認できたらと思っています。それは意見で終わりたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの施設が２階建てになっているのですけれども、１階に清掃車が入る広い大空間がございまして、そちらを主に使おうと考えています。５年程度だろうということで、一応、目安を５年としています。","id":"exchange-033"},{"speaker":"新妻副委員長","kind":"質問","question":"１つは、予算的なところがどれぐらいなのかというのを教えてください。常に誰か人がいて、何か展示物などがあって、ふらっと寄ってみようかということができるような整備をしていただけるのか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから用途変更に伴う、一定程度進める部分に関しましては、２,０００万円弱ぐらいを予定しております。こちらもまだ検討中なのですが、そこが３,０００万円程度ということですので、それよりは少し高くなるのではないかと考えています。","id":"exchange-034"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"東京２０２０大会のレガシーとしてということでありますので、地域の方がちょっと寄って、そこは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西村委員","kind":"質問・要望","question":"今ご質問にもあったのですが、そういうものが利用できるということなのかどうか伺いたいのと、要望も含めてお伺いしたいと思います。東京２０２０大会のレガシーということですので、そういったことも、今後のにぎわいイベントとしてご検討いただきたいと考えています。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"横幅が１４メートルぐらいで、パーツ、パーツのトレーニングで使うことができるかと考えています。今、委員からご要望のあったようなマルシェ的なもの、ゆかりのある地域や国のものを出すというようなこともあわせて考えていきたいと思っています。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どういった活動をするのかということを教えてもらいたいのと、あともう一点が、ここは飲食を伴うような場所となるのか。やはり運河沿いだと、飲食もあったほうがいいのかと私は思っているのですけれども、お分かりになれば教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと、先ほどもお話がありました、そういった方がそこで展示をする展示会的に使うということも考えられると思います。なかなかまたハードルが高くなるので、例えばイベントのときにはキッチンを出すとか、そういった形での提供はできるかと考えています。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2914#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":32835,"voices":119}},{"id":"r03-20211129-7","meetingId":"r03-cm11","date":"2021年11月29日","dateIso":"2021-11-29","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件整理しています。","topics":[{"id":"topic-01","title":"第６８号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"第６８号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これが５,０００万円の寄附を頂いたということでありますけれども、しゃべれる範囲で結構なのですが、もう少し教えてほしいと求めました。障害者の方にというようなことになったのかというような、分かる範囲というか、しゃべれる範囲で結構なので教えていただけますか。","respondent":"松山障害者福祉課長","answer":"このたび寄附者の方が障害者福祉基金、障害者福祉の進展のためというご意向がございました背景についてです。区と運営事業者に大変感謝しているということで、その背景がございまして、このたびご寄附を頂いたものです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお伺いしたいのは、最近、例えば区立もあれば私立もあるではないですか。その決め事のようなものがあるかなと思うのですが、その辺のところが分かれば、ちょっと教えていただきたい。","respondent":"松山障害者福祉課長","answer":"施設の中でも、今回は区のほうにまず最初にお話を頂きまして、区立の障害者施設の入所施設といいますと、区内ではかがやき園１か所です。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"それでもう１点、例えば私立があるではないですか。これはごめんなさい、障害者福祉課ではなくなってしまうかもしれないのだけれども、例えば高齢者施設で、私立などがあるではないか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"一般論としてお答え申し上げますけれども、そのような意味ではその施設設置者である区のほうに、このような形になっております。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"これも一般論でいいのだけれども、このようなことがあったときというのは、例えばそのようなときに、よく表彰制度のようなものがあるではないですか。そのようなものというのは、こういう福祉部門の寄附などがあったときは、そのようなものはあるのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"設置者はもちろん区ではありますが、法人があっての結果だと思いますので、区として何らかの形でそのことはお伝えする必要はあろうかというふうに考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"これまでも寄附された、こうした基金を使ってきたと思うのですけれども、障害者福祉の分野では、この間どのように使われてきたのかということを伺いたいということと、あと、これから今回の寄附金をどのように使っていくかということは、もう考えているものはあるのか、そこをお伺いします。","respondent":"松山障害者福祉課長","answer":"２点目ですけれども、やはりこれまでもそうでしたが、本人のご意向に沿って活用するということになろうかと考えています。やはり区立施設に入所されて、ご本人からは、障害がある方の施設等を整備する際にぜひ活用してほしい旨を伺っております。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"それを少なくするためにこのうちの家族が寄附したお金が使われた感じがして納得いかないというような思いが寄せられたのです。なので、こうして寄附される方々の思いというものを聞く機会というのは、そしてこのように使いますと事前に伺う機会というものはあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"区としてもコミュニケーションを図らせていただいて、ご意向を十分にお伺いして、納得された形でということでお話をお伺いしています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"そのような意見を聞いて、寄附された方が亡くなっている場合というのは、その意向というものは遺族になるのですか。確認する手だてはあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"あくまでも寄附者のご意向ですので、あくまでも区として、受領した際に確認をするという形になっております。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"つまり、この障害者福祉基金は、この全体の条例の中の一部でしかないので、例えば高齢者の方の施策に使えるのですか。第１条の社会福祉のために使うというように書いてあるのは、別表の全てにわたるということでよろしいのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"例えば別表の６つ目ですね、矢部久子高齢者用社会福祉基金、こういった基金名にしているということであります。障害者福祉のために使うということを明確にするために、このような基金名で区別をしていると、このようなことになります。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、何か私、不勉強で。条例の立てつけがこれでいいのかなと思ったので、その点だけとの意見を述べました。","respondent":"寺嶋福祉計画課長","answer":"より分かりやすい内容となるように、今後の工夫、研究とさせていただきたいと思います。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"まず全体的なところで伺いたいのですけれども、それぞれ現行とした、この特別な理由というものを伺いたいのです。まだ全部の説明が終わっていないのですけれども、全体的なところとして伺いたいと思って、特別な理由は何かということを伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"まず今年の４月に改定されました基本方針の中に、公募によらず特定の事業者を選定することができるものとする」というように明記をされております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。有識者を２名それぞれ入れて審査をされていますけれども、これ、あと任期はあるのでしょうかということを伺いたいです。","respondent":"宮尾高齢者福祉課長","answer":"指定管理者の予備委員会、選定委員会というものは、その都度施設の案件があるごとに組織をいたしまして、やっているものです。我々が選考を進めていくに当たって、そのテーマに精通された方を、今回お二人の方を外部からお招きしたです。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"これ、どのような基準で選考したのか、その項目ごとの点数も出していただけたらと思ったのです。情報公開で請求するとそれは出てくるのですけれども、委員会資料として出せないのか、出せない理由があるのか、ちょっと伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"助言をいただいたというところで、その中で、逆にこの方にぜひお願いをしたいというところで決まったという経緯があります。今回は今年の４月に指定管理の手続きのありようが大きく変わった中で、様式でご報告、ご審議をいただいているです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"それぞれどこで何点だったのかということが分かる資料というものは出していただけたらと思うのですが、情報公開で請求すると出るのです。ですけれども、普通に資料としてホームページに出している区もあるので、その辺、品川区はできないのかというところで、伺います。","respondent":"宮尾高齢者福祉課長","answer":"その４人のトータルが、小山地域密着型多機能ホームの場合には１０ページに記載のもので、トータルとして記載をさせていただいているものです。繰り返しの答弁になりますが、そこは今回はこのやり方でということのご報告、ご審議をいただいているところです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それぞれの（５）のところにある、それが、その最後のページに添付されている項目で採点されているということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"確認","question":"新しいので、これを見ているとどこがどのようにつながっているのだろうということがちょっと分かりづらいところもあったので、この選考基準に基づく採点表というものは、この後ろに別添でつけられている基準で採点されたものということでいいかということを確認したいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"この中に書いてある、職員の意欲向上につながっているようにあるのですが、研修制度や資格取得支援の具体的な中身というものは分かるでしょうか。客観性・公平性・個別性に配慮した入所調整というように書いてあるのですけれども、待機者はどれぐらいいるのか、分かりますか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"基本的にはお話をいただいた順番に、空きが出たときに一番最初の方からどうですかというようなお声がけをさせていただいているです。２番目、３番目の方に対して、我々は高く評価をさせていただいているところです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その具体的な中身、介護福祉士資格の取得率が８０％と書いてあって、人員配置数も基準より高くしているということなのでしょうか。分かれば教えていただきたいということと、あと離職率も低いというようにあるのですけれども、どれくらいなのか、説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"大体１４％台から１６％台で推移をしているところなのですが、こちらの小山倶楽部につきましては、１０％台で推移をしております。中でも常勤職員につきましては、令和２年度は６％台ということで、こちらも職員に対してしっかりと対応しているという結果です。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３８ページに書かれていますが、どれぐらいなのか、分かればお答えほしいと求めました。何か介助中にも事故が起きたというところでは、虐待の危険性はないのかなというような心配も見えるかなと思ったので、伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"上大崎特別養護老人ホームにつきましても、やはり開業当初というものは高いのですが、２年目、３年目となるにつれて、離職率は下がってきております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"上大崎特別養護老人ホームで、開設当初、そのときには私たちのところにも、こうした内出血等々の相談があったのです。なので、今、家族の皆さんから問題にされたりなどというようなことはなかったのかということを伺います。","respondent":"宮尾高齢者福祉課長","answer":"まずはその原因をしっかり突き止めること、それから、その事故に対して施設がどのような対応を取ったのかということです。報告、それで、まずその初期の対応がしっかりできているかということをしっかり見させてもらっています。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。ちょっと違う視点の質問なのですけれども、総合点数がこのように２５点も差があるのですけれども、この理由をもし伺えたらお願いします。","respondent":"宮尾高齢者福祉課長","answer":"併設しているクリニックとの連携ですけれども、様々な点で、日常の運営のベースの中に連携というものが組み込まれているところです。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、１つだけ。真ん中の３番ぐらいはそのような感じがするのですが、４０点になるにはどうやるのかということを、もし教えていただけるならばお願いします。","respondent":"宮尾高齢者福祉課長","answer":"１２ページの評価項目・配点表を例に挙げしますと、真ん中ほど、大きい３番のところに項目が３つ記載があるかと思いますが、その一番上です。","id":"exchange-021"},{"speaker":"若林委員","kind":"意見","question":"その点数に引き続いて、総合点数の満点が４００点で、これは公募によらないということなのですが、その点数が低ければ、当然一定の判断をしないといけないと思うのですけれども、その辺の基準というか、考え方をちょっとお示しくださいとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"例えば今回の基本方針の中には、次の５年間も任せるにふさわしいというように、ある程度はもう判断をさせていただいているところがあります。","id":"exchange-022"},{"speaker":"若林委員","kind":"確認","question":"これはもう数字ですから比較するしかないのですけれども、１２ページの、これが１つのラインですよね。どうなのかなというものが、法人の体質などというふうにも逆に見てとっていいのかどうか、これはちょっと確認します。","respondent":"宮尾高齢者福祉課長","answer":"決して現状に満足することなく、よりよい施設運営をという、この結果はその１つの材料になると我々は思っております。ですので、結果に満足することなく、常によりよいケアというところは、この結果を活用させていただきたいと考えています。","id":"exchange-023"},{"speaker":"若林委員","kind":"確認","question":"「１：問題がある」「２：やや問題がある」、これはちょっと確認するということと、押しなべて選定委員会のほうが点数が高めの傾向かなと。その辺も含めて、ちょっと感想なり、ご様子をお聞きしたいと思います。","respondent":"伊崎福祉部長、宮尾高齢者福祉課長","answer":"資料のほうになかなか浮き上がらせにくいところですが、予備委員会では書面による審査でございまして、やはりここで何点か疑問の点が出てまいります。その点に対して、それで疑問点が解消されるというところで… 私からは委員会の選考の過程に応じて、評点の１と２がどのぐらいの割合でついたかですが、今回の４施設に関しては、全ての委員で、１と２をつけた委員というのはおりませんでした。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それでまた離職率も低いとなっていますよね。そのようなメリットを区としてどのように全体として活かしていくかというような、そのような考え方はあるのか、ちょっと伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"このような課題が見受けられた、皆さん気をつけましょうというような、やはり横展開する。この今回のことで分かったことをしっかりと周知徹底していくことが、我々に与えられた使命かなと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１５人や１８人などの看護師の体制があった思いがしているのですが、その体制というのは今どうなっているのか。充実をされているために、そのような状況というものも分かったら教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"かなりこちらの施設についても、感染症予防という観点からも、しっかりと対応ができているというふうに感じております。そこのクリニックとの連携という考え方については、変える必要は全くない、しっかりとこの体制を維持していくようにと考えているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"入所３年まではかなり高いということが一般的で、数字、先ほどご答弁いただいていましたでしょうか。例えば区のほうから虐待の心配があって調査に入ったとか、そのようなことはないのか、そこの確認だけさせていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"こういったものもしっかりと捉えておりますので、こちらについては引き続き、数字については注視してまいりたいと考えています。これはやはりあってはならないことだと考えていますので、こういったところも、あった場合には徹底をしています。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、もう３年を超えてしまっても３５％の離職率というのは、その原因というのはどのようなところにあるのか。３５％というのはかなり高い数字のような思いがしているのですけれども、その原因はどのようなところにあって、ちょっとその点について伺います。","respondent":"宮尾高齢者福祉課長","answer":"まずそこをベースに考えて、そういったことを想定して採用しているというような人事交流制度をあらかじめ採用しているというところもあります。それが、これはやはり看過できない課題だというふうに捉えておりますので、そこはしっかりと対応してまいりたいと考えています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"では、例えばこの上大崎から名古屋のほうに戻るとなると、それは離職率に入ってしまうのですか。いろいろな要因はあったにしても、働きにくい職場というようなことがあるのかなという思いがするのですけれども、その点はどうなのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"まず物差しを１個設定しないと、ほかとの兼ね合いの面でも、そのような取り方をさせていただいているところです。それをもって、例えば離職率の高さをもって、職員の処遇面に何か課題があるなどというようには捉えておりません。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"新生寿会が６％台ということと比べても、ちょっと多いかなという思いがしているのです。働きやすい職場で離職率を下げるような取組というところでは、ぜひ区としても取組を進めていただきたいということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-02","title":"第７３号議案、指定管理者の指定","agenda":"第７３号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"この資料の施設側の提案内容が、この理由がもし分かれば伺いたいということと、改善の努力はどのようにされたのかということを伺いたいと思いますとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"２点目の職員に対する改善のところですけれども、また事業者のほうも、課題として認識をしているところがあります。１つには課題をしっかりとお互いが、区と事業者とで共通に認識をし合って、日々のやり取りの中でもしっかり取り組んでいくべきだと考えています。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"意見","question":"現状に満足せずにというところでは、やはりどんどんスキルアップなり、ほかの施設等のいい部分を参考にしていただいて、ぜひ評価点数を上げていくという、そういった部分も新たな報告書の中でも運用できるようになったなと思いますので、その辺はよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"財務状況は、この１か所の大井林町地域密着型多機能ホームだけを取って見ているのではないと思うのです。その辺の違いを教えていただきたいなと思っていて、これの意味合いというものは、どこを見てやっているのかということです。","respondent":"宮尾高齢者福祉課長","answer":"その両方を見て、今回の評価というようになっているところです。財政面で区が支援すべきところは、やっていく、検討していくつもりです。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"このさくら会だけではないけれども、ほかの施設は結構支援しているという施設があるではないですか。そのようになってきてしまうではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-03","title":"の順序を変更いたしまして、(7)第７７号議案、指定管理者の指定","agenda":"の順序を変更いたしまして、(7)第７７号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ここにある６２ページの、やはり採点表なのですけれども、財務状況評価が１００点満点でいうと６０点という状況です。プレゼンテーション、ヒアリング等を行った後に下がっていくという状況というものは、どのような理由なのかを伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"予備委員会、そして選定委員会の委員がそれぞれ採点するものでありますので、そこの捉え方の違いによるものかと思われます。先ほど地域密着型多機能ホームの候補者とさせていただいたのですが、全く同じ点数で予備委員会２８点、選定委員会２４点という形で採点しています。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"詳細になるということなのでしょうか。そのような状況で低くなってしまう点が、大丈夫なのかなというか、不安な部分があるのですけれども、これはどのように見ていらっしゃいますか。","respondent":"菅野高齢者地域支援課長","answer":"こちら、評価基準となるものの財務分析結果は、同じものを基に採点をしてもらっております。大きく違うところは、選定委員会のほうは外部の有識者の委員の方がいらっしゃるというところで、少し厳しく採点されたというように判断しております。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは１,０００万円ぐらい出ているという、財務状況評価がこれだけ点数が低いという理由がちょっとよく分からないのですけれども。ここだけで判断するのではなくてという、そのようなことで見るのか、ちょっとそこの理由を教えてほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"入居者の方の利用料や、あとは区のほうから出させていただいている家賃助成金等で、歳入のほうは賄っています。先ほどの評価につきましては、そういったルールの下で点数をつけているので、こちらの施設についてはプラスが出ているという状況です。","id":"exchange-037"}]},{"id":"topic-04","title":"第７６号議案、指定管理者の指定","agenda":"第７６号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"何か変わることがあるのかというところを伺いたいのですが、そこの変化だったり、あと事業の中身がどう変わってくるのか。職員体制も、どういった職種の方が何人ぐらいの体制でやられるのかということをお伺いしたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"継続する必要があるという事業については、すり合わせをして、利用者の方が不安にならないような事業展開をしていきたいと考えています。昼間は３名程度の勤務、指定管理者とは、その後の体制については調整していきたいと考えているところです。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その程度でもいいので教えていただきたいということと、そうするとどのような事業ができるのかということにつながっていくと思うのですが、そこを具体的にお知らせいただけたらと思います。","respondent":"菅野高齢者地域支援課長","answer":"それと施設管理費ということで、約９００万円ということで、実績ベースで事業者たちのほうにもお示ししています。大崎ゆうゆうプラザ規模の施設の運営をある一定数しているというように実績は出しております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"提案","question":"分かりました。（４）のところには「具体的な提案内容を聞いて審査をお願いしたい」ということで、どのような提案内容だったのか、お伺いしたいと思いますとの意見を述べました。","respondent":"菅野高齢者地域支援課長","answer":"やはり書面上ではなかなか具体的な部分が分からないところが多く、こういった形の報告、委員の意見となっております。全館型、全年齢世代型のイベントをしたりなどというような、具体的な提案を出していただいたりなどはしました。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"この４９ページのほうには、ここは大丈夫なのか、選定委員会では担保となるものが示されたのかということを伺いたいと思います。そしてなぜＣ評価なのか、どのような観点で評価するのか、伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"事業者経営分析の部分のほうからご説明します。もう一つは、その辺りのことをきちんと説明を受けて、その体制だったらこの人件費でも大丈夫なのかなということの判断をさせていただいた次第です。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"Ａだと何で、やはり何をどういった観点で評価をして、ぜひそういったところもそれぞれ資料として出していただけるとありがたいなと思います。人件費のところは、言われたから信用するのではなくて、何か担保になるようなものというのは示されるものなのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"１つ目の、私はご説明させていただきましたが、今後こういった表現をするときには気をつけていきたいと考えています。ヒアリングの中でもいろいろと聞き取れましたので、その辺りのところで大丈夫だということで、こちらのほうは判断しています。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、１つだけ。基本方針を改定されたので、それについてここの所管のお話で結構ですので、ほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"外部の方が入っているということで、この２点はやはり非常に大きな進歩というか、取組だったというふうに福祉部としても考えているところです。","id":"exchange-043"},{"speaker":"若林委員","kind":"提案","question":"指定管理者制度については以前から幾つかお話、提案や質問もさせていただいています。これは要望ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、１点だけ教えてください。何か、こちらは契約の問題もあるのかなと思ったりもするのですが、なぜここだけ違うのかなと思って。","respondent":"寺嶋福祉計画課長","answer":"特に今ご指摘のような違いがあったという認識ではないですが、したがって福祉部長が委員長になるということはないということが全庁的な仕切りです。代理という言い方もおかしいですけれども、総務部長にそのときに来ていただけたという、このような理解です。","id":"exchange-045"}]},{"id":"topic-05","title":"第７８号議案、特別区人事・厚生事務組合の共同処理する事務の変更および特別区人事及び厚生事務組合規約の変更","agenda":"第７８号議案、特別区人事・厚生事務組合の共同処理する事務の変更および特別区人事及び厚生事務組合規約の変更","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"更生施設を順次救護施設に転換していくという変更の理由が書かれているのですけれども、体制の違いを伺いたいのですが。更生施設と救護施設の人員配置などを具体的に伺えたらと思うのですけれども。","respondent":"櫻木生活福祉課長","answer":"入所できる方の人員で人数等も変わってまいりますが、１００人定員の更生施設で申し上げると、職員配置は総数で１４名という形になっております。配置としましては、施設長、事務員、主任指導員、介護職員、看護師、栄養士、調理員、嘱託医という中身になっております。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。対象とする方が違うのですけれども、救護施設になることで、更生施設に入っていた方が出なければならないような事態にはならないのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"基本的に、まず順次改築していくということではあります。依然として、既存の更生施設に入られている方が出されるということはなくて、救護施設の基準で支援を受けるということになろうかと思います。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今更生施設を使っている方は、救護施設に転換されていくときに救護施設を利用できるということでいいのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"ほかの更生施設に転所される可能性もありますし、引き続きそこの救護施設の中で受けたいということであれば、一定期間は当然救護施設の中で支援していくということになろうかと思います。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"この更生施設、品川区でいうと、どこになるのでしょうか。救護施設は区内にあるのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"救護施設に関しては、区内および２３区には設置がございません。更生施設については、浜川荘という特人厚の施設がございまして、場所的にはなぎさ会館や大井競馬場近辺という形になります。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今その浜川荘にいらっしゃる方々は、すぐに救護施設にはならないと思うので、当面いられる状況なのですけれども、救護施設に転換していくときも、その方々は、今更生施設を使われている方は救護施設も使えるということになるということでいいのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"基本的に順次転換していくということで方針は決まっておりますが、全てが転換すると決まっているわけでもございません。今回の方針の大前提ですので、個々の状況の判断になりますが、救護施設にそのままいらっしゃるという方も当然いらっしゃると思います。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと１回確認なのですが、更生施設を順次救護施設にしていくということは、改修時なのか。その辺のところを分かるように教えてもらいたい。","respondent":"櫻木生活福祉課長","answer":"特人厚のほうで加配という形で、人員を少し基準以上に手厚くして、何とか対応してきたというような状況です。ただ、いつまでもいわゆる加配という形で対応をしていくということもなかなか困難な状況ということで。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問","question":"今言った令和 ９年、そこをどうやっていこうということなのだけれども、更生施設というのはブロックでやっているのではなかったですか。その辺も教えてほしい。","respondent":"櫻木生活福祉課長","answer":"今回ご提案させていただいているものは、生活保護受給者で居所がない方々の入所先の話ということで、別の話です。法定で４分の１を負担するケースはあるのですが、若干の運営費増等の可能性は考えられるところではありますが、そのようなことではございません。","id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国が７５％の区が２５％、ホームレスなどということであれば、東京都が２５％ということで考えていいわけですよね。その確認が１点と、浜川荘の現在の職員体制を教えていただきたいということと、どの程度いらっしゃるのかということも教えていただけたらと思います。","respondent":"櫻木生活福祉課長","answer":"それと、浜川荘自体の定数につきましては把握できていないのですが、現時点で各区で３人加配がついているという状況です。定数は１２０人です。","id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"３人加配がついているのかということを一つ教えていただきたいということと、例えば介護の、浜川荘などというようにはなかなかならないと思うのです。そのようなところをどう考えていくのかということも、併せて伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、浜川荘は既に１４名以上の職員体制にプラスして３人いるという、そのようなことでされているということでいいのでしょうか。看護師ですとか、そこの定数は、介護職員と看護師の定数がどれぐらいなのかというようなところも教えてほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"浜川荘に関しましては、１２０人ということで、当然定数、１００人定数以上の人員を確保された上で、さらに加配が３人ついているという状況です。救護施設については、２８名中、介護職員が１７名、看護師１名という配置になっています。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"意見","question":"議案には賛成なのですが、やはり更生施設が必要な方もいますし、救護施設が必要な方もいますので、更生施設をなくしていきながら救護施設ではなく、やはり更生施設も残しながら新たに救護施設をという形が望ましいのではないかなと思いますので、そうした意見を付して賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"}]},{"id":"topic-06","title":"第６４号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第６４号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"いろいろ検討されていくということですが、イメージができるようにと思ってお聞きしたいと思います。この実施内容の（１）のところに、事務局はどこなのか、取りあえずまずそれを伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"資料の実施内容、１圏域当たり２０事業所ぐらいの緩やかなグループをつくらせていただいて、そういうところを考えております。３点目の事務局ですが、ＮＰＯ法人の品川ケア協議会のほうにその事務局機能をお願いしたいというところで、検討を進めているところです。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"この１,０００万というのは１年間のものではなくて、２０２１年度の予算で、丸々１年度で見たらもっと入る補助金なのか。なぜ品川ケア協議会にしたのかということと、それと、どのような人員体制で事務局を担ってもらうのかということを伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"今回のこの１,０００万円ですが、令和３年度としての事業経費ということになりますので、また改めてということになります。今回この東京都の要綱を見たときに、効率的に執行できるというように判断をいたしまして、今回のこのような事業スキームに至ったです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、６圏域つくるわけですけれども、そこにこの事務局が入っていくという形なのですか。それとも皆で集まる感じになるのか、ちょっとどのような形で計画作成までに至るのかというイメージをしたいのですが、お願いします。","respondent":"宮尾高齢者福祉課長","answer":"ノウハウは、基本的にケア協議会も様々なノウハウをお持ちだということは我々も認識していますし、今回。品川ケア協議会からその６圏域の中核となる事業者とで、まずいろいろ検討、このようなことをやっていただく。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"１の背景のところの最後にあるのですけれども、要は区が事務局をやろうとすれば、そこに補助金が入るという仕組みとしても捉えていいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"そのような事業構築をした区市町村に東京都が補助をする、このような立てつけになっておりますので、区が事務局を担うという想定にはなっていません。そこの大本の制度設計、それから、そこはしっかりと取り組んでまいりたいと思ってあります。","id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１か月３００万円くらいになると、人員体制というものはどのぐらいの体制が取られるのか、その辺のところも教えてください。それと比較的規模の小さい介護事業者１２０事業者ということなのですけれども、１２０事業所の種類を教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"今年度は令和３年度として東京都から１,０００万円頂けるという見込みを立てておりまして、やはり人件費のところが一番大きくなってまいります。あくまでも予定ではありますが、非常勤職員を５名ないし６名程度採用していただくような形で考えているところです。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"このようなＢＣＰ計画などをつくっていくということだと、もう既にそれ以外のところというのはできているというように考えていいのでしょうか。それは具体的に、このような形でつくっていくということを、私たちとしてはイメージを持てばいいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"いろいろ考え方があるかと思うのですが、そのような状況があることが、今回事業を組み立てようと思った理由の１つです。に、横の連携を取るためのきっかけとなるものをつくりたいということで、今回提案をさせていただいているところです。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その辺のところはどうなっているのかということと、実施内容のところには、ここも進めていくということも入っていますよね。１件当たり幾らという形で計画をつくるというようなことで、今回の中で具体化していきたいという、そのような中身で考えていいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"そのときに、１人の高齢者に複数の介護サービス事業者が関わっている方というのも、決して少なくありません。１対１ではなく、高齢者１人の方に対して複数の事業者がうまく有機的に関われる、そのような狙いもこの事業には込められております。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"個別計画の支援者をどうするかということは、そのようなところを連携を取りながらやっていこうということはすごく大事なことだと思います。全ての事業者を対象にして把握をして、このような計画をつくっていけるということでの把握もしながら、ぜひ支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、それはもう実績があるわけだから、それはできるのだろうけれども、ただ今度この中身が大変ではないですか。要望しておきます。","respondent":"宮尾高齢者福祉課長","answer":"短時間でいつも滞りなく実施をできると、こういった実績も、今回この事業を品川ケア協議会にお任せしたいという理由の１つです。この事業は東京都も基本的に３か年度取り組んでほしいというように言っているぐらいの、丁寧に検討していきたいと考えています。","id":"exchange-065"},{"speaker":"高橋（し）委員","kind":"質問","question":"３か月ですからどこまで立てられるか分からない。どのような形で、翌年度も含めての計画になるのだと思うのですが、その辺はどのような思いでこの事業を進めようとされているか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"今年度は、もちろん検討は検討で進めていくのですが、まず今年度はその土台をつくらせていただきたいと考えています。これからの、品川ケア協議会も含めて、あと東京都とも協議しながら進めてまいりたいと考えています。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"意見","question":"品川ケア協議会だけでは非常に難しいので、今お話があったように、区のほうで協力してといいますか、うまく詰めていって、３年度終わった段階で全部の事業所が計画できるように、非常に大変な作業だと思うのですけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"若林委員","kind":"確認","question":"ちょっと確認ですけれども、東京都のこの１,０００万円の枠でやるのは、今の報告も含めて、実施内容の（１）だけでいいのですか。今、１２０という数字ばかり出ているのですけれども、全体としてどのぐらいの事業所があるのかも確認をお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"あくまでも今回の資料の実施内容に記したところの（１）から（３）、ということは、当然に報告の必要も出てくるのかなというふうに捉えております。検討の余地があるかと思うのですが、一方であまりにも拡大をし過ぎてしまうと、事業の進捗自体に影響が出かねない。","id":"exchange-068"},{"speaker":"若林委員","kind":"確認","question":"特にこの（３）の個別計画の絡みで、複数の事業所が１人の利用者というのですか、被保険者の方に関わっている。そこは１,０００万円がどうのこうのではなくて、決してあなたは１２０の外だから、そのようなことがないということの確認を。","respondent":"宮尾高齢者福祉課長","answer":"まさに今、委員のおっしゃるとおりです。その１２０が、もし１２０に入っていない事業所がいたら、それはもう決してあってはいけないことだと考えています。","id":"exchange-069"},{"speaker":"せお委員","kind":"質問","question":"集団接種会場は１回目、３回目の集団接種会場なのですけれども、看護師が打つというところで変わりないのですか。そこだけ説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"集団接種会場での運営については、医師が予診、看護師が接種、そして薬剤師が分注という流れは、基本的には変えない方向で、今、調整を進めている状況です。","id":"exchange-070"},{"speaker":"せお委員","kind":"質問・要望","question":"看護師の意見が伝わらないというか、私も３回従事して、２回目のときには看護師ノートというのができていました。こうしてほしいのだけれどもというようなものが伝わらなくて、ぜひそこをちょっと気に留めていただきたいなと思って、そこだけ要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"意見","question":"３回目は、別に１回目、２回目と同様ではなくてもいいというようなことも言われていると思うのですが、それは選べるのかということと。８か月以上経った方から順次打っていくということになると思うので、一気に聞きましたけれども、その辺をお願いしますとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"この辺は、今後検討とか調整を進めてまいりたいというふうに考えております。予約サポートについても、地域センターを含めて、本庁舎も含めて、現在調整等々を進めておりまして、そちらの方向で現在検討を進めております。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":61856,"voices":276}},{"id":"r03-20211129-8","meetingId":"r03-cm11","date":"2021年11月29日","dateIso":"2021-11-29","committee":"建設委員会","time":"午前１０時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件整理しています。","topics":[{"id":"topic-01","title":"第６９号議案、品川区手数料条例の一部を改正する条例","agenda":"第６９号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"長期使用構造等の審査を省略できるということになっておりますけれども、この省略できるのはなぜかというところを伺いたいと思います。建築確認申請も、こういった民間が審査をしてやる仕組みがあると思うのですが、そちらもこうした省略などをしているのかどうか伺いたいと思います。","respondent":"長尾建築課長","answer":"現行制度ですと、分譲事業者が各住戸を売買した後に変更の手続を共同して行う必要があります。その売却が進んでいなかった住戸が売れた後、またその後、変更認定の申請をするということが必要なくなるということになります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"民間の評価機関のところで重複するものを１回で済ませるということだと思うのですけれども、行政のほうでちゃんと基準にのっとっているのかということが確認できなくなってしまうのではないかというふうに思ったのでお聞きしたので、そこのところをもう１回伺いたいと思います。","respondent":"長尾建築課長","answer":"民間の性能評価機関のほうで技術的な審査を１回行っておりますので、ちゃんとチェックして、その場合は審査を省略できるということになります。所管行政庁に技術的な審査も併せて申請される場合は、当然、所管行政庁のほうで技術的なチェックを行うことになります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"結局、行政のほうでの審査は省略できるというお話だったと思うのですが、そうすると、行政のほうで、出された申請にミスがあったということをチェックできないのではないかというふうに思うのですが、そういったフォローをするシステムはあるのか尋ねました。","respondent":"長尾建築課長","answer":"制度的な仕組みのお話になりますけれども、ダブルでチェックするということは、原則的にはやる必要はないというふうな仕組みになっております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"そもそものところをお聞きしたいのですが、認定方式の変更のところで、そもそも住戸単位で認定をしていた理由は何だったのか伺いたいと思います。この手数料が上がるのか下がるのか、どちらも、上がる場合も下がる場合も理由を伺いたいと思います。","respondent":"長尾建築課長","answer":"住戸ごとの変更認定というところで言いますと、都度の変更が必要ですし、制度が住棟単位に変更されているということになっております。都内２３区、今回、東京都の手数料の設定に合わせて変更をかけているものです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"手数料が変わったのは東京都の金額に合わせたということなのですが、その東京都が変わった理由もあると思うのですけれども、そこを伺いたいと思います。","respondent":"長尾建築課長","answer":"東京都が手数料を見直した背景といたしましては、審査をする、技術的な審査の人件費に当たる部分の見直しというふうに聞いております。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"それは上がるほうも下がるほうもということか尋ねました。","respondent":"長尾建築課長","answer":"おっしゃるとおり、上がるほうも下がるほうも両方です。","id":"exchange-006"}]},{"id":"topic-02","title":"第７０号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第７０号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、容積率の指定が載っていないのですが、この条例案に容積率の最高や最低限度について記載がないのはなぜなのか伺います。容積率、従前の容積率が何％で、今回、道路や広場を設けることで何％緩和されて、今回、建物がどのような計画をされているのか伺います。","respondent":"長尾建築課長、多並都市開発課長","answer":"建築基準法の中で条例に定められるもの、定められないものが設定されておりますので、その考え方に沿って設定しております。容積率の最高限度については１０分の５２、また… 今の補足ということでご説明します。広場１号、区画道路１号等を整備することで、総合的に判断したものです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"条例上に定めるものになっていないということだったと思うのですが、そこの定めるものと、定めないものの違いは何なのか伺いたいと思います。こうした東京一極集中を進める超高層ビルはやめるべきだと思いますけれども、いかがか尋ねました。","respondent":"長尾建築課長、多並都市開発課長","answer":"条例の中で定められる内容につきましては、建築基準法の施行令のほうで具体的に定まっております。法律の中で条例に定めるものとして例示されておりませんので、今回、地区計画図書の中には出てきていないということになっております。全体的に開発の進め方ですけれども、土地利用の大きな方針の中と、歩行者ネットワークについての整備の計画があります。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"壁面位置の制限などは、歩行者の安全を確保するということで理解できます。それぞれいろいろ地区で幅員があるのですけれども、とりあえずこの青の歩道上空地１号、幅員６.５ｍ、この幅員の根拠などを説明を求めました。","respondent":"長尾建築課長","answer":"歩道上空地の１号、６.５ｍというところの根拠ですけれども、平成４年にこちらの東五反田地区の更新計画が設定されておりまして、その内容を踏まえた上での幅員、道幅の設定というふうになっております。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問","question":"分かりました。１つお聞きするのは、１００ｍを超えてはならないということで理解するのですけれども、基準になるポイントの考え方を説明を求めました。","respondent":"長尾建築課長","answer":"こちらは建築基準法の中で地盤面の高さの捉え方が決まっておりまして、その基本的な考え方と同じ内容になっております。その高低差の平均値といいますか、その平均値を地盤面の高さと設定して、そこから今回の建物の高さは１００ｍ以内ですという考え方になります。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"ちょっと今のと関連するかもしれませんけれども、壁面の位置の制限とか、それから、高さの制限、これは何か計算値とかはあるのですか。何かしらの、先ほど、平成４年で決めたとかという道路の幅がありますけれども、その出し方の根拠は、どういうところからこれが出てくるのか尋ねました。","respondent":"多並都市開発課長","answer":"この検討につきましては、大崎地区全体の中で、道路ネットワークの発生交通量を計算して、まず必要な道路の確保をします。現実に合った形で更新計画を踏まえ、よりプラスな形で確保していただくということで整えていく、そのような段取りを進めているものであります。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"１号から６号になっていますけれども、これ、高さも同じなのです。では、その数値はどこから出てきたのですかということなのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"もう一度詳しく説明しますが、敷地内でも人が安全に歩ける場所ということで、双方で考えていく。最高限度の中でという形で、そういう計画で進めている、そういうところです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"そうなった場合に、そこの制限のかけ方によっては、高いものを建てられなくなるような、そういうこともできるという理解でいいのですか。誰が決めるのですかと言ったときに、ここの地域は、５０ｍにしようというふうに決めることができるのか。","respondent":"鈴木都市計画課長","answer":"ここは例えば２０ｍにしましょう、その地区内ではそれ以上建てられないという考え方で進めるという考え方は、地区計画そのものの考え方にあります。","id":"exchange-013"},{"speaker":"塚本委員","kind":"確認","question":"すみません、ちょっと基本的なことを確認させてください。Ｂ地区以外の残された地域は、今、どういう扱いになっているのかということを説明を求めました。","respondent":"長尾建築課長","answer":"地区計画そのものの中で、特にまだ建築に関する制限が定められていないところですので、今回は条例の中での制限を位置づけることはいたしません。仮にその地区計画が変更されて、その変更の後に、そういうような流れに基本的にはなっております。","id":"exchange-014"},{"speaker":"塚本委員","kind":"確認","question":"そうすると、そこにものを建てようとする人たちがいたから、このようなことでよろしいでしょうか。それを確認させてください。","respondent":"長尾建築課長","answer":"委員おっしゃるような流れで、今回、Ａ地区、Ｂ地区については制限が課されたです。","id":"exchange-015"},{"speaker":"芹澤委員","kind":"確認","question":"基本的な確認をしたいのですが、図面の広場１号というところの、そういうものはどこで決められていくのでしょうか。この広場の在り方というのは、どこで誰が、関わりを区が持つのか尋ねました。","respondent":"多並都市開発課長","answer":"開発を進める際には、高度利用ということで容積の緩和を図りながら、よりよい計画となっていこうということで誘導しているものです。広場１号ということで、その要素ということで、貢献のもとでやっているものです。","id":"exchange-016"},{"speaker":"芹澤委員","kind":"質問","question":"どういうふうに使っていくというのが、あと、区がそこに関わりを持てるのかということを説明を求めました。","respondent":"多並都市開発課長","answer":"公共空間であるので、容積の緩和とかの貢献のメニューになってあります。これは敷地を見ながら、区としてもいろいろ協議しながら進めているということで、最終的にこのような形になったというところであります。","id":"exchange-017"},{"speaker":"のだて委員","kind":"意見","question":"規制緩和により、地方からヒト・モノ・カネを吸い上げて、東京に集めて一極集中を進める計画でもあります。様々な悪影響をもたらしますので、こうした超高層ビル計画を可能とする改正ですので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"のだて委員","kind":"提案","question":"議員が事業者を選ぶということにもなりますので、資料をしっかり出してほしいと求めましたけれども、いかがでしょうか。そして、今回、事業者からどういう提案がされたのか伺いますとの意見を述べました。","respondent":"竹田住宅課長","answer":"できるだけホームページ等で公表していきたいと考えておりますが、今回は、詳細についてはお示ししていないところです。個々の状況に応じた対応を行うなど工夫が感じられている点や、すぐに職員と連携を図り、一連の対応の流れができているという点が高評価の点です。","id":"exchange-019"},{"speaker":"のだて委員","kind":"提案","question":"選定委員会は２回やられておりますけれども、公的施設の管理者を選ぶというものですから、予備委員会も含めて公開にすべきだというふうに思います。そして、今回、事業者からプレゼンやヒアリングがあったということですので、どのようなことが行われたのか伺いますとの意見を述べました。","respondent":"竹田住宅課長","answer":"可能な限りご説明したいと思うのですが、主に考え方や業務体制、それから団体の経営状況等です。組織運営や運営方針につきましては、ＳＤＧｓ等の社会環境も踏まえた運営方針が提案され、安定的な組織運営体制が期待できるです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"提案","question":"入居者管理経費というものも出されていると思いますので、その中の人件費率、あと管理コスト削減プランなどの内容です。どういった事業者からの提案があったのか、区としてどういうふうに評価をしたのか伺いましたので、そこのところをお聞きしたいと思いますとの意見を述べました。","respondent":"竹田住宅課長","answer":"具体的な数字については、口頭では申し上げきれないのですけれども、区で想定しております適切な人員配置等はなされていると、あるいは、有資格者が配置されている等々確認できましたので、指定管理者としてふさわしいというふうに判断したところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"適切な人員配置というのがどういう配置なのかというところを伺っているのですが、ご答弁いただけますでしょうか。従業員の方の平均賃金ですとか、あるいは最低の賃金額が幾らになるのか伺います。","respondent":"竹田住宅課長","answer":"なかなかコロナ禍ですので、直接お会いできないケースもあるのですけれども、極力、状況について判断しております。一部の方、まとめてお話しできないというような方もいらっしゃいますので、電話で丁寧に聞き取るようにしています。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"ご存じでしたらご説明いただけたらと思います。そして、今回、応募したところが１者ということだと思うのですけれども、１者になった理由を伺いたいと思います。","respondent":"竹田住宅課長","answer":"こういったところを計画的に行うことによって、コストの削減に努めていきたいと考えております。それから……。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"どうやって利益を上げているかというところが具体的に説明がなかったのですが、改めて答弁があったら伺いたいと思うのですけれども、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"それから、株式会社というところで、どうなのかということですけれども、逆に株式会社だからこそできる自由性というところもあります。それから、指定管理という枠組みのメリットというのも最大限活かせるのも株式会社というふうに考えております。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"１つは、これ、区営住宅と区民住宅と両方やるということでの要綱になっているのですか。それとも別々なのか尋ねました。","respondent":"竹田住宅課長","answer":"こちらは、一括して公募して、ご応募いただいたところです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"なので、だから、この両方、区営住宅と区民住宅と両方やってくださいということで出したのか、それとも区住宅営は区営住宅、そして区民住宅は区民住宅ということで、それぞれ出したけれども、結局１者だったということか尋ねました。","respondent":"竹田住宅課長","answer":"区営住宅の管理および区民住宅の管理ということで、一括して公募したものです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"お願いするしかないではないですか、５年間経つわけですから。いかがか尋ねました。","respondent":"竹田住宅課長","answer":"１者については、辞退理由は、社内協議による判断、もう１者は、一部業務が実施が困難であると判断されたためというふうに伺っております。仮に１者だとしても、１者であっても、制度上の問題はないと考えています。","id":"exchange-027"},{"speaker":"西本委員","kind":"提案","question":"評価も見ると、例えば、提案内容評価は９５０点満点だけれども７４０点とか、総合点数は７８０点ではないですか。だから、そこをどういうふうに持っていくのか尋ねました。","respondent":"竹田住宅課長","answer":"事業者にとって、区が示した仕様に適切に対応できるのか、または採算がとれるのか等も、今回、判断基準になったと考えております。選考となる形が理想的なものと考えておりますので、仕様も含めて、どういった形が最善なのかということは検討していきたいと考えております。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"７割ですから、だけど、あと３割あるわけでしょう。これは要望として終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"本多委員","kind":"提案","question":"選定予備委員会の委員の意見の２番目に、２４時間３６５日対応できる提案となっている。６番目には、この１５年間の実績の中でこういったことがされてきたのか、そこだけ説明を求めました。","respondent":"竹田住宅課長","answer":"夜間・休日の件につきましては、専用の受付センターという、提携会社ですが、そちらに電話が入るようになっておりまして、これは従来から行っているものです。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"適切かどうか判断する資料が出されないということと、説明を求めても説明できないという状況です。区直営にするべきなので、両方とも反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"賑わい軸地区のほうの資料について伺いたいのですけれども、今度、これは案内のためのポスティングはするのでしょうか。そして、先ほど、意見書は３９通ということでしたけれども、賛成、反対などの態度などは何人だったのか伺います。","respondent":"多並都市開発課長","answer":"説明会の案内につきましては、広報でご案内します。地区の方には、ビラということでまかせていただく予定となっております。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり知らない方も多くいらっしゃると思いますので、ぜひビラをポスティングしていただきたいというふうに思うのですが、いかがでしょうか。１７条の説明会が、せめてお知らせぐらいしていただきたいと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"説明会の案内につきましては、地区内の方にお配りさせていただいています。その周辺の方につきましても、町会等へのご案内という形で周知はさせていただいたと思っています。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"十分な資料や説明がされないまま進められており、請願第１３号で都市計画手続きの中止を求め、請願第１４号は準備組合の民主的運営を求めるものです。ここで伺いたいのですけれども、第１地区の地権者と、そして借家人の方も同様に家族を含めた総人数を伺います。","respondent":"多並都市開発課長","answer":"１１０名です。第２地区のほうは、借家人の方の人数は聞いてございません。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料を求めても出さないということで、組合の名簿や規約の提出を求めても、いろいろ理由をつけて提供されませんでしたと。こうした説明してもらえないといった準備組合の運営が、やはりおかしいのではないかというふうに思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"小山三丁目第１地区のマンション、全部で５棟ありますけれども、各戸別にまたご説明をしていただいているということで報告を受けているところです。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこうした区の姿勢としては、情報提供をしていただきたいということなのかどうか、いかがでしょうか。そうした資料を渡していただきたいというふうに思うのですが、区として指導していただけないか尋ねました。","respondent":"多並都市開発課長","answer":"その中でしっかり説明させていただきたいと思っています。この説明会の中でご説明することになっていますので、改めて、しっかりご説明するようにということで。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校や病院が変わらなければならないということにもなりますので、こうした自分で探さなくてはならないというのはおかしいのではないでしょうか。伺います。","respondent":"多並都市開発課長","answer":"準備組合としては、引越しをする際の情報提供をさせていただいて、サポートをするということでお聞きしています。これについては、またお一人お一人の状態をご確認しながら、適切な判断をということになるかと思います。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"立ち止まって、住民の皆さんと全員で話し合うということが必要なのではないかというふうに思いますけれども、いかがでしょうか。マンション居住者の意思確認を行ってほしいと、こういったマンション住民の意思確認を行っていただきたいのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"地域の方の企画提案を受け、これから手続を進めていくということですので、中止する考えはありません。マンションにつきましても、マンションだけではなくて、そういう形で必ず法令に基づいた手続を進めていきたいと思っているところです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"それは中野区は強引に進めてしまったのですけれども、品川でもそういった同じことが起きかねないという状況だと思いますが、いかがでしょうか。ぜひこの再開発、ごり押しするのではなくて、住民の皆さんと話合いをして進めていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"その意見書が、先ほどご説明しました３９通で、賛成の方のご意見が２４通、反対の方が１５通、そういう手続の中でしています。次の、それはまた広く皆さんに説明して進めていくということで、しっかりご説明を聞かなければいけないという法律になっていますから。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうしたことで強引に進めていくのはやめるべきですし、実際、今でもやはりよく分からないことで悩んでいる方もいらっしゃいます。そうしたところで、この再開発をごり押ししていくということはやめるべきだと強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。この書面１枚で判断しかねるのと、区が中止をするというのもするべきでないという思いで、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"塚本委員","kind":"意見","question":"法によって定められた手続で進められているという中で、これを議会において中止ということを採択するということは、非常にやっぱり難しい。そういったものには当たらないと思いますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"大沢副委員長","kind":"意見","question":"今、塚本委員からもありましたように、法にのっとってこれは進められることであります。そして、法にのっとりながらしっかりと進めていくべき問題だと思いますので、不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"のだて委員","kind":"意見","question":"やはり十分な情報も提供されない。そして、このまま住み続けたいという方がいるもとで、着々と都市計画手続を進めるべきではないと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"１５件が反対ということなのですが、やはりスタートの段階がどうだったのかというところも含めて、やはり丁寧にすべきところもあったのではないか。教えていただいたこともありますので、今後、再開発をするときの１つの課題という形になろうかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。まちづくりは住民合意で進めるべきですし、民主的運営が必要ですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]},{"id":"topic-03","title":"令和３年陳情第５４号、広町地区開発計画に障害者支援施設の整備を求める陳情","agenda":"令和３年陳情第５４号、広町地区開発計画に障害者支援施設の整備を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"やはり一度立ち止まって、情報公開と住民参加で一から検討すべきものだと思います。この間、説明会などを行ってきたということで、参加人数と、意見書などの提出があった数、これを伺いたいと思います。","respondent":"多並都市開発課長","answer":"説明会ですが、地区計画の区域の中の権利者の方を対象とした説明会としては、１９名の方がいらっしゃっています。全区民の方を対象とした説明会は、９月２７日に行っており、このときの参加者が６２名となっております。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、広町地区のところでも、障害者施設の整備は可能だということなのか伺います。今回の計画ですと、道路などはあると思うのですが、公共施設については計画がないということになるのか、その点も伺います。","respondent":"多並都市開発課長","answer":"説明会ですけれども、事業者説明会ということで近隣の方にご説明した内容がありまして、これが今年の３月に行っています。委員の方のご意見も踏まえながら進めていくということになっていますから、そこも含めて総合的に考えていくべきと区としては考えているところです。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、障害者施設をつくるということも含まれるということなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"その協議の中に障害者福祉施設も含まれるということか尋ねました。","respondent":"多並都市開発課長","answer":"今、基本計画の検討中で、その検討経過を踏まえ、来年度以降、都市計画の協議をしていくということですので、これからしていくということでご説明したところです。","id":"exchange-050"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認します。それはどういう時点で話し合われて、いろいろ出てくると思うのですけれども、その順番はどうなっていますか。","respondent":"多並都市開発課長","answer":"どういう部署だとか、そういうものが集約していくかという、ちょうどこれから検討していく段階です。そこをどう取りまとめていくかということを決めていくところなので、その中で総合的に検討していくべきということで考えているところであります。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"広い意味で考えていただきたいというふうに思って、これは要望なので、要望です。要望なので、広い意味で考えていただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"芹澤委員","kind":"質問・要望","question":"障害者施設を区で入れる入れない、十分であるかどうかというよりは、広町地区に入れてほしいというようなお話で理解をしています。これからまさにどういった施設を入れるのか、十分検討をこれからしていただきたいという思いで、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問・要望","question":"結論は不採択でお願いいたします。最もふさわしいものを決定していっていただきたいという思いはありますけれども、ちょっと難しいというふうに思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"大沢副委員長","kind":"質問","question":"よりいい施設、様々な総合的な施設をつくってもらいたいと思いますので、そこのところは自由な発想ができるような形をつくってもらいたいと思います。よって、この特定の障害者の施設、これは分かりますけれども、今後の議論の流れの中、推移を見たいと思いますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。広町の開発計画は進めるべきではないですけれども、障害者施設の整備が必要ということは理解できますので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"西本委員","kind":"意見","question":"もうちょっと広い意味になると思いますので、決定経過を、やはり透明性のある決定経過であってほしいと思います。住民合意ということも非常に大切な視点だと思いますので、これはお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-04","title":"令和３年陳情第５５号、品川区長・都市整備推進担当部長・都市開発課担当主査以上３名による謝罪を求める陳情","agenda":"令和３年陳情第５５号、品川区長・都市整備推進担当部長・都市開発課担当主査以上３名による謝罪を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"区も同様に、再開発でないとごまかしていることも重大だと思います。このごまかして再開発を進めるのはやめるべきだと思いますが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"市街地再開発事業だけではなくて、共同の建て替えなど、様々なまちの課題を解決していく手法について勉強されているということで認識しています。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、勉強している段階ということですけれども、実際に住民は、この進め方に恐怖さえ感じていますと、この陳情にも書かれております。住民生活を壊すＣ地区は、中止をするよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。なかなか区議会から区長に対して謝罪を求めるというのは、少し違うのかなという思いで、不採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問・要望","question":"区職員等に謝罪というようなことが求められるというのは、それを審議するということ自体がちょっと筋違いというふうに思いますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"大沢副委員長","kind":"意見","question":"賛成、様々な意見があろうかと思いますけれども、当事者同士でよくお話をしていただくのが本来の筋ではなかろうかと思います。この３名を名指しして、３名ということで出されておりますけれども、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"のだて委員","kind":"意見","question":"住民の生活が脅かされるこの再開発をごまかして進めることは許されません。生活を壊さないでほしいとのこの陳情者の思いも分かりますので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"その矛先は、まちづくりですから、やっぱり住民サイドでまとめてもらわなければならないことだと思います。いろいろなサポートが必要ですから、非常に残念だなと思うと同時に、ご理解していただきたいということを非常に感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-05","title":"の１、議案審査を再び議題に供します。 (5)第８１号議案、指定管理者の指定","agenda":"の１、議案審査を再び議題に供します。 (5)第８１号議案、指定管理者の指定","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"実際に事業者からどういう提案がされたのか伺いたいと思います。予備委員会も含めて、議事録などもしっかり公開をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"先ほど説明をさせていただきましたとおり、記載がありますけれども、そちらに基づいてプレゼンテーションなどを行ってもらったというものです。","id":"exchange-065"},{"speaker":"のだて委員","kind":"提案","question":"全体の関係でということでしたので、ぜひ所管の課から公開するようにということで求めていただきたいというふうに思います。実際の事業者の提案内容なのですけれども、他社との違いというところもありますけれども、実際にここのところでどういった提案がされたのか伺いますとの意見を述べました。","respondent":"川口交通安全担当課長","answer":"先ほども説明させていただきましたように、また新たな利用者ニーズに対応するサービス、その辺の部分を。自転車の各駐車場における人員配置については変更がないのですけれども、その上の部分、やや不安があるのかというところでございました。","id":"exchange-066"},{"speaker":"のだて委員","kind":"提案","question":"人的配置が利用実態に即した提案になっているということがあったのですけども、それはどういった配置なのか伺いたいのと、事業者Ｂ。その中での人件費率を教えていただきたいのと、分かっていたら、ぜひ教えていただきたいというふうに思いますとの意見を述べました。","respondent":"川口交通安全担当課長","answer":"１つ目の、先ほどご説明させていただきましたように、各駐輪場の配置員は変わらずと。それで、今回の候補者である、通称「ＮＣＤ」と説明します。","id":"exchange-067"},{"speaker":"のだて委員","kind":"提案","question":"人件費率は４６％ということで、悪くなっていってしまうのかなというふうに思うのですが、そこのところをどうお考えなのか伺いたいと思います。それはどうやって利益を上げているのか伺いたいと思いますとの意見を述べました。","respondent":"川口交通安全担当課長","answer":"その金額が区のほうに、そこの部分に関して、委員がご心配されているような中身の部分はないのかなというふうに考えております。その辺は利用者の状況のバランス等も、全体を考慮しながら適切な運営を心がけていければいいのかなというふうな考え方です。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"それが何社あるのか伺いたいと思います。それぞれ人数などが分かりましたら、伺います。","respondent":"川口交通安全担当課長","answer":"それ以外につきましては、２つの会社があるのですけれども、人材派遣会社で、これが全体の６割から７割です。地元雇用を守るという趣旨で、そのような形で行っているものですので、そのようなバランス関係になっているところです。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問","question":"地元雇用を守るということなのですけれども、以前はシルバー人材センターのほうで管理していたと思うのですが、そういった形に戻していく必要があるのではないかというふうに思うのですが、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"全体的なバランスを考えたときに、利用者ニーズに対応するために、そのような形で指定管理者制度の中でやっていくのが適切なのかなと思います。","id":"exchange-070"},{"speaker":"塚本委員","kind":"提案","question":"そういった中でお伺いしたいのは、提案内容の評価のところで、品川区の現状や課題を認識していると。この現状や課題というのは、どういったものなのかということを教えてほしいと求めました。","respondent":"川口交通安全担当課長","answer":"どのように事業者として認識をしているかということと、例えば今、外国人の方の自転車の利用も増えております。そのような老朽化に対する更新の考え方がどういうところかという部分になるのかなです。","id":"exchange-071"},{"speaker":"塚本委員","kind":"提案","question":"まだオンラインというか、キャッシュレスができていないところは、幾つかまだ残っていましたか。どのような感じで今後進むか、こういった提案等もなされていたりするのであれば、その中身を教えてほしいと求めました。","respondent":"川口交通安全担当課長","answer":"大森駅の駅前のところと、あと、大井町のほうにも今年度導入をさせていただきました。今後、キャッシュレスの施設につきましては、全部の駐輪場に計画的な配備を進めていきたいというプレゼンテーションがあったものです。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"時期的なものは、ある程度示されているのですか。どれぐらいでどこまでやるかみたいな話がもしあれば教えていただければ。","respondent":"川口交通安全担当課長","answer":"申し訳ございません。今後全てのというところははっきり書いてありますので、この指定管理の５年間というところの考え方でよろしいのかなというふうには思っております。","id":"exchange-073"},{"speaker":"西本委員","kind":"提案","question":"そういういろいろな管理できる提案という形なのですけれども、これ、どういう仕組みになっているのでしょうか。実際そこにいて、仕事をされている方がやっておられると思うのですけれども、そことの関係性はどういうふうな提案がなされているのか尋ねました。","respondent":"川口交通安全担当課長","answer":"既存で品川区で使っている精算機ですとか、ラックについては、そのまま引き続きその使用を行うというものです。入替えというような話にもなったりする場合もあるのですけれども、今回の場合につきましては、そのような提案ということになっておりました。","id":"exchange-074"},{"speaker":"西本委員","kind":"提案","question":"いろいろこの提案されているという、例えば空き状況が分かったりとか、ＱＲコードが使えたりとかというのは、いい提案だと思うのです。そのトレーニングであったり、指導であったりというところは、どういうふうにされて評価をされたのか尋ねました。","respondent":"川口交通安全担当課長","answer":"例えば地元雇用を行いますというふうにはっきり明記されている中でも、年間を通じてやっていくというようなプレゼンでの提案がございましたので、そのような点は評価をしたです。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"ここはやはり、「研修をしています」と言うと、「本当ですか」と言う方もいらっしゃるのです。どういう方を現場に派遣するのかというところ、その人たちをどう研修とかをするのかということをチェックを入れた場合に、その辺はいかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"しっかりと今後も引き続き、確かに委員ご指摘のように、利用者アンケートはモニタリングでもやっていると報告をさせていただいているところです。利用者の方と、今後そういうところは、また引き続き対応していきたいというふうに考えております。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう観点よりは、やっぱり住民との折衝というか、直に会う方々のほうが大切だと私は思っています。でも、やっぱり評価の中ではかなりウェートを占めていただきたいというふうに思っておりますので、今後の検討課題という形でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"のだて委員","kind":"意見","question":"どんどん経費削減が進んでいくと、賃金まで下げられるようになり、区がワーキングプアをつくり出すことになりかねません。利益向上を追求する株式会社は、公的施設の管理者としてなじまないので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"}]},{"id":"topic-06","title":"令和３年陳情第５７号、しながわ水族館のイルカショー等の廃止および生体展示からの方向転換を求める陳情","agenda":"令和３年陳情第５７号、しながわ水族館のイルカショー等の廃止および生体展示からの方向転換を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"陳情に、実際にあったのかどうかを含めて、ご存じでしたら伺いたいと思います。実際に、課題などのところにも関係すると思うのですけれども、プールはイルカにとって狭いという状況なのか伺います。","respondent":"高梨公園課長","answer":"令和２年度に行いました将来検討におけるメンバーですけども、また、しながわ観光協会の会長にご参加をいただいて検討したところです。それぞれの検討項目の詳細といったところで簡単にご説明しますと、現状のしながわ水族館の課題についてご意見を伺い、議論をしたところです。","id":"exchange-079"},{"speaker":"本多委員","kind":"質問・要望","question":"今まで３０年間で、延べ１,９７４万人の入館者ということで、すごくいろいろな効果があったかと思うのです。担当の部署としまして、この１,９７４万人が、この３０年間にわたって受けた手応えを教えていただきたいのです。","respondent":"高梨公園課長","answer":"イルカの体の部位の働きを説明するだったりとか、実際にどのようなスピードで泳げるのだという説明をしたりというような形でショーを行っております。昨年度の検討の中でも、やはりイルカのショーというのは、しながわ水族館の目玉として皆様に認知がされているところです。","id":"exchange-080"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"そこで、実際の担当、運営されている公園課の課長として、これは「イルカショー」という単語は、どうしてもイメージするものが誤解されるような感じ。子どもたちの学習効果を求めつつ、親しみやすさということですか、そこのところを教えていただきたいのですけれども。","respondent":"高梨公園課長","answer":"このように早く泳げるのだ、ショーも１つの展示という意味では、展示というくくりの中で行っているものというふうに認識をしています。子どもたちを含め、大人に対して広げていただく場として水族館は存在しているのではないか、このように感じているところです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、その本体のほう、サンシャインの運営は大丈夫なのでしょうか。会社全体の、今この大変な時期なので、ちょっと心配なのですけれども、その辺はどうなのか尋ねました。","respondent":"高梨公園課長","answer":"この間、急な状況で、すぐに経営状態が危ないというようなことは、お話しする中ではないかなというふうに考えているところです。将来検討の中でも、すぐに水族館をやめたいというような話を、意見を持っているといったところではないというふうに考えているところです。","id":"exchange-082"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ここでやめるべきとか、そういう話は不適当かなということで、不採択と思っています。私はぜひ前向きにやっていただきたいなと思っていて、いろいろな体験をしてほしいなという思いで、今回は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"塚本委員","kind":"質問","question":"様々な考え方があるのだろうというふうには思いますが、現時点でこういう姿が正しいのだというような結論めいたことはなかなか言えないと思います。この陳情も１つの意見として受け止めさせてはいただきますけれども、こういったこともしっかり評価されるべきだと思いますし、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"やはり水族館というもの、これは長年の月日を経て培われたノウハウもある、子どもにとっても大きな学習効果があります。先ほど、非常に学習効果の高いものだと思いますので、これについては不採択の理由にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"のだて委員","kind":"意見","question":"水族館などの展示動物、畜産などの産業動物、愛玩動物、実験動物、盲導犬、救助犬などの支援用動物、野生動物など、それぞれの分野で異なります。人と動物が共生できる社会を目指していくには、各分野の状況を情報提供し、認識の共有を図る必要があると思いますので、継続ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"私も区でやる意味合いは大きいと思うのです。追求するところがあるかと思いますので、私は継続的にやっていただきたいと思っていますので、今回は不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"のだて委員","kind":"意見","question":"生き物の持つ力や命を身近に感じることができるという見方もありますので、陳情に今回は賛成できないということで、不採択で結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":59473,"voices":262}},{"id":"r03-20211129-9","meetingId":"r03-cm11","date":"2021年11月29日","dateIso":"2021-11-29","committee":"文教委員会","time":"午前１０時００分～午後 ２時５９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません。これはそもそも所管質問にあたるかどうかも含めて質問したいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのご質問の中に、その保育園の数のご答弁作成にこちらの所管が関わっておられたのかどうか、それを確認させていただきたいのです。保育園の数が、所管の保育課と保育支援課が関わっておられたのか、それを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"だから関わっているかいないかだけでも私としては伺いたい。そうしたら、その後は個別に伺うことになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"その具体的なことについては所管が違うというのは承知しているのですけれども、建設委員会のほうの所管で保育園の数などを把握されたのか、それともちゃんとその答弁内容にこちらの所管が関わっていたのか、それだけ確認してからでないと、その先いろいろ質問ができないと思ったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それは尊重されてしかるべきなのではないかと私は思いますけれども、所管質問しますということを言うのであれば、しかるべきなのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"個人的な話で言わせていただけると、所管質問ということについて、あまり詳しくお話はできないかもしれないですけれども、私の中のイメージだと、子ども未来部に直接お話をして、それで解決してしまうのかなと個人的には思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ここに関わっていたのかどうかというのは、各所管が関わってそれへの対応をしていただきたいという思いがありましたので、ここで伺いたいと思ったということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"特にないですか。それは子ども未来部に聞いたのですかという話ですから、委員会ではなくてほかの形で聞いていただくようにお願いさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"それはいつかということをお伺いしたいのと、２点目は、それぞれ第８６号議案と第８７号議案で分かれば教えてください。それはよくないのではないかと思うのですけれども、そこら辺の影響について、区教委の認識を伺いたいと思います。","respondent":"工藤指導課長","answer":"そういった意味で、教育にかけるモチベーションが下がるとは考えてございませんが、引き続き働き方改革は進めなければいけないという認識です。本年の実質でいきますとほぼ同じなのですが、大体平均すると５万７,６００円という金額です。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"特に学校現場の場合はあまりに長時間ということと、長時間の上に教員が創意工夫を持って自分たちでする裁量権がないということなのです。その２つが大きな問題だと思っていますので、その両面から、ぜひそちらは強力に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"それと区採用教員と都採用の教員での待遇格差が出るということもあまり望ましくないということで、反対するものではありません。賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしても、教員の働き方とか幼稚園教諭の働き方などを考えると、このマイナスの額は平均ですけれどもかなり大きいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-02","title":"令和３年請願第１２号、品川区天然記念物第１５号戸越八幡神社ケンポナシ保存に関する請願","agenda":"令和３年請願第１２号、品川区天然記念物第１５号戸越八幡神社ケンポナシ保存に関する請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"教育委員会としては、この当該樹木の文化的価値についてどのように認識をされているのか伺いたいというのが１点です。その区民というのにこのマンション事業者はあたるのかということを確認させていただきたいのと、あと、そこら辺をお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"そのうちケンポナシとしては１件でございまして、昭和５３年ぐらいに調査し、現在でも天然記念物としての価値があると考えております。事業者については直接この区民というよりは、第４項のところで言っています関係者と捉えるほうがよろしいかと、考えているところです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"保存と公開と活用に努めていただくために努力してほしいと求めましたし、引き続き所有者の神社にしっかりとお話を伺いながら、ぜひ条例にのっとって進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"松澤委員","kind":"意見","question":"東京全体で見ても、このケンポナシというのはもしかしたら１本しかないかもしれないぐらい、大変貴重だということは聞いております。いろいろな課題がある中、こういう天然記念物というものをどのように品川区としては守っていくのかといったところを少しお話しくださいとの意見を述べました。","respondent":"有馬庶務課長","answer":"日常的な管理、そういったものには保護奨励金というものをお出ししたりしておりますので、そういったところでの管理もお願いしています。それから、そういったところに配慮していこうというところで対応してもらっていますので、そういったところはいろいろ検討してもらって。","id":"exchange-015"},{"speaker":"松本委員","kind":"意見","question":"先ほど現状変更という話が出たかと思いますけれども、これが今のところ現状変更にあたりそうなのかというところと、条例上は現状変更にあたると、教育委員会の許可が第１４条第１項で出てくるかと思うのですけれども、この辺りの対応は今どうなっているのか、お願いいたしますとの意見を述べました。","respondent":"有馬庶務課長","answer":"所有者の承諾を取って、事業者が変更届を出すということになります。それから、それを受けたら、区のほうは最終的には教育委員会にかけて、こういう形で変更します。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問・要望","question":"今軽微に当たるかどうかというところで、ぜひそこのところを条例上できる範囲内で解釈を頑張っていただいて、やってほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"その隣接している根っこの部分で、どういう形で根が地面で張っていくかというのは分からないわけだけれども、施工業者を含めてやっていただきたい。この辺りについては、今この条例上で区として積極的にやることはないのかもしれませんが、どういうところまでできるものなのか説明を求めました。","respondent":"有馬庶務課長","answer":"ここは我々もいろいろ調べてみたのですが、非常に難しいところがありまして、まず今回の建築確認はもう下りているのです。重要事項の説明の中に入るのかというところも調べたのですけれども、区の天然記念物のレベルですと、そこまでの責務はないようなのです。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"枝が出てくるから切ってくれとか、枯れ葉がどうだとか、いろいろそういう細かい話もまた今後出てくると思うのです。そういうトラブルが今後ないようないい形で進められればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"今後の住居者のところまで心配しなくてはならないということは、これが残るということですので、まずは残す方向で話し合いが進んでほしいと思います。品川区としてもまた別の専門家、樹木医の意見を聞くとか、そういうところまで考えておられるのかというのをまず伺いたいと思います。","respondent":"有馬庶務課長","answer":"これは所有者の神社があって、すぐに区が入っていって、そこでこういうやり方でという仲介ということでは制度的にはないのです。折り合いをうまくつけてもらうようなやり方を模索してもらうということで今考えていますので、今の段階では考えておりません。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、質問の仕方がまずかったです。区としては教育委員会としての判断だけではなくて、そこに別の立場の樹木医の意見とかも聞く予定はあるのかということを伺います。","respondent":"有馬庶務課長","answer":"これは軽微な変更ではないので、今所有者がそれでいいですよという承諾を取り、その承諾書を持って事業者が変更届を出すというその手続きです。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことが必要になった時にはぜひそうしていただきたいというのもあって、伺いました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。先ほどもいろいろお聞きしましたけれども、文化財保護条例に基づきましてしっかりと引き続き管理をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"つる委員","kind":"意見","question":"本日結論を出すで、採択です。所有者、そして隣接の事業者および後の区民となられる方々の調整をしっかりとお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択です。区民がはぐくんできた大切な地域文化を守るために、区としても条例に基づいて最大限努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほども言いましたけれども、これは区の天然記念物に指定されていますけれども、品川区にはほかにもいろいろ貴重な樹木があります。そういう時にはぜひ区としてもそれは残す方向で力を尽くしていただきたいですし、この請願を採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"令和３年陳情第５８号、品川区立学校図書館の充実に関する陳情","agenda":"令和３年陳情第５８号、品川区立学校図書館の充実に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区教委として、学校図書館の計画的な活用、授業での活用の重要性についてどういう認識をお持ちなのか伺いたいと思います。それにあたって、学校図書館運営支援スタッフの働きをどう位置づけていくのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"２点ご質問いただいたかと思います。それから、学校図書館の重要性につきましては当然認識していますので、しっかりサポートしていける体制を整えていこうと考えているところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"学校図書館運営支援スタッフという名称なのですけれども、改めてなぜそういう名前にしているのかという理由を伺いたいというのが１点です。授業の支援の上でも、今現状では、この運営支援スタッフに対してのネット環境はどのようになっているかというのも併せてお伺いします。","respondent":"吉田品川図書館長","answer":"実際は約８割以上を越えた者が支援スタッフの中では司書資格を持っております。その関係で、必要に応じて学校の教材系等から、インターネット等を検索していただくような形になっているところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"１５時間配置するという計画の根拠、なぜこのようにしているのかを伺いたいと思いますし、これはずっと変わっていないのか伺いたいと思います。それと併せて予算なのですけれども、その財源構成はどこかから補助金が出ているのかとか、その辺についても伺いたいと思います。","respondent":"吉田品川図書館長","answer":"学校と学校司書、それからボランティアの人たちが協力しながら進めていくのにあたりまして、現在はこの２.５日を基準にやっております。それから財源につきましては、一般財源が全てです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"生徒一人ひとりに端末を配っているわけですから、しっかり支援ができるように今後しっかりとネット環境を整えてほしいと求めました。１５時間ということですと、大きなところというのはクラスが多いわけですから、ほとんど配置されなくなってしまう。","respondent":"吉田品川図書館長","answer":"今回のこの学校図書館運営支援委託につきましては、平成３０年度から５年間ということで、総合評価方式で進めております。その関係で、１０年というところでまた見直していくというお話もあったと思いますけれども、今後必要に応じて考えていく部分だと考えております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほとんどその学校としては支援スタッフがいる中での図書の授業は受けられないということになるわけですから。もう５年とか１０年とか言っていないで、少しでも増やしていくという姿勢を私は持つべきだと思うのですけれども、何がネックなのか尋ねました。","respondent":"吉田品川図書館長、矢部教育総合支援センター長","answer":"学級数が多いところにどう対応していくかについて、現状何がネックになっているかですけれども、いろいろな面があると思います。それと学級数、一律にどれが原因ということもありませんけれども… 様々な条件の中で、時には区立の図書館に行って調べることができない子では仕方ないということで、やはり力をつけなくてはいけないと思うのです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"港区、大田区、渋谷区では４日ということで、２倍ぐらい配置しているわけではないですか。もうとにかくすごく仕事があるわけですから、スタッフが本当に学びの充実をする子どもに、ただでさえそういう現状なのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり指定管理契約が５年間ということで、５年間に関しては動かせないということが主な原因なのかというのを確認したいのが１点です。だから、学校司書の役割は増しているように思うのですけれども、その辺についてのご見解を伺いたいと思います。","respondent":"吉田品川図書館長","answer":"それから、現在までの学校司書と学校、それからボランティア、これはかなり密接に連携して進めてきたところです。今後、こちらの強化につきましては検討してまいりたいと考えています。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"要は新指導要領に基づいて、今後はそれを強化していくという見解でよろしいのでしょうか、もう一度確認させてください。学校のそういう教育の中で求められていると思うのですが、その辺についての見解をもう一度伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"は学年にもよりますが、児童・生徒相互にそれぞれ学び合うという機会としても大事なことなのではないかと思います。子どもたちは図書以外にも、様々な視点で、また機会としては市民科や各教科でリテラシーのほうも学んでもらいたいと考えております。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"学校司書がこういう資料を研究したらどうかと提供することも図書館司書の役割ですよね。ぜひ図書館司書がずっといてほしいと思うのですけれども、改めてそこのご見解を伺いたいと思います。","respondent":"吉田品川図書館長、工藤指導課長","answer":"その辺は、学校の図書委員だとか、またはスタッフだとか、いろいろな形でも学校では開けられるのかなと考えています。今後図書館の利用、その辺も含めまして、必要に応じて必要なところで検討してまいりたいと考えているところです。図書担当の児童・生徒が休み時間に開館するであるとか、また授業の活動においても、鍵と管理をしっかりしながら教員が行うこともできたりいたします。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、学校司書に司書の資格があるということは、やはり学校司書に求められている役割があるわけです。やはり必要だから資格があり、その人の配置というのが図書館に求められているのだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"松本委員","kind":"確認","question":"今の質疑の中できちんと確認しておきたいのですけれども、区立の小・中学校で、昼休みおよび放課後に学校の図書館が開いていないということが実際に事実としてあるのでしょうか、お願いします。","respondent":"工藤指導課長","answer":"あるいは場面もあろうかと思いますけれども、基本的にはそういった活動の中で、いわゆる学校司書がいるいないにかかわらず開館をするというのは活動の中で行っているです。","id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"自分が小さい頃を考えると、学校の図書館が少なくとも昼休みに開いていないというのは、私が育った環境ではなかったのです。昼休みに図書館が開いていないという状況を、教育委員会としては、それは別に問題ないと思われているのか伺います。","respondent":"工藤指導課長","answer":"それは開くべきであると認識しておりますし、それは活動の中で無理のない範囲でという言葉はもちろんつきますけれども、様々学校は工夫してできるだけ開くような体制で行っていくと認識しています。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"そうは言っても現実問題として開けていないというのは、私は区民の方から聞いてちょっと衝撃を受けたのですけれども、開けていないという状況はやはり問題だと思っていて、それについて何か今改善のための対策はされているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"これまでの回答のとおり、学習だけではなくて、居場所として開放しているケースが多いと認識しております。実態をつかんで、いろいろなところの教育にも関わると思いますので、図書館の活用については今後も進めてまいりたいと考えます。","id":"exchange-039"},{"speaker":"松澤委員","kind":"確認","question":"２点ほど確認したいのですけれども、例えば学校図書館というのは子どもたちが利用しますよね。学校図書館はどうですかというようなアンケート、図書館の利用をどう思っていますかというのは、教育委員会で聞いたことはあるのか尋ねました。","respondent":"吉田品川図書館長","answer":"利用について子どもに対するアンケートにつきましては、最近では記録にはないところです。学校司書とどのようにうまく連携が取れているかとか、学校の司書教諭の先生だとかを含めまして、そういったアンケートは実施しています。","id":"exchange-040"},{"speaker":"松澤委員","kind":"確認","question":"それともう一つ、要は学校図書館の利用率は大体どれぐらいの児童・生徒が利用しているか。学校の中でやるのか分からないのですけれども、そういうのがあるのだったら、確認させてください。","respondent":"吉田品川図書館長、矢部教育総合支援センター長","answer":"利用率という形だと、例えば一定程度年間にどのぐらい貸出しがあるだとか、そういうところの数値についてはつかんでいるところです。人数が多い学校と少ない学校では… 正確なデータは分かりませんが、個人での利用についてはなかなか把握できないのですけれども、基本的には図書の時間がありますので、学校図書館の利用は全員に近い数でされていると認識しています。","id":"exchange-041"},{"speaker":"つる委員","kind":"確認","question":"そういう受けとめを２年前の質疑の時に確認しながら思ったところですし、今日の質疑でも思ったのですけれども。把握しているかしていないかは別にして、聞いたことがあるのか、そういう部分であれば説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"子どもたちは読み聞かせについても大変集中して聞いておりますし、それぞれの各学校の中で、実態に合わせて大変充実しているように認識しています。読書の冊数についても、貸出冊数についても各学校でそれぞれカウントしていると認識しています。","id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"私も本屋出身ですから、図書館というのは対極なのか仲間なのかどちらか分からないのですけれども、本屋としては本を買ってほしい。ですから、その部分で考えていただきたい。","respondent":"吉田品川図書館長","answer":"そのためには、まずは例えば各学校では広報活動だとか、図書館だより等を作りながら進めていっているところです。１０年、今後拡充の方向で考えていければと、今検討しています。","id":"exchange-043"},{"speaker":"吉田委員","kind":"確認","question":"そこを確認させてください。それが少し気になったのですが、それだけ確認させてください。","respondent":"吉田品川図書館長","answer":"この中で、運営方針、運営内容等を定めて活動しているところです。その中には、そこの承諾の下という形をとっておりますので、一般的な意味でも偽装という形には当てはまらないものと認識しています。","id":"exchange-044"},{"speaker":"吉田委員","kind":"意見","question":"学校側も受託した運営事業者もその中でしか動けないというのは、それはやむを得ないというか、そういうことですね。臨機応変にその場で、例えばボランティアの方がそこで協議をして何か考えるということは、やはり難しいのですよねとの意見を述べました。","respondent":"吉田品川図書館長","answer":"現場の責任者と学校長、副校長や担当の司書教諭と話し合って、またそこで決まった内容で委託のスタッフにおろす。この辺につきましては、現在も臨機応変に行っているところでもあります。","id":"exchange-045"},{"speaker":"松澤委員","kind":"質問・要望","question":"ではしなさいではなくて、子どもたちが本当にどう思っているのかとか、そういった把握というのもしっかりしないといけないと思うのが１点。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほど質疑の中でも確認させていただきまして、先ほど確認させていただいたその段階で５年、文教委員会では不採択になっておりました。今、品川区がとっていただいている様々な方の関わりの中で、体制を充実するということをしっかりとさらに力を入れてやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"新しい学習指導要領の問題とかで、やはりもう学校の図書館に図書館司書、学校図書館に求められる状況は大きく重要性が増しています。２年前は２年前で、今回は私たち今のこの委員会で、これをしっかり採択していくことが私は重要だと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはあくまで区側がどういう資源を子どもたちに提供するかという視点で、ぜひそれは進めていただきたいと思って、そういうふうに言いました。先ほど、私自身もどちらかというと外で遊ぶよりも図書館にいる人だったのですけれども、今は子どもたちもみんな調べ学習とかが求められていますね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"学校の教員の皆さんが、あるいは学校の教員の方たちが自分たちで資料を探すというのも大変ですから、こういう書籍がありますと。学校の図書館が放課後、または昼休みに開いていないということがあるということを伺い、これもやはり大きな問題だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"それと、一本橋保育園のほうですけれども、ここは保育園の民営化対象園だと認識しておりますが、何園目でいつからの計画なのか伺いたいと思います。公立は維持すべきだと思うのですけれども、耐震性には問題があるのか伺いたいのと、この機能はどうなるのか伺いたいと思います。","respondent":"廣田子ども育成課長、初貝保育教育運営担当課長","answer":"エレベーターでベビーカーを乗せたりとかして、子ども連れでも上がれるように利便性が上がったというところが大きな変更点となっております。２階も少し使わせていただいて、狭くなった分… まず、民営化はこの一本橋保育園に関しましては４園目という形になりまして、時期は令和６年度から予定しております。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"４園目の保育園部分は民間委託するということなのですけども、なぜ耐震性には問題ないのに、その理由をもう少しお伺いさせてほしいと求めました。園庭を持つ区立保育園の転用を求めるような質疑があったのですけど、あとは転用について、今どんな検討をしているのか伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"建て替えに関しても、建て替えができるタイミングで順次建て替えをする必要があるというような認識の下、建て替えをしているというようなところです。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"必ずしも全部十分になることは難しいのは理解しているのですけども、その辺の機能の充実というのはなかったのか伺いたいと思います。例えばこういうような児童センターで比較的近いところがあるよとか、そういう情報提供とか何かそういうことはあるのか伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"中・高生はそこで３対３みたいなものができるというのも特徴で、本当にもともと狭いのですが、何とかやりくりして工夫はさせていただいたところです。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"子どもたちのほうも求めていたり、私たちが求めている子どもの意見聴取の役割を果たしているという、ぜひ今後も検討してほしいと求めました。休館中のフォローについては、ぜひ丁寧にやっていただくようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"安藤委員","kind":"意見","question":"東大井保育園等の移転は、老朽化による建て替えに伴う移転なので賛成ですが、一本橋保育園の移転はやるべきではない。したがって、全体の態度としては反対となりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"先ほどの態度と同じなのですが、こちらは進めるべきではない。区立保育園の民営化を前提として、民営化を進めていくための住所変更ということで賛成できないということで、全体としてこちらは反対となりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"}]},{"id":"topic-04","title":"第６４号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第６４号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"実施予定場所が今は、ファミーユ西品川子ども未来部分室は確定というかそれが使えるということで、そこでどれぐらいのお子さんが預かれるのか。それから、区内、今、調整中というのはどれぐらいを想定して調整しておられるのか、確認をさせてください。","respondent":"山下子ども家庭支援センター長","answer":"ファミーユ西品川につきましては、お部屋のほうは２つ、今現在あるのですけれども、利用といいますか準備を進めていくのは今、１室で考えております。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"今、区としてはどれくらいの規模を目指して調整に入っておられるのか、その辺伺いたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"調整に当たっている宿泊事業者の数ですけれども、今現状、直接に調整に当たっているのは１の事業者であります。いろいろな近隣の宿泊施設事業者と連携して対応しているところがございまして、複数の事業者のお部屋の確保に至れる可能性も残してはあります。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"それで、それだけのことを想定してこの金額ですよね、５４０万円。設置準備等経費というのは例えばどんな準備が必要で、この金額で賄えるのかなとかと思うのですけど、その辺の金額についても教えていただけますか。","respondent":"山下子ども家庭支援センター長","answer":"設置準備等経費といいますのは、こちらファミーユ西品川子ども未来部分室における準備の経費として考えております。支援委託の経費につきましては、保育サービス事業者への委託の支援員に対する時給的なところが、そちらのほうから算出した金額として。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"この間実際にこういう事業が必要とされるような相談というのですか、区民から寄せられていたということはあったのかというのを伺いたいと思います。罹患した保護者が違う所に移って、そこでお子さんを預かるということも想定しているという理解でよろしいのか、などについて伺います。","respondent":"山下子ども家庭支援センター長","answer":"４点目の、まだ幼いようなお子さんにつきましては、その辺りは臨機応変に対応していきたいと考えております。ご自宅で支援を受けられるというような形での調整が整えば、こちらのほうで支援員をご自宅への派遣という形で捉えておりまして、別途施設を用意して。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"２３区でどれくらいあるのか分かれば、先行自治体の実際の利用状況など、もしこれも分かれば伺いたいと思います。最後に、子どもの預かりという意味ではかなり専門性も必要なのかなと思うのですけど、そこら辺について不安はないのかというのは伺いたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"私のほうで把握している区としましては、７区ほどがこちらの支援事業のほうの準備ないし体制を整えているというふうに聞いてあります。２点目の宿泊事業者における子どもの預かりについてですけれども、今、支援の体制については安全第一で考えてまいりたいと考えています。","id":"exchange-061"},{"speaker":"つる委員","kind":"確認","question":"そこだけ１点まず確認させてください。明確にどちらなのだろうという、入院施設がなくてやむを得ず自宅になっている場合でも、この対象になるのかどうかを確認させてください。","respondent":"山下子ども家庭支援センター長","answer":"２、利用対象者の（１）の要件についてです。逼迫してしまって利用がかなわないといったような状況については、こちらの療養困難、療養を要しているというふうに捉えていきたいと考えております。","id":"exchange-062"},{"speaker":"つる委員","kind":"確認","question":"そうすると具体的にどういう資格を持っている事業者になるのかというところと、２４時間交代でどなたかの事業者が、ちょっとその辺の確認。それと、そのサービス事業者がどういう事業者なのかというのを説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"今いろいろなところを探し当てる中で、濃厚接触者に当たるような児童についても支援ができないかということで、少々相談を進めたところです。","id":"exchange-063"},{"speaker":"つる委員","kind":"質問","question":"教育委員会のほうでタブレットとかを使っての学習とかそういうことを、登園だとか登校は親がこういう状況だと当然これはできないという前提ですよね。やはり夜間のところというのですか、どういう想定があり、どういうことが可能なのかというところを説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"当初、宿泊事業者のほうについても、後からどこかできるところはないかというふうに検討に当たったところです。一定夜間帯見守りが必要なお子さんであっても、そちらのほうで準備が進められるように努めてまいりたいと考えています。","id":"exchange-064"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろ、工夫しているところを品川区もぜひ、そういう際に参考にしていただきたいなというところ。だからその辺のお金がどのように使われていくのかというところを説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"今考えておりますのは、あと、実際に支援が必要になった場合にその支援の経費についてお支払いをしていくというような二段構えで考えております。","id":"exchange-065"},{"speaker":"吉田委員","kind":"確認","question":"必要な事業だと思います。この予算額が、これでどうなのだろうかというのはさっきあったのですけど、今の質疑の中で確認できましたので、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]},{"id":"topic-05","title":"令和３年請願第１１号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和３年請願第１１号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"つる委員","kind":"質問","question":"現在は補助金の金額は１人当たり１０万円かというふうに理解していますが、この１０万円になったときというのがこの平成２１年度からでしょうか。今現在の１０万円になったときがいつからかというのをまず説明を求めました。","respondent":"若生保育支援課長","answer":"その後、その翌年の平成１９年４月、こちらで１０万円に増額したということで、それ以降は１０万円ということで変わらずという状況です。ですので、平成１９年４月に最後の増額、１万５,０００円を増額したです。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問","question":"平成１９年からですから、２００７年だから十三、上げていただいて経っています。それで、入園料の平均が昨年の答弁では１３万５,０００円とあるわけですけれども、この辺りの今の品川区の考え方を説明を求めました。","respondent":"若生保育支援課長","answer":"平成１９年度あたりの状況ですと、そういったことで１年間でこういった増額があったというところは、捉えているところです。それは社会情勢等も含めまして、今後も区のほうでも把握しつつ、必要に応じて増額というところも検討していきたいというふうに考えてあります。","id":"exchange-068"},{"speaker":"つる委員","kind":"確認","question":"私立の幼稚園側からのそういうベクトルというのでしょうか、特に私立ですからいろいろあるわけですけれど、保護者に対する支援というところでは。そしてそれを家庭で守っていただいている保護者の方にも通じるような、そういう幅広な支援を今後もお願いしたいというふうに、現状は確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"松澤委員","kind":"質問","question":"品川区としてはどれくらい具体的に、どういう感じでという、そういう把握というのはあるのでしょうか。説明を求めました。","respondent":"若生保育支援課長","answer":"いろいろな要素が考えられて、女性の方の就業率が上がってきているというところから、一定程度保育園のほうが受皿になっている部分があるのかなと。様々、その辺の状況については区としても、この分析を続けていきたいというふうに考えてあります。","id":"exchange-070"},{"speaker":"松澤委員","kind":"質問","question":"その中で、私立幼稚園協会などと品川区が直接お話するというのは、多分、各園同士ではないと思うのです。そういうのが、一園一園私立幼稚園と話合いをされるのか、その辺はどういうことなのか尋ねました。","respondent":"若生保育支援課長","answer":"私立幼稚園の各園の皆さん、あるいはその協会との連携といったところです。あるいは園の方が直接いらっしゃってご相談ということもありますので、そういった連携というか情報の共有、それからご相談等も行っているところです。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"区が把握するところでいいのですが、具体的にどういう活動をどれくらいされているのかということを教えていただきたい。区としてはそういう活動というのをどのように評価されているかについても伺います。","respondent":"若生保育支援課長","answer":"実際、直接やり取りするというところは、こちらの請願のタイミング以外はなかなかない部分ではあります。先ほどご説明で申し上げたとおり、保護者ですとか教員の立場から、教育の下支えというところで貢献していただいていると区では認識しています。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"常に私立保育園の補助金の使い方について、その関連で言うと、こちらについてもご説明をしていただきたいところが１個あります。それとも１人受け入れるごとにこういう補助金が出るということなのか、基本的なところを伺って申し訳ないのですけど教えてほしいと求めました。","respondent":"若生保育支援課長","answer":"あるいはその見込みのところを出していただいて、実施した後にこちらの実績報告という形で必ず一定の様式の書類を提出していただいて。そういった面で一定程度、そういった意味でチェックというのは今後、改めて検討して実施していこうというふうに考えているところではあります。","id":"exchange-073"},{"speaker":"吉田委員","kind":"確認","question":"この補助金は、例えば受け入れるから申請するということで報告が出ているというふうに理解してよろしいのでしょうか。ちょっと確認させてください。","respondent":"若生保育支援課長","answer":"心身障害児教育事業費の補助金は、あくまでも障害がある方が入園された後に申請いただくことになりますので、実際支給しているのにそういったお子さんがいらっしゃらないという状況はないというふうに認識しております。","id":"exchange-074"},{"speaker":"吉田委員","kind":"確認","question":"本日結論を出すで、採択を主張いたします。ご答弁で確認できましたけれども、それから幼稚園の運営にきちんとその補助金が目的どおり使われているかの確認は、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]},{"id":"topic-06","title":"令和３年陳情第５３号、新型コロナウイルス感染症に関する要望についての陳情","agenda":"令和３年陳情第５３号、新型コロナウイルス感染症に関する要望についての陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"いわゆる第５波が落ち着いて以降の感染状況の変化というのはどうなっているのかというのも併せて伺いたいと思います。伺いたいと思います。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"第５波が落ち着いた後に、１１月ですけれども、園児に関しては感染者が今のところ発生していないというような状況です。適切な消毒であったり、基本的な対策というところを徹底してまいりまして… 特に第５波、７月から８月末ぐらいにかけてというところでは、数園生じているというところは認識しています。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、なぜやらないのか、改めて理由を伺いたいというのが２点目です。ですから、その辺についてどうなっているのか、区立園、私立園それぞれについて伺いたいと思います。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"今までも保健所のほうと連携をしながら、適切な体制で必要に応じて検査をし、対応しています。は保育所等における新型コロナウイルスへの対応にかかるＱ＆Ａというところ、説明をして、その徹底を図っているというようなところです。 かなり密に連携を取りつつ、感染状況に応じて迅速な対応をしていますので、適宜状況に応じて対策も変化してくるものです。そういったところを随時、迅速に対応しています。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後の質問ですが、そこのところでもう１回伺いたいのですけど、改めて現在どうなっているかというのをちょっと確認させてもらいたい。もう一度、理由を伺わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"安藤委員","kind":"確認","question":"今のところ、確認したいのですけど、濃厚接触者と特定されなければ検査はされないということは変わっていないということなのでしょうか。私はそれを確認したいのと、この２点、お伺いさせてください。","respondent":"初貝保育教育運営担当課長","answer":"現在の対応といたしましては、きちんとご理解がいただけるように説明をして、ご安心していただけるような対応をしています。","id":"exchange-079"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、４番目の柔軟な対応、日割り徴収など柔軟な対応については、柔軟に対応しているはずというようなことでしょうか。そこだけもう一回確認させてください。","respondent":"若生保育支援課長","answer":"そういったところで実際のところ対応が行われているところですので、何らか区として、これは各設置者において適切に行っていただくものですので。","id":"exchange-080"},{"speaker":"吉田委員","kind":"質問","question":"そこで感染が広がる可能性があるわけではないですか。保護者の判断になりますけど、例えばそういうようなこともあっていいのではないかなということだと思うのですけど、その辺についていかがか尋ねました。","respondent":"立木保育課長","answer":"こちらをした場合にのみ、そのきょうだい関係で感染防止という観点からというところに関しましては、今後の課題なのかなというふうに考えてあります。今の状況では、日割りのほうはできないという形になってあります。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問・要望","question":"感染者の発生が落ち着いている今だから、やはりもう１回改めて、ぜひ要望を受け入れていただきたいなというふうに思います。費用の補助の考え方とか、ＰＣＲ検査の対象の広げ方とか、何かお考えあれば伺いたいです。","respondent":"若生保育支援課長","answer":"陳情の２番のところでの、区のほうでは、こういったものにかかった費用に対して充てられる形で補助事業を昨年度から今年度も引き続き実施しています。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問・要望","question":"ＰＣＲ検査の対象の広げ方についても伺ったのですけど、やはり保育という仕事がいろいろなほかの仕事に全部つながってくるわけです。そういう役割だということをぜひ認識して、今後ＰＣＲ検査の対象の検討をしていただきたいのですが、その辺についていかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"園で陽性者が出た場合、濃厚接触者を保健所等々で確認をして特定をして、というようなところで対応しています。区としてのＰＣＲ検査の考え方等を検討しまして、方向性だったり、保育所でのＰＣＲ検査の在り方など考えていきたいと考えております。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問・要望","question":"まだ言葉が不十分ですから、やはり表情でお互いコミュニケーションを取っている。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"松澤委員","kind":"質問・要望","question":"理由は、いろいろご答弁をお聞きしておりましたけれども、品川区は現状、第６波に向けても引き続き努力していただいていると思います。しかしながら、感染者の増加というものの拡大があると思いますので、引き続き気を引き締めて継続して、頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"つる委員","kind":"質問・要望","question":"ここに列挙されている６項目についても、１番については、確認ができました。これは国と自治体挙げてしっかりと対応していかないといけないところですので、それは引き続きしっかりとやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり検査体制というのは整えないと、本当にまた再拡大になりますよ、ということでやるべきだと思います。できる対策というのは本当に取っていただきたいですし、私はこれはやはりしっかり採択をして、対策を進めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。一歩踏み込んで、対策を今だからこそ強めていただきたいと思いまして、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"松本委員","kind":"質問・要望","question":"まず１番、安全ではなくて安心を求めるということであれば、無限に対象は広がっていくというふうに思います。２番のところですけれども、この補助金の交付要綱を確認したところ、そういったところも含めて不採択というふうに申し上げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こういった損害賠償金というのは自転車保険とかからは出ないものなのでしょうか。その２点、お伺いします。","respondent":"立木保育課長","answer":"これは園の職員が保育課のほうに出張をした帰り、園に戻る途中の事故です。それから、こちら損害賠償のほうですが、区が加入しております自治体賠償保険のほうから、損害賠償金として支払われたものです。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5048#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":68327,"voices":258}},{"id":"r03-20211129-5","meetingId":"r03-cm11","date":"2021年11月29日","dateIso":"2021-11-29","committee":"総務委員会","time":"午前１０時００分～午前１０時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"確認","question":"改めて伺いたいのと、協議の結果を伝えないということがあるのかどうかとか、そういうところを確認したいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"冒頭に申し上げたとおり、取り上げる順番を変更して、まず(2)第７１号議案 第二戸越幹線整備工事（上流部シールド）請負契約の変更","agenda":"冒頭に申し上げたとおり、取り上げる順番を変更して、まず(2)第７１号議案 第二戸越幹線整備工事（上流部シールド）請負契約の変更","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今のご説明では、あまり具体的な中身が分からなかったのですけれども、これは当初から予測できた変更ではないのですか。どうしようもない変更だったのか、その辺が分かるようなご説明をもし頂ければ頂きたいのですけれども、いかがか尋ねました。","respondent":"栗原河川下水道課長","answer":"説明の中でコンクリートセグメントから鋼製セグメントへの変更ということがございましたが、その後、その際に詳細に地盤改良の範囲を検討したところ。併せましてほかの変更につきましても、当初設計時点では予期せぬものでございまして、それを今回工事の中で変更しています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"では、予測できなかったものだという感じですけれども、こういう工事は大体、一般的にそういうものなのでしょうか。致し方ないというか、そういうふうに理解してよろしいのか尋ねました。","respondent":"栗原河川下水道課長","answer":"土木の工事では、設計段階では予期せぬことが起こって、それを設計変更にて修正していくということは、一般的に実施していることです。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"今の質問と関連するのかもしれないですが、変更が必要となった理由を知りたかったのですけれども、予期せぬ事態が起こって、鋼製セグメントに変わったということですが、予期せぬ事態というのは何なのですかということを知りたいです。","respondent":"栗原河川下水道課長","answer":"コンクリートセグメントから鋼製セグメントへの変更ですけれども、地下水のトンネルへの浸入を防ぐために、地盤を改良して止水を行います。その範囲についてまだ確定していないことから、次期工事の内容を踏まえて、今回工事の中で変更させていただいたです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"リニアの工事と隣接する場所でもあるのですが、その影響から工法が変更されたというのは、また全然別問題ですか。そことも関係があるのかどうかお知らせください。","respondent":"栗原河川下水道課長","answer":"今回の工事は上流部シールドということで、リニアの工事と場所が重複する区間につきましては下流部シールドでございまして、今回の工事の変更とは関係ございません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり地下でいろいろ崩壊といったらいいのですか、戸越幹線等についても、地下に空洞を空けて工事を進めるわけですから。今はもう衛星でできるわけですから、その辺は所管でしっかり研究して、今後対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"１件、聞き忘れてしまいました。工法の変更による安全性の担保の部分についてお知らせいただきたいのですけれども、安全性は確保されているのですかというところです。","respondent":"栗原河川下水道課長","answer":"今回の変更項目の中で、安全性に関する点というと、コンクリートセグメントから鋼製セグメントへの変更に関しましても。変更内容に交通誘導員の変更がありますが、安全に誘導するために交通誘導員を配置したことに伴う変更でございまして、今回の中で変更しています。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"そういうものは何だったのかということ、それで何が合意されたのか、その辺のことをまずお伺いしたいと思います。","respondent":"崎村人事課長","answer":"期末手当が０.１５月分引下げになるということに対しまして、やはり組合から、大分強い意見があったところです。こちらにつきましては、次年度以降の会計時期については改めて協議して検討していくというようなことで妥結しています。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"そういった点をお伺いしたいと思います。いかがか尋ねました。","respondent":"古巻総務課長","answer":"同じような内容で答申がされたということで、特に、もっと下げなくてはいけないといった意見は出なかったと認識しています。そういったことで、区は答申を尊重するという観点で、今回の条例案を出しています。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問・要望","question":"待遇改善の点、先ほども少し出ていたと思うのですけれども、今後も考えていってほしいと求めました。会計年度任用職員の待遇改善の点について何かございましたら、もう一度伺いたいと思うのですけれども、いかがか尋ねました。","respondent":"崎村人事課長","answer":"冒頭ご説明させていただきましたとおり、昨年４月から新しい、一般職の公務員という扱いで制度が開始されたところです。随時、その辺につきましては、我々の給与と連動するような形で設定していくものと認識しています。","id":"exchange-010"},{"speaker":"田中委員","kind":"提案","question":"やはり区議会議員と区長の条例を分けるべきではないかということを提案していたのですけれども、今この議論というのはどうなっているのかというところを確認させていただきたいのですけれども、いかがか尋ねました。","respondent":"古巻総務課長","answer":"私も聞いておりませんし、品川区議会議員の議員報酬、費用弁償及び期末手当に関する条例というのがあります。そのときの答弁の中ではそういった形で答弁させていただいているとは認識しておりますけれども、その後、具体的に変更するというような流れには。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"こちらは賛成したいけれど、こちらは賛成しかねるみたいなときがあったりするので、ぜひ考えていただきたいということを求めたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"２３区は高いほうだと思うのですけれども、歳入不足という現実を考えると、この勧告の趣旨はどうなのかと私は思います。私は品川区特別職報酬等審議会に今後しっかり考えてほしいということと、しっかり民間の生活、しっかりした勧告をしていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"今さらの質問かもしれないですけれども、１点お伺いしたいのが、その辺は実際どうなのか。駄目だったというふうに見られるのかと思うのだけど、その辺の相関関係といいましょうか、もし教えていただければ。","respondent":"崎村人事課長","answer":"上から４番目の成績を取った者について何％という形で上乗せして支給しているところですけれども、パーセンテージにつきましては年度によってばらつきがありますので一概にお答えはできないですけれども、手当に反映させるといったことで取り組んでいるところです。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"あてがうと言ったら失礼ですけれども、かぶせることができるところなので、それはしっかりとやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"質問","question":"品川区の場合というのは２３区、３月のときに１年分のものを調整するというか、今年度の分はやらないのですか。その辺がもし分かれば。","respondent":"崎村人事課長","answer":"先日、支給月数の引下げを勧告どおり実施するのですけれども、来年６月の期末手当から減額するといったところで調整していると伺っております。都道府県の中にも、例えば鹿児島県や岡山県は、１２月の実施を見送って来年６月にするというところで聞いているのですけれども。","id":"exchange-016"},{"speaker":"たけうち副委員長","kind":"意見","question":"意見だけです。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"おくの委員","kind":"意見","question":"より厳しく見ていくべきだという意見を申し上げながら、賛成致しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問・要望","question":"賛成は致します。ただやはり、より厳しく見ていただきたいという意見は申し上げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問・要望","question":"これも、労使の合意を尊重して賛成いたしますが、ただ先ほども申しましたように、対応改善に向けて話合いを積み重ねていっていただきたいという意見を申し述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"第６５号議案 品川区組織条例の一部を改正する条例","agenda":"第６５号議案 品川区組織条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"あるならば、新旧対照表にある文化スポーツ振興部の（４）を削るだけなら分かるのですが、（３）に「および振興」という文言を加えられた。","respondent":"佐藤（憲）企画調整課長","answer":"（３）には「スポーツの推進に関すること」という文言がありまして、区としては従来から条例化しており推進してきたところであります。スポーツの振興、スポーツと品川区全体を盛り上げていくというところで、そういった意味で追加しているものです。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2214#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":14996,"voices":111}},{"id":"r03-20211130-6","meetingId":"r03-cm11","date":"2021年11月30日","dateIso":"2021-11-30","committee":"区民委員会","time":"午前１０時００分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"区民葬儀協力火葬料金料改","agenda":"区民葬儀協力火葬料金料改","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、幾つかお伺いしますが、それぞれの料金が増えるわけですけれども、区民全体では総額幾らの負担増となるのか伺いたいと思います。激変緩和措置ということですが、これは何年間実施されるのか、それぞれご説明ほしいと求めました。","respondent":"木村戸籍住民課長","answer":"この値上げに伴います区民全体の負担額につきましては、令和２年度の実績で９２人なので、６,５００円掛ける９２で約６０万円という形になります。考えられることといたしますと、全体の経費が上がるというような動きが何かない限りは、このまま続くという認識でおります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"区民全体の負担は６０万円ということでよろしかったですか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"６０万円ということですけれども、区民の負担増にならないようにすることなどは検討されなかったのか、経過を伺いたいと思います。少し分からないので教えていただきたいのですが、この辺がどうなっているのかということと、あわせてご説明ほしいと求めました。","respondent":"木村戸籍住民課長","answer":"東京２３区で協定として行っているというところでございまして、独自に区がという考えは、今のところございません。いわゆる死亡届につきましても、そちらのほうで、いわゆるご案内はそういう経由でされるというところで認識しております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"その２３区の協定の中でも、要するに公費を投入して、引上げを抑えるべきだという議論をぜひ進めていただきたいと要望したいと思います。先ほどの実績は少し件数が少ないのかなとも思ったので、ほぼ区民はこのクーポン券を使えているのかどうか、最後にご説明ほしいと求めました。","respondent":"木村戸籍住民課長","answer":"そのうち９２件ですので、ほとんどの方が使われていないという形です。主に流れていっているのではないかですけれども、私どもとしては選択肢の１つとして、こういう形でもご用意をしておるという形です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"内容が違うということですけれども、葬儀業者を通じて区民に選択肢として示されているのかどうか、この件数からすると疑問を感じざるを得ません。ぜひ業者と調整をしていただいて、選択できるように進めてほしいと求めましたが、この点、お伺いしたいです。","respondent":"木村戸籍住民課長","answer":"令和元年度が４８件、令和２年度が９２件ということで、令和元年度から令和２年度にかけて倍増をしております。この制度のＰＲというのですか、それも続けながら、選択肢の１つとして選んでいただけるよう引き続き努めてまいりたいと思っています。","id":"exchange-005"}]},{"id":"topic-02","title":"１１月２２日「いい夫婦の日」の報告","agenda":"１１月２２日「いい夫婦の日」の報告","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"お尋ねしたいのが、まず(4)の東京２０２０オリンピック・パラリンピック競技大会ノベルティグッズをお配りしたという件なのですが、まずそこを１点伺います。","respondent":"木村戸籍住民課長","answer":"既に作られたものをお配りしたものです。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"東京２０２０大会が終わってそれなりの期間がたった後に、そのノベルティグッズをなぜ配ったかというのが少し疑問であります。これを配ろうと思った発想であるとか、どのような検討を経て実施することとなったのかというのを、お聞きしたいです。","respondent":"木村戸籍住民課長","answer":"新たにまた何かを買ってということよりも、有効活用ということではないのですけれども、そういう考えでお渡しをしたです。","id":"exchange-007"},{"speaker":"くにば委員","kind":"提案","question":"やっていらっしゃるかどうかは分からないのですが、それをやっているかどうかというのをまず伺いたいのが１つと、提案として。２人で写る写真を撮りたいので、ぜひ工夫をしてほしいなというところで、ご答弁をお願いしたいと思いますとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"それから、夜間受付での工夫ですけれども、今ご提案をいただいた立てかけるものであるとか、いろいろ考えていきたいなと思います。３階のほうには自撮り棒を用意していたりはするのですけれども、やはり夜間というところもございまして、いろいろ考えてまいりたいと考えています。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"今の件、ぜひともよろしくお願いします。ぜひともそれはご来庁の皆様に活用していただきたいので、何かそういったご協力というか、工夫をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"中の注釈を見ると、実際のお届けにはご使用になれませんと書いてあるとおりで、２人の記念にどうぞという取組みだと思います。伺いたいのは、同性カップルについてもご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"確かにご指摘のとおりと思います。検討の経過というのですか、私どももこのつくりにつきましては、考えていくような形になると考えています。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"今回は、９０人と去年よりも減ったけれども、どういう対策をしたのか。この９０名というのは通常より多いわけですけれども、その対応にあたっての今後の課題について、お考えがあったら説明を求めました。","respondent":"木村戸籍住民課長","answer":"当初は３階のプラッツァ、そういう工夫で考えて、そういう対策を取っておりました。そういう運営上の問題というところで、大きな課題の認識は、今のところございません。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"いつもカウンターの内のところにいる方まで、外に出てやってくださったではないですか。私は対策の１つで、私はそれが対策の１つだと思うのですけれども、どうでしょう。","respondent":"木村戸籍住民課長","answer":"それぞれに何か不具合なところがあれば、駆けつけて対応するというような、そういう形で対応してまいりました。基本的に委託スタッフと一緒に、入り口のところで対応したです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ハッピーな気持ちで手続きを進めていただきたいと思うのですけれども、今の区職員と委託業者のやり取りは、偽装請負にはならないのですか。先ほどの説明だと、指示系統がもろ偽装請負になってしまうと思ったので、そこの答弁だけ説明を求めました。","respondent":"木村戸籍住民課長","answer":"少し言葉足らずで申し訳ございませんでした。基本的には、役割分担は明確に分けておりまして、事前に責任者を通じて、その場でのああしろ、こうしろという感じの指示は、一切行っておりません。","id":"exchange-013"},{"speaker":"新妻副委員長","kind":"質問","question":"オリジナル婚姻届について少しお伺いします。今のままでも十分すてきなものだと思うのですけれども、今後のもし計画がありましたら説明を求めました。","respondent":"木村戸籍住民課長","answer":"平成２９年からお配りをしておるところです。今もお話をいただいたところですので、何か考えられるところがあれば、取り組んでまいりたいと考えています。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"特に変更してくださいということではなくて、とてもいいものだと考えていますので、今後も続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"西村委員","kind":"確認","question":"そういったフォローアップがあるのか伺いたいなというのと、あと保育課とかで進んでいるリアルタイムの混雑状況の確認みたいなものがあるのか。３階に行きますと、画面で見るものはあるのですが、スマートフォンとかで今確認できるようになっているのか、あわせて説明を求めました。","respondent":"木村戸籍住民課長","answer":"現在はスマホへの転送という形はありません。今、いわゆる委員が今おっしゃったそういうやり方、病院とかでよくあるような、メールが届くとか、そういう形の仕組みを、検討しておるところです。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問","question":"その場で記入漏れがあって、その場で完結しない、証人のことであったり、例えば旧姓が分からないとかであっても、その日中に、１１月２２日の日付で受理することができるという意味か尋ねました。","respondent":"木村戸籍住民課長","answer":"申し訳ございません。いわゆる証人がいないので書いてきてくださいという形になってしまいますと、その日中に受け付けるというのは……。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":9873,"voices":46}}]);
